// src/components/tuner/PianoKeyboard.tsx — 88-key canvas keyboard with subscription gating
// FIX: Uses refs for Zustand values to prevent rAF restart on every state change.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { useAuthStore } from '../../store/authStore';

const NOTE_NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'];
const WHITE_NOTES_IN_OCTAVE = [0, 2, 4, 5, 7, 9, 11]; // C D E F G A B
const BLACK_NOTES_IN_OCTAVE = [1, 3, 6, 8, 10]; // C# D# F# G# A#

const FREE_RANGE = { low: 48, high: 72 }; // C3–C5
const FULL_RANGE = { low: 21, high: 108 }; // A0–C8

export function PianoKeyboard({ className }: { className?: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const tunerRef = useRef(useTunerStore.getState());
  const authRef = useRef(useAuthStore.getState());

  // Keep refs in sync — does NOT restart animation
  tunerRef.current = useTunerStore();
  authRef.current = useAuthStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      // Read from refs — no closure dependency
      const { noteNum, isActive } = tunerRef.current;
      const { subscriptionTier } = authRef.current;
      const isFullAccess = subscriptionTier === 'plus' || subscriptionTier === 'pro';

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      const range = isFullAccess ? FULL_RANGE : FREE_RANGE;

      // Count white and black keys
      let whiteCount = 0;
      for (let n = range.low; n <= range.high; n++) {
        if (!BLACK_NOTES_IN_OCTAVE.includes(n % 12)) whiteCount++;
      }

      const whiteWidth = w / whiteCount;
      const blackWidth = whiteWidth * 0.6;
      const whiteHeight = h;
      const blackHeight = h * 0.62;

      // Clear
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      // Draw white keys
      let wx = 0;

      for (let n = range.low; n <= range.high; n++) {
        const noteInOctave = n % 12;
        const isBlack = BLACK_NOTES_IN_OCTAVE.includes(noteInOctave);

        if (!isBlack) {
          const isActiveNote = isActive && noteNum === n;

          ctx.fillStyle = isActiveNote ? '#164e38' : '#f8fafc';
          ctx.fillRect(wx, 0, whiteWidth - 1, whiteHeight - 2);

          ctx.strokeStyle = '#94a3b8';
          ctx.lineWidth = 0.5;
          ctx.strokeRect(wx, 0, whiteWidth - 1, whiteHeight - 2);

          if (isActiveNote) {
            ctx.save();
            ctx.shadowColor = '#22c55e';
            ctx.shadowBlur = 15;
            ctx.fillStyle = '#22c55e';
            ctx.fillRect(wx + 1, whiteHeight * 0.7, whiteWidth - 3, 4);
            ctx.restore();
          }

          if (noteInOctave === 0) {
            ctx.fillStyle = isActiveNote ? '#22c55e' : '#64748b';
            ctx.font = `${Math.max(8, Math.min(10, whiteWidth * 0.35))}px "Exo 2", sans-serif`;
            ctx.textAlign = 'center';
            ctx.fillText(`C${Math.floor(n / 12) - 1}`, wx + whiteWidth / 2, whiteHeight - 6);
          }

          wx += whiteWidth;
        }
      }

      // Draw black keys on top
      wx = 0;
      for (let n = range.low; n <= range.high; n++) {
        const noteInOctave = n % 12;
        const isBlack = BLACK_NOTES_IN_OCTAVE.includes(noteInOctave);

        if (isBlack) {
          const isActiveNote = isActive && noteNum === n;

          ctx.fillStyle = isActiveNote ? '#166534' : '#1e293b';
          const bx = wx - blackWidth / 2;

          const br = 2;
          ctx.beginPath();
          ctx.moveTo(bx + br, 0);
          ctx.lineTo(bx + blackWidth - br, 0);
          ctx.quadraticCurveTo(bx + blackWidth, 0, bx + blackWidth, br);
          ctx.lineTo(bx + blackWidth, blackHeight - br);
          ctx.quadraticCurveTo(bx + blackWidth, blackHeight, bx + blackWidth - br, blackHeight);
          ctx.lineTo(bx + br, blackHeight);
          ctx.quadraticCurveTo(bx, blackHeight, bx, blackHeight - br);
          ctx.lineTo(bx, br);
          ctx.quadraticCurveTo(bx, 0, bx + br, 0);
          ctx.closePath();
          ctx.fill();

          if (isActiveNote) {
            ctx.save();
            ctx.shadowColor = '#22c55e';
            ctx.shadowBlur = 12;
            ctx.fillStyle = '#22c55e';
            ctx.fillRect(bx + 2, blackHeight - 6, blackWidth - 4, 3);
            ctx.restore();
          }

          ctx.strokeStyle = '#0f172a';
          ctx.lineWidth = 1;
          ctx.stroke();
        } else {
          wx += whiteWidth;
        }
      }

      // Show locked range indicator for free tier
      if (!isFullAccess) {
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';

        // Left lock overlay
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.fillRect(0, 0, 28, h);
        ctx.fillStyle = '#94a3b8';
        ctx.fillText('🔒', 14, h / 2 + 4);

        // Right lock overlay
        ctx.fillRect(w - 28, 0, 28, h);
        ctx.fillText('🔒', w - 14, h / 2 + 4);
      }

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []); // Empty deps — loop runs forever, reads values from refs

  const isFullAccess = authRef.current.subscriptionTier === 'plus' || authRef.current.subscriptionTier === 'pro';

  return (
    <div className={`relative w-full ${className || ''}`}>
      <canvas
        ref={canvasRef}
        className="w-full h-14 sm:h-18 rounded-lg border border-slate-800"
      />
      {!isFullAccess && (
        <div className="absolute top-1 left-1/2 -translate-x-1/2 bg-slate-800/90 px-2 py-0.5 rounded text-[10px] text-slate-400 border border-slate-700">
          Free: C3–C5 · <button
            onClick={() => useAuthStore.getState().setTier('plus')}
            className="text-cyan-400 hover:text-cyan-300"
          >
            Unlock full 88 keys
          </button>
        </div>
      )}
    </div>
  );
}