// src/components/settings/SettingsPanel.tsx — Slide-over settings panel

import { useSettingsStore } from '../../store/settingsStore';
import { useAuthStore } from '../../store/authStore';

export function SettingsPanel({ onClose }: { onClose: () => void }) {
  const { referenceA, tuningMode, sensitivity, setReferenceA, setTuningMode, setSensitivity } = useSettingsStore();
  const { subscriptionTier, isAuthenticated, email } = useAuthStore();
  const isPlus = subscriptionTier === 'plus' || subscriptionTier === 'pro';

  return (
    <div className="fixed inset-0 z-40 flex">
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/60" onClick={onClose} />

      {/* Panel */}
      <div className="relative ml-auto w-full max-w-sm bg-slate-900 border-l border-slate-800 h-full overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-800">
          <h2 className="text-lg font-bold font-['Orbitron'] text-slate-100">Settings</h2>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-slate-200 transition-colors"
          >
            ✕
          </button>
        </div>

        {/* Sections */}
        <div className="p-4 space-y-6">
          {/* Account */}
          <section>
            <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3">Account</h3>
            <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700/50">
              {isAuthenticated ? (
                <div className="space-y-2">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-cyan-500/20 flex items-center justify-center text-cyan-400 font-bold text-sm">
                      {(email || 'U')[0].toUpperCase()}
                    </div>
                    <div>
                      <div className="text-sm font-medium text-slate-200">{email?.split('@')[0]}</div>
                      <div className="text-xs text-slate-400">{email}</div>
                    </div>
                  </div>
                  <div className="mt-2 flex items-center gap-2">
                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                      subscriptionTier === 'pro' ? 'bg-amber-500/20 text-amber-400 border border-amber-500/30' :
                      subscriptionTier === 'plus' ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30' :
                      'bg-slate-700 text-slate-400'
                    }`}>
                      {subscriptionTier === 'pro' ? '★ PRO' : subscriptionTier === 'plus' ? 'PLUS' : 'FREE'}
                    </span>
                  </div>
                </div>
              ) : (
                <p className="text-sm text-slate-400">Sign in to unlock Plus and Pro features.</p>
              )}
            </div>
          </section>

          {/* Reference Pitch */}
          <section>
            <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3">Reference Pitch</h3>
            <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700/50">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-slate-300">A4 Frequency</span>
                <span className="text-lg font-bold font-['Share_Tech_Mono'] text-cyan-400">{referenceA} Hz</span>
              </div>
              <input
                type="range"
                min="415"
                max="466"
                step="0.1"
                value={referenceA}
                onChange={(e) => setReferenceA(parseFloat(e.target.value))}
                className="w-full accent-cyan-500"
              />
              <div className="flex justify-between text-[10px] text-slate-500 mt-1">
                <span>415 Hz</span>
                <span>440 Hz</span>
                <span>466 Hz</span>
              </div>
            </div>
          </section>

          {/* Sensitivity */}
          <section>
            <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3">Sensitivity</h3>
            <div className="grid grid-cols-3 gap-2">
              {(['slow', 'normal', 'fast'] as const).map((s) => (
                <button
                  key={s}
                  onClick={() => setSensitivity(s)}
                  className={`py-2.5 rounded-xl text-sm font-medium transition-colors ${
                    sensitivity === s
                      ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                      : 'bg-slate-800/50 text-slate-400 border border-slate-700/50 hover:bg-slate-700/50'
                  }`}
                >
                  {s.charAt(0).toUpperCase() + s.slice(1)}
                </button>
              ))}
            </div>
            <p className="text-[10px] text-slate-500 mt-2">
              {sensitivity === 'slow' ? 'Smoothing: heavy (stable, good for beginners)' :
               sensitivity === 'fast' ? 'Smoothing: light (responsive, for experienced tuners)' :
               'Smoothing: balanced'}
            </p>
          </section>

          {/* Stretch Tuning (Plus) */}
          <section>
            <div className="flex items-center gap-2 mb-3">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500">Stretch Tuning</h3>
              {!isPlus && (
                <span className="text-[9px] px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-400 border border-amber-500/30 font-bold">PLUS</span>
              )}
            </div>
            <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700/50">
              {isPlus ? (
                <>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-sm text-slate-300">
                      {tuningMode === 'stretch' ? 'Railsback Stretch' : 'Equal Temperament'}
                    </span>
                    <button
                      onClick={() => setTuningMode(tuningMode === 'stretch' ? 'equal' : 'stretch')}
                      className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                        tuningMode === 'stretch' ? 'bg-cyan-500' : 'bg-slate-600'
                      }`}
                    >
                      <span className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                        tuningMode === 'stretch' ? 'translate-x-6' : 'translate-x-1'
                      }`} />
                    </button>
                  </div>
                  <p className="text-xs text-slate-400">
                    {tuningMode === 'stretch'
                      ? 'Bass notes slightly flat, treble slightly sharp — matching natural string inharmonicity.'
                      : 'Standard 12th-root-of-2 equal temperament. Toggle on for professional stretch tuning.'}
                  </p>
                </>
              ) : (
                <p className="text-xs text-slate-400">Unlock the Railsback stretch tuning curve for professional-grade equal temperament. Available in Plus and Pro plans.</p>
              )}
            </div>
          </section>

          {/* About */}
          <section>
            <h3 className="text-xs font-bold uppercase tracking-wider text-slate-500 mb-3">About</h3>
            <div className="bg-slate-800/50 rounded-xl p-4 border border-slate-700/50 text-xs text-slate-400 space-y-1">
              <div>KeyTune v1.0.0</div>
              <div>Pitch detection: YIN autocorrelation</div>
              <div>Audio: Web Audio API @ 44.1kHz</div>
              <div className="pt-2 text-slate-500">
                Professional piano tuning assistant.
                <br />Not a substitute for a trained ear.
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
}