// src/components/tuner/TuningCurveChart.tsx — Railsback deviation curve across 88 keys
// Shows cents offset per key: bass flat, treble sharp. Marks the currently detected note.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { useSettingsStore } from '../../store/settingsStore';
import { RAILSBACK } from '../../audio/StretchTuning';

const NOTE_NAMES = ['A','A♯','B','C','C♯','D','D♯','E','F','F♯','G','G♯'];

export function TuningCurveChart() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);

  const storeRef = useRef(useTunerStore.getState());
  const settingsRef = useRef(useSettingsStore.getState());
  storeRef.current = useTunerStore();
  settingsRef.current = useSettingsStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      // Background
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      const { isActive, noteNum } = storeRef.current;
      const { tuningMode } = settingsRef.current;
      const isStretch = tuningMode === 'stretch';

      const padding = { left: 28, right: 8, top: 14, bottom: 18 };
      const chartW = w - padding.left - padding.right;
      const chartH = h - padding.top - padding.bottom;
      const maxCents = 15; // ±15 cents scale

      // Grid lines
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 0.5;
      ctx.fillStyle = '#475569';
      ctx.font = '7px "Share Tech Mono", monospace';

      // Cents grid
      for (let c = -15; c <= 15; c += 5) {
        const y = padding.top + chartH * (1 - (c + maxCents) / (2 * maxCents));
        ctx.beginPath();
        ctx.moveTo(padding.left, y);
        ctx.lineTo(w - padding.right, y);
        ctx.stroke();
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(`${c > 0 ? '+' : ''}${c}¢`, padding.left - 3, y);
      }

      // Zero line
      const zeroY = padding.top + chartH * 0.5;
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding.left, zeroY);
      ctx.lineTo(w - padding.right, zeroY);
      ctx.stroke();

      // Key labels (A0, C4, C8 boundaries)
      const keyLabels = [
        { key: 0, name: 'A0' },
        { key: 27, name: 'C4' },
        { key: 87, name: 'C8' },
      ];
      ctx.fillStyle = '#475569';
      ctx.font = '6px "Share Tech Mono", monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      keyLabels.forEach(({ key, name }) => {
        const x = padding.left + (key / 87) * chartW;
        ctx.fillText(name, x, h - padding.bottom + 5);
        ctx.strokeStyle = '#1e293b80';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(x, padding.top);
        ctx.lineTo(x, h - padding.bottom);
        ctx.stroke();
      });

      // Draw equal temperament line (0 cents, straight)
      ctx.beginPath();
      ctx.moveTo(padding.left, zeroY);
      ctx.lineTo(padding.left + chartW, zeroY);
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 4]);
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw Railsback curve
      ctx.beginPath();
      const firstValid = RAILSBACK.findIndex(v => v !== 0);
      let started = false;
      for (let i = 0; i < 88; i++) {
        const offset = RAILSBACK[i];
        const x = padding.left + (i / 87) * chartW;
        const y = padding.top + chartH * (1 - (offset + maxCents) / (2 * maxCents));
        if (!started) { ctx.moveTo(x, y); started = true; }
        else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = isStretch ? '#06b6d4' : '#475569';
      ctx.lineWidth = isStretch ? 2 : 1.5;
      ctx.stroke();

      // Fill area under curve when stretch is active
      if (isStretch) {
        const grad = ctx.createLinearGradient(0, padding.top, 0, h - padding.bottom);
        grad.addColorStop(0, 'rgba(6, 182, 212, 0.15)');
        grad.addColorStop(0.5, 'rgba(6, 182, 212, 0.02)');
        grad.addColorStop(1, 'rgba(6, 182, 212, 0.15)');

        ctx.beginPath();
        for (let i = 0; i < 88; i++) {
          const offset = RAILSBACK[i];
          const x = padding.left + (i / 87) * chartW;
          const y = padding.top + chartH * (1 - (offset + maxCents) / (2 * maxCents));
          if (i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        }
        // Close to zero line
        ctx.lineTo(padding.left + chartW, zeroY);
        ctx.lineTo(padding.left, zeroY);
        ctx.closePath();
        ctx.fillStyle = grad;
        ctx.fill();
      }

      // Mark current note if active
      if (isActive && noteNum !== null && noteNum >= 21 && noteNum <= 108) {
        const keyIdx = noteNum - 21;
        const offset = RAILSBACK[keyIdx] || 0;
        const x = padding.left + (keyIdx / 87) * chartW;
        const y = padding.top + chartH * (1 - (offset + maxCents) / (2 * maxCents));

        // Vertical highlight
        ctx.strokeStyle = 'rgba(234, 179, 8, 0.4)';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x, padding.top);
        ctx.lineTo(x, h - padding.bottom);
        ctx.stroke();

        // Dot on curve
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fillStyle = '#eab308';
        ctx.shadowColor = '#eab308';
        ctx.shadowBlur = 8;
        ctx.fill();
        ctx.shadowBlur = 0;

        // Note label
        const noteName = NOTE_NAMES[noteNum % 12];
        const octave = Math.floor(noteNum! / 12) - 1;
        ctx.fillStyle = '#eab308';
        ctx.font = 'bold 8px "Share Tech Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        ctx.fillText(`${noteName}${octave}`, x, padding.top - 1);
      }

      // Title + mode
      ctx.fillStyle = '#94a3b8';
      ctx.font = 'bold 8px "Exo 2", sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(isStretch ? '⟡ Stretch' : 'Equal', padding.left, 2);

      ctx.fillStyle = isStretch ? '#06b6d4' : '#475569';
      ctx.font = '7px "Exo 2", sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText('88 keys', w - padding.right, 4);

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-full rounded-lg border border-slate-800"
    />
  );
}