// src/components/calibration/CalibrationResultsPanel.tsx — Shown after calibration completes: diagnosis summary, save profile, start tuning

import { useState } from 'react';
import { useCalibrationStore, FlaggedKey } from '../../store/calibrationStore';
import { SaveProfilePanel } from './SaveProfilePanel';

const MIDI_OFFSET = 21;
const TOTAL_KEYS = 88;
const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

function midiToNoteName(midi: number): string {
  const name = NOTE_NAMES[midi % 12];
  const octave = Math.floor(midi / 12) - 1;
  return `${name}${octave}`;
}

export function CalibrationResultsPanel({ onStartTuning, onRecalibrate }: {
  onStartTuning: () => void;
  onRecalibrate: () => void;
}) {
  const { soundPrints, flaggedKeys, calibrationCompletedAt } = useCalibrationStore();
  const [showSavePanel, setShowSavePanel] = useState(false);
  const [savedProfileId, setSavedProfileId] = useState<string | null>(null);

  const capturedCount = Object.keys(soundPrints).length;
  const okCount = capturedCount - flaggedKeys.length;
  const highFlags = flaggedKeys.filter(f => f.level === 'high');
  const moderateFlags = flaggedKeys.filter(f => f.level === 'moderate');

  if (showSavePanel) {
    return (
      <SaveProfilePanel
        onClose={() => setShowSavePanel(false)}
        onSaved={(id) => { setSavedProfileId(id); setShowSavePanel(false); }}
      />
    );
  }

  return (
    <div className="fixed inset-0 z-50 bg-[#020617] overflow-y-auto">
      <div className="max-w-lg mx-auto p-4 pb-8 flex flex-col" style={{ gap: '12px' }}>
        {/* Success header */}
        <div className="text-center py-4">
          <div className="text-4xl mb-2">✅</div>
          <h1 className="text-lg font-bold font-['Orbitron'] text-cyan-400 tracking-wider">
            CALIBRATION COMPLETE
          </h1>
          <p className="text-xs text-slate-400 mt-1">
            {capturedCount} of {TOTAL_KEYS} keys recorded
          </p>
          {calibrationCompletedAt && (
            <p className="text-[10px] text-slate-500 mt-1">
              {new Date(calibrationCompletedAt).toLocaleString()}
            </p>
          )}
        </div>

        {/* Diagnosis summary */}
        <div className="bg-slate-800/30 rounded-xl border border-slate-700/30 p-4">
          <div className="grid grid-cols-3 gap-3 text-center">
            <div>
              <div className="text-2xl font-bold text-green-400 font-['Orbitron']">{okCount}</div>
              <div className="text-[10px] text-slate-400 uppercase tracking-wider">OK</div>
            </div>
            <div>
              <div className="text-2xl font-bold text-amber-400 font-['Orbitron']">{moderateFlags.length}</div>
              <div className="text-[10px] text-slate-400 uppercase tracking-wider">Moderate</div>
            </div>
            <div>
              <div className="text-2xl font-bold text-red-400 font-['Orbitron']">{highFlags.length}</div>
              <div className="text-[10px] text-slate-400 uppercase tracking-wider">High Priority</div>
            </div>
          </div>
        </div>

        {/* Flagged keys detail */}
        {flaggedKeys.length > 0 && (
          <div className="bg-slate-800/30 rounded-xl border border-slate-700/30 p-4">
            <h2 className="text-xs font-bold text-amber-400 uppercase tracking-wider mb-3">
              ⚠ Keys Needing Attention
            </h2>
            <div className="space-y-2">
              {flaggedKeys.map(fk => (
                <div
                  key={fk.midiNote}
                  className="flex items-center justify-between bg-slate-900/50 rounded-lg px-3 py-2 border border-slate-700/20"
                >
                  <div>
                    <span className="font-bold font-['Orbitron'] text-slate-200 text-sm">
                      {fk.noteName}{fk.octave}
                    </span>
                  </div>
                  <div className="text-right">
                    <div className={`text-xs capitalize ${fk.level === 'high' ? 'text-red-400' : 'text-amber-400'}`}>
                      {fk.issues.join(', ').replace(/_/g, ' ')}
                    </div>
                    <span className={`text-[10px] font-bold ${
                      fk.level === 'high' ? 'text-red-400' : 'text-amber-400'
                    }`}>
                      {fk.level.toUpperCase()}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Sound print highlights — keys furthest from target */}
        {Object.keys(soundPrints).length > 0 && (
          <div className="bg-slate-800/30 rounded-xl border border-slate-700/30 p-4">
            <h2 className="text-xs font-bold text-cyan-400 uppercase tracking-wider mb-2">
              📊 Sound Print Summary
            </h2>
            <div className="text-xs text-slate-400 space-y-1">
              {(() => {
                const prints = Object.values(soundPrints);
                const avgCents = prints.reduce((s, p) => s + Math.abs(p.cents), 0) / prints.length;
                const worstKey = prints.reduce((worst, p) => Math.abs(p.cents) > Math.abs(worst.cents) ? p : worst, prints[0]);
                const avgDecay = prints.reduce((s, p) => s + p.decayMs, 0) / prints.length;
                return (
                  <>
                    <div className="flex justify-between">
                      <span>Average deviation</span>
                      <span className="text-slate-200">{avgCents.toFixed(1)}¢</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Worst key</span>
                      <span className="text-slate-200">{worstKey.noteName}{worstKey.octave} ({worstKey.cents > 0 ? '+' : ''}{worstKey.cents.toFixed(1)}¢)</span>
                    </div>
                    <div className="flex justify-between">
                      <span>Avg decay time</span>
                      <span className="text-slate-200">{(avgDecay / 1000).toFixed(1)}s</span>
                    </div>
                  </>
                );
              })()}
            </div>
          </div>
        )}

        {/* Action buttons */}
        <div className="space-y-3 pt-2">
          {/* Save Profile — primary action */}
          <button
            onClick={() => setShowSavePanel(true)}
            disabled={!!savedProfileId}
            className={`w-full py-3 rounded-xl text-sm font-bold transition-all ${
              savedProfileId
                ? 'bg-green-500/10 text-green-400 border border-green-500/20'
                : 'bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/25 active:bg-cyan-500/35'
            }`}
          >
            {savedProfileId ? '✅ Profile Saved' : '💾 Save Piano Profile & Invoice'}
          </button>

          <button
            onClick={onStartTuning}
            className="w-full py-3 rounded-xl text-sm font-bold bg-green-500/15 text-green-400 border border-green-500/30 hover:bg-green-500/25 active:bg-green-500/35 transition-all"
          >
            ▶ Begin Tuning Session
          </button>

          <button
            onClick={onRecalibrate}
            className="w-full py-2.5 rounded-xl text-sm font-medium bg-slate-800/30 text-slate-400 border border-slate-700/30 hover:bg-slate-800/50 transition-all"
          >
            🔄 Re-calibrate
          </button>
        </div>
      </div>
    </div>
  );
}