// src/store/tunerStore.ts — Main tuner state

import { create } from 'zustand';

export interface TunerState {
  frequency: number;
  noteNum: number | null;
  noteName: string;
  octave: number;
  cents: number;
  idealFreq: number;
  isActive: boolean;
  isListening: boolean;
  micError: string | null;

  setPitch: (freq: number, noteName: string, octave: number, noteNum: number, cents: number, idealFreq: number) => void;
  setInactive: () => void;
  setListening: (listening: boolean) => void;
  setMicError: (error: string | null) => void;
}

export const useTunerStore = create<TunerState>((set) => ({
  frequency: 0,
  noteNum: null,
  noteName: '',
  octave: 0,
  cents: 0,
  idealFreq: 0,
  isActive: false,
  isListening: false,
  micError: null,

  setPitch: (frequency, noteName, octave, noteNum, cents, idealFreq) =>
    set({ frequency, noteName, octave, noteNum, cents, idealFreq, isActive: true }),

  setInactive: () =>
    set({
      frequency: 0,
      noteName: '',
      octave: 0,
      noteNum: null,
      cents: 0,
      idealFreq: 0,
      isActive: false,
    }),

  setListening: (isListening) => set({ isListening }),

  setMicError: (micError) => set({ micError }),
}));