// src/components/session/ManualNoteEntry.tsx — Professional note logging with annotations

import { useState } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { useSessionStore, type TunedNote } from '../../store/sessionStore';
import { NOTE_NAMES } from '../../audio/NoteUtils';

interface Props {
  onClose: () => void;
  defaultNote?: string;
  defaultOctave?: number;
  defaultMidi?: number | null;
}

export function ManualNoteEntry({ onClose, defaultNote, defaultOctave, defaultMidi }: Props) {
  const { frequency, cents, idealFreq } = useTunerStore();
  const { recordNote, addSessionNote } = useSessionStore();

  const [selectedNote, setSelectedNote] = useState<string>(defaultNote || 'A');
  const [selectedOctave, setSelectedOctave] = useState(defaultOctave || 4);
  const [annotation, setAnnotation] = useState('');
  const [condition, setCondition] = useState<'good' | 'fair' | 'poor' | 'needs-repair'>('good');
  const [action, setAction] = useState<'tuned' | 'pitch-raised' | 'left-as-is' | 'needs-follow-up'>('tuned');

  const allNotes: string[] = [...NOTE_NAMES];
  const midiNote = defaultMidi ?? (selectedOctave + 1) * 12 + allNotes.indexOf(selectedNote);

  const handleSave = () => {
    // Record the tuning data
    const data: TunedNote = {
      noteName: selectedNote,
      octave: selectedOctave,
      frequency,
      cents,
      idealFreq,
      timestamp: Date.now(),
      manuallyLogged: true,
    };
    recordNote(midiNote, data);

    // Add annotation if provided
    if (annotation.trim()) {
      addSessionNote(
        `${selectedNote}${selectedOctave}: ${annotation} [${condition}, ${action}]`,
        midiNote
      );
    } else if (condition !== 'good' || action !== 'tuned') {
      addSessionNote(
        `${selectedNote}${selectedOctave}: ${condition}, ${action}`,
        midiNote
      );
    }

    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-end sm:items-center justify-center p-4">
      <div className="bg-slate-900 rounded-2xl border border-slate-700 w-full max-w-md shadow-2xl max-h-[85vh] overflow-y-auto">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-slate-800 sticky top-0 bg-slate-900 z-10">
          <h2 className="text-lg font-bold font-['Orbitron'] text-slate-100">Log Note</h2>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-slate-200 transition-colors"
          >
            ✕
          </button>
        </div>

        <div className="p-4 space-y-5">
          {/* Current reading */}
          {frequency > 0 && (
            <div className="bg-slate-800/50 rounded-xl p-3 border border-slate-700/50">
              <div className="text-[10px] text-slate-500 uppercase tracking-wider mb-1">Current Reading</div>
              <div className="flex items-center justify-between">
                <span className="text-2xl font-bold font-['Orbitron'] text-cyan-400">
                  {selectedNote}<sub className="text-sm">{selectedOctave}</sub>
                </span>
                <div className="text-right">
                  <div className="text-sm font-mono text-slate-300">{frequency.toFixed(1)} Hz</div>
                  <div className={`text-sm font-bold font-mono ${
                    Math.abs(cents) <= 2 ? 'text-green-400' : Math.abs(cents) <= 8 ? 'text-yellow-400' : 'text-red-400'
                  }`}>
                    {cents > 0 ? '+' : ''}{cents.toFixed(1)}¢
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Note selector */}
          <div>
            <label className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 block">Note</label>
            <div className="grid grid-cols-12 gap-1">
              {allNotes.map((n) => (
                <button
                  key={n}
                  onClick={() => setSelectedNote(n)}
                  className={`py-2 rounded-lg text-xs font-bold transition-colors ${
                    selectedNote === n
                      ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                      : 'bg-slate-800/50 text-slate-400 border border-slate-700/30 hover:bg-slate-700/50'
                  }`}
                >
                  {n}
                </button>
              ))}
            </div>
          </div>

          {/* Octave selector */}
          <div>
            <label className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 block">Octave</label>
            <div className="grid grid-cols-8 gap-1">
              {[0,1,2,3,4,5,6,7].map((o) => (
                <button
                  key={o}
                  onClick={() => setSelectedOctave(o)}
                  className={`py-2 rounded-lg text-sm font-bold transition-colors ${
                    selectedOctave === o
                      ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                      : 'bg-slate-800/50 text-slate-400 border border-slate-700/30 hover:bg-slate-700/50'
                  }`}
                >
                  {o}
                </button>
              ))}
            </div>
          </div>

          {/* String condition */}
          <div>
            <label className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 block">String Condition</label>
            <div className="grid grid-cols-4 gap-2">
              {[
                { id: 'good', label: 'Good', color: 'green' },
                { id: 'fair', label: 'Fair', color: 'yellow' },
                { id: 'poor', label: 'Poor', color: 'orange' },
                { id: 'needs-repair', label: 'Repair', color: 'red' },
              ].map(({ id, label, color }) => (
                <button
                  key={id}
                  onClick={() => setCondition(id as any)}
                  className={`py-2 rounded-lg text-xs font-medium transition-colors ${
                    condition === id
                      ? `bg-${color}-500/20 text-${color}-400 border border-${color}-500/30`
                      : 'bg-slate-800/50 text-slate-400 border border-slate-700/30 hover:bg-slate-700/50'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>

          {/* Action taken */}
          <div>
            <label className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 block">Action Taken</label>
            <div className="grid grid-cols-2 gap-2">
              {[
                { id: 'tuned', label: '♪ Tuned' },
                { id: 'pitch-raised', label: '↑ Pitch Raised' },
                { id: 'left-as-is', label: '━ Left As-Is' },
                { id: 'needs-follow-up', label: '⚠ Follow-up' },
              ].map(({ id, label }) => (
                <button
                  key={id}
                  onClick={() => setAction(id as any)}
                  className={`py-2 rounded-lg text-xs font-medium transition-colors ${
                    action === id
                      ? 'bg-cyan-500/20 text-cyan-400 border border-cyan-500/30'
                      : 'bg-slate-800/50 text-slate-400 border border-slate-700/30 hover:bg-slate-700/50'
                  }`}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>

          {/* Annotation */}
          <div>
            <label className="text-[10px] text-slate-500 uppercase tracking-wider mb-2 block">Notes / Annotation</label>
            <textarea
              value={annotation}
              onChange={(e) => setAnnotation(e.target.value)}
              placeholder="e.g. Sticky key, replaced string, pin tight, false beat on 3rd partial..."
              className="w-full px-3 py-2 bg-slate-800 border border-slate-600 rounded-xl text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-sm resize-none h-20"
            />
          </div>

          {/* Save button */}
          <button
            onClick={handleSave}
            className="w-full py-3 rounded-xl bg-green-500 text-white font-bold text-sm hover:bg-green-600 transition-colors shadow-lg shadow-green-500/20 flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
            </svg>
            Log {selectedNote}{selectedOctave} to Session
          </button>
        </div>
      </div>
    </div>
  );
}