// src/hooks/useInstallPrompt.ts — PWA beforeinstallprompt handler

import { useState, useEffect } from 'react';

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export function useInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isDismissed, setIsDismissed] = useState(false);

  useEffect(() => {
    const handler = (e: Event) => {
      e.preventDefault();
      console.log('[PWA] beforeinstallprompt captured');
      setDeferredPrompt(e as BeforeInstallPromptEvent);
    };
    window.addEventListener('beforeinstallprompt', handler);

    const installedHandler = () => {
      console.log('[PWA] appinstalled event');
      setIsInstalled(true);
      setDeferredPrompt(null);
      localStorage.setItem('pwa-installed', '1');
    };
    window.addEventListener('appinstalled', installedHandler);

    // Check if already in standalone mode or was previously installed
    const isStandalone = window.matchMedia('(display-mode: standalone)').matches
      || (navigator as any).standalone === true;
    if (isStandalone || localStorage.getItem('pwa-installed')) {
      setIsInstalled(true);
    }
    if (sessionStorage.getItem('install-dismissed')) {
      setIsDismissed(true);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('appinstalled', installedHandler);
    };
  }, []);

  const promptInstall = async () => {
    // If we have a native prompt, use it
    if (deferredPrompt) {
      console.log('[PWA] Triggering native install prompt');
      await deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setIsInstalled(true);
        localStorage.setItem('pwa-installed', '1');
      }
      setDeferredPrompt(null);
      return;
    }

    // Otherwise show fallback instructions
    const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
    if (isIOS) {
      alert('To install KeyTune:\n\n1. Tap the Share button (⬆️) at the bottom of Safari\n2. Scroll down and tap "Add to Home Screen"\n3. Tap "Add"');
    } else {
      alert('To install KeyTune:\n\n1. Open this page in Chrome\n2. Tap the three-dot menu (⋮) in the top right\n3. Tap "Install app" or "Add to Home Screen"');
    }
  };

  const dismiss = () => {
    sessionStorage.setItem('install-dismissed', '1');
    setIsDismissed(true);
  };

  // Show install button if not yet installed and not dismissed
  const shouldShowBanner = !isInstalled && !isDismissed;

  return { shouldShowBanner, promptInstall, dismiss, isInstalled };
}