// src/hooks/useAudioEngine.ts — Hook to start/stop mic and connect to analyzer store
// KEY FIX: AudioContext is created synchronously inside the click handler,
// before any async work. This is required for iOS Safari PWA.
// Mic permissions: try getUserMedia directly (triggers permission prompt),
// then show helpful message if denied.

import { useRef, useCallback } from 'react';
import { AudioEngine, prepareAudioContext, micErrorMessage, getSharedAnalyser } from '../audio/AudioEngine';
import { useTunerStore } from '../store/tunerStore';
import { useSessionStore } from '../store/sessionStore';
import { useSettingsStore } from '../store/settingsStore';
import { useCalibrationStore } from '../store/calibrationStore';
import { noteFromFrequency } from '../audio/NoteUtils';

export let engineInstance: AudioEngine | null = null;
let audioContextRef: AudioContext | null = null;

export function useAudioEngine() {
  const autoRecordTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const start = useCallback(async (ctx: AudioContext) => {
    // Clean up any previous engine
    if (engineInstance) {
      engineInstance.stop();
      engineInstance = null;
    }

    const engine = new AudioEngine();
    engineInstance = engine;

    const sensitivity = useSettingsStore.getState().sensitivity;
    const alpha = sensitivity === 'slow' ? 0.08 : sensitivity === 'fast' ? 0.3 : 0.15;
    // Reset hysteresis state so the jump filter doesn't block the first calibration key
    engine.resetHysteresis();
    engine.updateSensitivity(alpha);
    // Bypass hysteresis jump filter during calibration mode
    const calibState = useCalibrationStore.getState();
    engine.bypassHysteresis = calibState.isCalibrating;

    try {
      await engine.start(ctx, (freq) => {
        const store = useTunerStore.getState();

        if (freq < 0) {
          store.setInactive();
          return;
        }

        // Read settings dynamically so changes take effect immediately
        const { referenceA, tuningMode, calibrationOffset, noteSwitchMode } = useSettingsStore.getState();
        const useStretch = tuningMode === 'stretch';
        const info = noteFromFrequency(freq, referenceA, useStretch, calibrationOffset);

        // Note switch mode filtering
        const currentNoteNum = store.noteNum;
        if (noteSwitchMode === 'lock' && currentNoteNum !== null) {
          // Lock mode: keep the current note, only update cents/frequency
          // Recalculate cents relative to the LOCKED note's ideal frequency
          const lockedIdealFreq = referenceA * Math.pow(2, (currentNoteNum - 69) / 12);
          const lockedCents = 1200 * Math.log2(freq / lockedIdealFreq);
          const lockedInfo = noteFromFrequency(freq, referenceA, useStretch, calibrationOffset);
          // Keep the locked note name/num, update cents from the detected pitch
          store.setPitch(freq, store.noteName, store.octave, currentNoteNum, lockedCents, lockedIdealFreq);
        } else if (noteSwitchMode === 'stepwise' && currentNoteNum !== null) {
          // Stepwise mode: only allow adjacent notes (±2 semitones max)
          const distance = Math.abs(info.noteNum - currentNoteNum);
          if (distance <= 2) {
            store.setPitch(freq, info.name, info.octave, info.noteNum, info.cents, info.idealFreq);
          }
          // If jump >2, ignore the note change but still update cents for current note
          else {
            const lockedIdealFreq = referenceA * Math.pow(2, (currentNoteNum - 69) / 12);
            const lockedCents = 1200 * Math.log2(freq / lockedIdealFreq);
            store.setPitch(freq, store.noteName, store.octave, currentNoteNum, lockedCents, lockedIdealFreq);
          }
        } else {
          // Auto mode (default): accept any detected note
          store.setPitch(freq, info.name, info.octave, info.noteNum, info.cents, info.idealFreq);
        }

        // Calibration capture: if calibrating, feed notes into calibration store
        const calibState = useCalibrationStore.getState();
        if (calibState.isCalibrating && calibState.currentMidi >= 0) {
          // Accept any detected note within ±1 semitone of expected key position.
          // The point of calibration is recording WHAT the piano produces —
          // even if the key is out of tune, we still capture it at the correct slot.
          const distance = Math.abs(info.noteNum - calibState.currentMidi);
          if (distance <= 1) {
            console.log('[CALIB DEBUG] Capture — detected:', info.name, info.octave, '(' + info.noteNum + ')', 'expected midi:', calibState.currentMidi, 'distance:', distance, 'freq:', freq, 'cents:', info.cents);
            // Capture sound print for this key using the EXPECTED midi position
            const analyser = getSharedAnalyser();
            if (analyser) {
              const floatData = new Float32Array(analyser.fftSize);
              analyser.getFloatTimeDomainData(floatData);
              const peakAmp = Math.max(...Array.from(floatData.map(Math.abs)));
              const normalizedAmp = Math.min(peakAmp, 1);

              const sampleRate = ctx.sampleRate;
              const rmsValues: number[] = [];
              const windowSize = Math.floor(sampleRate * 0.02);
              for (let i = 0; i < floatData.length - windowSize; i += windowSize) {
                let rms = 0;
                for (let j = i; j < i + windowSize && j < floatData.length; j++) {
                  rms += floatData[j] * floatData[j];
                }
                rmsValues.push(Math.sqrt(rms / windowSize));
              }
              const peakRms = Math.max(...rmsValues);
              const decayThreshold = peakRms * 0.1;
              let decayMs = 2000;
              const peakIdx = rmsValues.indexOf(peakRms);
              for (let i = peakIdx + 1; i < rmsValues.length; i++) {
                if (rmsValues[i] < decayThreshold) {
                  decayMs = ((i - peakIdx) * 20);
                  break;
                }
              }

              const freqData = new Uint8Array(analyser.frequencyBinCount);
              analyser.getByteFrequencyData(freqData);
              const binWidth = sampleRate / analyser.fftSize;
              const fundamental = freq;
              let inharmonicity = 0;
              for (let h = 2; h <= 8; h++) {
                const partialFreq = fundamental * h;
                const bin = Math.round(partialFreq / binWidth);
                let peakBin = bin;
                let peakVal = 0;
                const searchRange = Math.max(3, Math.round(fundamental / binWidth));
                for (let b = bin - searchRange; b <= bin + searchRange && b < freqData.length; b++) {
                  if (b >= 0 && freqData[b] > peakVal) {
                    peakVal = freqData[b];
                    peakBin = b;
                  }
                }
                if (peakVal > 30) {
                  const centsDev = 1200 * Math.log2((peakBin * binWidth) / partialFreq);
                  inharmonicity += Math.abs(centsDev);
                }
              }
              inharmonicity = Math.min(inharmonicity / 700, 1);

              let beating = 0;
              if (rmsValues.length > 4) {
                const peaks: number[] = [];
                const valleys: number[] = [];
                for (let i = 1; i < rmsValues.length - 1; i++) {
                  if (rmsValues[i] > rmsValues[i-1] && rmsValues[i] > rmsValues[i+1]) peaks.push(rmsValues[i]);
                  if (rmsValues[i] < rmsValues[i-1] && rmsValues[i] < rmsValues[i+1]) valleys.push(rmsValues[i]);
                }
                if (peaks.length > 1) {
                  beating = (peaks.length * 50) / (rmsValues.length);
                }
              }

              calibState.captureKey({
                midiNote: calibState.currentMidi, // Use EXPECTED key position
                noteName: info.name,
                octave: info.octave,
                frequency: freq,
                cents: info.cents,
                idealFreq: info.idealFreq,
                inharmonicity,
                decayMs: decayMs,
                amplitude: normalizedAmp,
                beating,
              });
            } else {
              calibState.captureKey({
                midiNote: calibState.currentMidi,
                noteName: info.name,
                octave: info.octave,
                frequency: freq,
                cents: info.cents,
                idealFreq: info.idealFreq,
                inharmonicity: 0,
                decayMs: 2000,
                amplitude: 0.5,
                beating: 0,
              });
            }
          }
        }

        // Auto-record if enabled and within ±5¢
        const { autoRecordEnabled, recordNote } = useSessionStore.getState();
        if (autoRecordEnabled && Math.abs(info.cents) <= 5) {
          if (autoRecordTimerRef.current) {
            clearTimeout(autoRecordTimerRef.current);
          }
          const noteNum = info.noteNum;
          autoRecordTimerRef.current = setTimeout(() => {
            recordNote(noteNum, {
              noteName: info.name,
              octave: info.octave,
              frequency: freq,
              cents: info.cents,
              idealFreq: info.idealFreq,
              timestamp: Date.now(),
            });
          }, 1500);
        }
      });

      useTunerStore.getState().setListening(true);
      useTunerStore.getState().setMicError(null);
      audioContextRef = ctx;
    } catch (err: any) {
      useTunerStore.getState().setListening(false);
      let msg: string;
      if (err instanceof DOMException || err instanceof Error) {
        msg = micErrorMessage(err);
        // If permission denied, add device-specific instructions
        if (err instanceof DOMException && err.name === 'NotAllowedError') {
          const ua = navigator.userAgent.toLowerCase();
          if (ua.includes('android')) {
            msg += '\n\nOn Android Chrome:\n1. Tap the lock (🔒) icon in address bar\n2. Set Microphone → Allow\n3. Refresh the page';
          } else if (ua.includes('iphone') || ua.includes('ipad')) {
            msg += '\n\nOn iOS Safari:\n1. Tap the "aA" or lock icon in address bar\n2. Tap "Website Settings"\n3. Set Microphone → Allow\n4. Refresh the page';
          }
        }
      } else {
        msg = 'Could not start microphone';
      }
      useTunerStore.getState().setMicError(msg);
      console.error('AudioEngine error:', msg, err);
      // Clean up context on failure
      try { ctx.close(); } catch {}
      audioContextRef = null;
      throw err;
    }
  }, []);

  const stop = useCallback(() => {
    if (engineInstance) {
      engineInstance.stop();
      engineInstance = null;
    }
    if (audioContextRef) {
      try { audioContextRef.close(); } catch {}
      audioContextRef = null;
    }
    if (autoRecordTimerRef.current) {
      clearTimeout(autoRecordTimerRef.current);
      autoRecordTimerRef.current = null;
    }
    useTunerStore.getState().setListening(false);
    useTunerStore.getState().setInactive();
  }, []);

  const toggle = useCallback(async () => {
    const { isActive, isListening } = useTunerStore.getState();
    if (isActive || isListening) {
      stop();
      return;
    }

    // CRITICAL: Create AudioContext synchronously inside the user gesture.
    // iOS Safari requires this — async work (getUserMedia) breaks the gesture chain.
    const { ctx } = prepareAudioContext();
    await start(ctx);
  }, [start, stop]);

  return { start, stop, toggle, resetHysteresis: () => engineInstance?.resetHysteresis() };
}