// src/pages/SettingsPage.tsx — Settings page (standalone for navigation)

import { useSettingsStore, type TuningMode, type SensitivityLevel } from '../store/settingsStore';
import { useAuthStore } from '../store/authStore';

const REFERENCE_PITCHES = [432, 438, 440, 441, 442, 443, 444, 446];

export function SettingsPage() {
  const {
    referenceA, tuningMode, sensitivity, calibrationOffset,
    setReferenceA, setTuningMode, setSensitivity, setCalibrationOffset,
  } = useSettingsStore();
  const { subscriptionTier } = useAuthStore();
  const isPlus = subscriptionTier === 'plus' || subscriptionTier === 'pro';

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100">
      <header className="px-4 py-4 border-b border-slate-800">
        <h1 className="text-lg font-bold font-['Orbitron'] text-cyan-400">
          ⚙️ Settings
        </h1>
      </header>

      <main className="max-w-lg mx-auto px-4 py-6 space-y-6">
        {/* Reference Pitch */}
        <section className="bg-slate-800/50 rounded-xl p-4 border border-slate-700">
          <h2 className="text-sm font-bold text-slate-300 mb-3">Reference Pitch (A4)</h2>
          <div className="grid grid-cols-4 gap-2">
            {REFERENCE_PITCHES.map((hz) => (
              <button
                key={hz}
                onClick={() => setReferenceA(hz)}
                disabled={!isPlus && hz !== 440}
                className={`py-2 rounded-lg text-sm font-medium ${
                  referenceA === hz ? 'bg-cyan-500 text-white' :
                  !isPlus && hz !== 440 ? 'bg-slate-800 text-slate-600 cursor-not-allowed' :
                  'bg-slate-800 text-slate-300 hover:bg-slate-700'
                }`}
              >
                {hz} Hz
              </button>
            ))}
          </div>
        </section>

        {/* Tuning Mode */}
        <section className="bg-slate-800/50 rounded-xl p-4 border border-slate-700">
          <h2 className="text-sm font-bold text-slate-300 mb-3">Tuning Mode</h2>
          <div className="space-y-2">
            <button
              onClick={() => setTuningMode('equal')}
              className={`w-full py-3 rounded-lg text-sm font-medium text-left px-4 ${
                tuningMode === 'equal' ? 'bg-cyan-500 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
              }`}
            >
              <div className="font-bold">Equal Temperament</div>
              <div className={`text-xs ${tuningMode === 'equal' ? 'text-cyan-100' : 'text-slate-500'}`}>
                Standard 12-tone equal temperament
              </div>
            </button>
            <button
              onClick={() => setTuningMode('stretch')}
              disabled={!isPlus}
              className={`w-full py-3 rounded-lg text-sm font-medium text-left px-4 ${
                tuningMode === 'stretch' ? 'bg-cyan-500 text-white' :
                !isPlus ? 'bg-slate-800 text-slate-600 cursor-not-allowed' :
                'bg-slate-800 text-slate-300 hover:bg-slate-700'
              }`}
            >
              <div className="font-bold">{!isPlus ? '🔒 ' : ''}Stretch Tuning{isPlus ? ' ✓' : ''}</div>
              <div className={`text-xs ${tuningMode === 'stretch' ? 'text-cyan-100' : 'text-slate-500'}`}>
                Railsback curve for piano inharmonicity
              </div>
            </button>
          </div>
        </section>

        {/* Sensitivity */}
        <section className="bg-slate-800/50 rounded-xl p-4 border border-slate-700">
          <h2 className="text-sm font-bold text-slate-300 mb-3">Sensitivity</h2>
          <div className="flex gap-2">
            {(['slow', 'normal', 'fast'] as SensitivityLevel[]).map((level) => (
              <button
                key={level}
                onClick={() => setSensitivity(level)}
                className={`flex-1 py-2.5 rounded-lg text-sm font-medium capitalize ${
                  sensitivity === level ? 'bg-cyan-500 text-white' : 'bg-slate-800 text-slate-300 hover:bg-slate-700'
                }`}
              >
                {level}
              </button>
            ))}
          </div>
          <p className="text-xs text-slate-500 mt-2">
            Lower = more stable but slower. Higher = more responsive but noisier.
          </p>
        </section>

        {/* Calibration */}
        <section className="bg-slate-800/50 rounded-xl p-4 border border-slate-700">
          <h2 className="text-sm font-bold text-slate-300 mb-3">Calibration Offset</h2>
          <div className="flex items-center gap-3">
            <input
              type="range"
              min={-10}
              max={10}
              step={1}
              value={calibrationOffset}
              onChange={(e) => setCalibrationOffset(parseInt(e.target.value, 10))}
              className="flex-1 accent-cyan-500"
            />
            <span className="text-sm font-mono text-slate-300 w-12 text-right">
              {calibrationOffset >= 0 ? '+' : ''}{calibrationOffset}¢
            </span>
          </div>
        </section>
      </main>
    </div>
  );
}