// src/pages/SessionPage.tsx — Professional session history page

import { useSessionStore } from '../store/sessionStore';
import { useAuthStore } from '../store/authStore';

export function SessionPage() {
  const {
    records, sessionNotes, clientName, pianoMake, pianoModel, pianoSerial,
    sessionStartedAt, clearSession, removeNote, removeSessionNote,
  } = useSessionStore();
  const { subscriptionTier } = useAuthStore();
  const isPlus = subscriptionTier === 'plus' || subscriptionTier === 'pro';
  const entries = Object.entries(records);

  return (
    <div className="min-h-screen bg-[#020617] p-4">
      <h1 className="text-xl font-bold text-slate-100 font-['Orbitron'] mb-4">Session History</h1>

      {/* Session info card */}
      {(clientName || pianoMake || pianoSerial) && (
        <div className="mb-4 bg-slate-800/50 rounded-xl p-4 border border-slate-700/30">
          <div className="text-sm font-bold text-slate-200">{clientName || 'No client name'}</div>
          {(pianoMake || pianoModel) && <div className="text-xs text-slate-400 mt-1">{pianoMake} {pianoModel}</div>}
          {pianoSerial && <div className="text-xs text-slate-500">S/N: {pianoSerial}</div>}
          {sessionStartedAt && (
            <div className="text-[10px] text-slate-500 mt-1">
              Started: {new Date(sessionStartedAt).toLocaleString()}
            </div>
          )}
        </div>
      )}

      {/* Session notes */}
      {sessionNotes.length > 0 && (
        <div className="mb-4">
          <h2 className="text-xs text-slate-400 uppercase tracking-wider mb-2">Notes ({sessionNotes.length})</h2>
          <div className="space-y-1">
            {sessionNotes.map((n) => (
              <div key={n.id} className="flex items-start gap-2 bg-slate-800/30 rounded-lg px-3 py-2 text-xs">
                <span className="text-slate-300 flex-1">{n.text}</span>
                <button
                  onClick={() => removeSessionNote(n.id)}
                  className="text-slate-600 hover:text-red-400 transition-colors shrink-0"
                >
                  ✕
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {entries.length === 0 ? (
        <div className="text-center py-16">
          <div className="text-6xl mb-4">🎵</div>
          <p className="text-slate-400 text-sm">No notes tuned yet.</p>
          <p className="text-slate-500 text-xs mt-1">Go to the Tuner tab, start the mic, and log notes.</p>
        </div>
      ) : (
        <>
          <div className="mb-3 flex items-center justify-between">
            <span className="text-xs text-slate-400">{entries.length} notes recorded</span>
            <button
              onClick={clearSession}
              className="text-xs text-red-400 hover:text-red-300 transition-colors"
            >
              Clear all
            </button>
          </div>

          <div className="space-y-1.5">
            {entries.reverse().map(([midi, rec]) => {
              const absCents = Math.abs(rec.cents);
              const centsColor = absCents <= 2 ? 'text-green-400' : absCents <= 8 ? 'text-yellow-400' : absCents <= 20 ? 'text-orange-400' : 'text-red-400';

              return (
                <div
                  key={midi}
                  className="flex items-center justify-between bg-slate-800/50 rounded-lg px-3 py-2 border border-slate-700/30"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-lg font-bold font-['Orbitron'] text-slate-200">
                      {rec.noteName}<sub className="text-xs">{rec.octave}</sub>
                    </span>
                    <span className="text-xs text-slate-500">
                      MIDI {midi}
                      {rec.manuallyLogged && ' ✓'}
                    </span>
                  </div>
                  <div className="flex items-center gap-4">
                    <span className="text-xs font-mono text-slate-400">
                      {rec.frequency.toFixed(1)} Hz
                    </span>
                    <span className={`text-sm font-bold font-mono ${centsColor}`}>
                      {rec.cents > 0 ? '+' : ''}{rec.cents.toFixed(1)}¢
                    </span>
                    <button
                      onClick={() => removeNote(Number(midi))}
                      className="text-slate-600 hover:text-red-400 transition-colors text-sm"
                    >
                      ✕
                    </button>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="mt-6">
            <button
              onClick={() => {
                if (!isPlus) return;
                const report = {
                  client: clientName || 'Unnamed',
                  piano: { make: pianoMake, model: pianoModel, serial: pianoSerial },
                  sessionDate: sessionStartedAt ? new Date(sessionStartedAt).toISOString() : null,
                  notes: sessionNotes.map(n => ({ text: n.text, time: new Date(n.timestamp).toISOString() })),
                  tunedKeys: Object.entries(records).map(([midi, rec]) => ({
                    midi: Number(midi),
                    note: `${rec.noteName}${rec.octave}`,
                    frequency: Math.round(rec.frequency * 100) / 100,
                    cents: Math.round(rec.cents * 10) / 10,
                    manual: rec.manuallyLogged || false,
                  })),
                };
                const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `keytune-report-${new Date().toISOString().slice(0, 10)}.json`;
                a.click();
                URL.revokeObjectURL(url);
              }}
              disabled={!isPlus}
              className={`w-full py-2.5 rounded-xl text-sm font-medium transition-colors ${
                isPlus
                  ? 'bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 hover:bg-cyan-500/25'
                  : 'bg-slate-800/30 text-slate-600 cursor-not-allowed'
              }`}
            >
              {isPlus ? 'Export Full Report (JSON)' : '🔒 Export requires Plus plan'}
            </button>
          </div>
        </>
      )}
    </div>
  );
}