// src/components/auth/LoginModal.tsx — Login modal with demo account support

import { useState } from 'react';
import { validateDemoLogin, DEMO_ACCOUNTS, useAuthStore } from '../../store/authStore';

interface Props {
  open: boolean;
  onClose: () => void;
  onLogin: (email: string, tier: 'free' | 'plus' | 'pro') => void;
}

type AuthView = 'login' | 'signup' | 'forgot';

export function LoginModal({ open, onLogin, onClose }: Props) {
  const [view, setView] = useState<AuthView>('login');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!open) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      // Check demo accounts first
      const tier = validateDemoLogin(email, password);
      if (tier) {
        await new Promise(r => setTimeout(r, 400));
        useAuthStore.getState().login(email, tier);
        onLogin(email, tier);
        onClose();
        return;
      }

      // In production: Supabase auth
      // const { data, error } = await supabase.auth.signInWithPassword({ email, password })
      
      setError('Invalid email or password. Try a demo account below.');
    } catch (err: any) {
      setError(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setError(null);
    setLoading(true);

    try {
      // In production: const { data, error } = await supabase.auth.signInWithOAuth({ provider: 'google' })
      await new Promise(r => setTimeout(r, 500));
      setError('Google OAuth requires Supabase setup. Use a demo account instead.');
    } catch (err: any) {
      setError(err.message || 'Google login failed');
    } finally {
      setLoading(false);
    }
  };

  const handleDemoLogin = (demoEmail: string) => {
    const account = DEMO_ACCOUNTS[demoEmail];
    if (account) {
      useAuthStore.getState().login(demoEmail, account.tier);
      onLogin(demoEmail, account.tier);
      onClose();
    }
  };

  const title = view === 'login' ? 'Sign In' : view === 'signup' ? 'Create Account' : 'Reset Password';

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-slate-900 rounded-2xl border border-slate-700 max-w-md w-full p-6 shadow-2xl max-h-[90vh] overflow-y-auto">
        <div className="flex items-center justify-between mb-5">
          <h2 className="text-xl font-bold text-slate-100 font-['Orbitron']">{title}</h2>
          <button onClick={onClose} className="p-2 rounded-lg hover:bg-slate-800 text-slate-400 hover:text-slate-200 transition-colors">✕</button>
        </div>

        {error && (
          <div className="mb-4 px-4 py-3 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400 text-sm">{error}</div>
        )}

        {/* Demo accounts — quick access */}
        <div className="mb-5 p-4 rounded-xl bg-cyan-500/5 border border-cyan-500/20">
          <div className="text-xs font-bold text-cyan-400 uppercase tracking-wider mb-3">Demo Accounts</div>
          <div className="space-y-2">
            {/* Pro account */}
            <button
              onClick={() => handleDemoLogin('pro@keytune.app')}
              disabled={loading}
              className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg bg-amber-500/10 border border-amber-500/30 hover:bg-amber-500/20 transition-colors disabled:opacity-50"
            >
              <div className="flex items-center gap-2">
                <span className="w-7 h-7 rounded-full bg-amber-500/20 flex items-center justify-center text-amber-400 text-[10px] font-bold">★</span>
                <div className="text-left">
                  <div className="text-sm font-bold text-amber-400">Pro Account</div>
                  <div className="text-[10px] text-slate-400">pro@keytune.app</div>
                </div>
              </div>
              <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-500/20 text-amber-400 border border-amber-500/30">PRO</span>
            </button>

            {/* Plus account */}
            <button
              onClick={() => handleDemoLogin('plus@keytune.app')}
              disabled={loading}
              className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg bg-cyan-500/10 border border-cyan-500/30 hover:bg-cyan-500/20 transition-colors disabled:opacity-50"
            >
              <div className="flex items-center gap-2">
                <span className="w-7 h-7 rounded-full bg-cyan-500/20 flex items-center justify-center text-cyan-400 text-[10px] font-bold">+</span>
                <div className="text-left">
                  <div className="text-sm font-bold text-cyan-400">Plus Account</div>
                  <div className="text-[10px] text-slate-400">plus@keytune.app</div>
                </div>
              </div>
              <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-cyan-500/20 text-cyan-400 border border-cyan-500/30">PLUS</span>
            </button>

            {/* Demo account (Pro) */}
            <button
              onClick={() => handleDemoLogin('demo@keytune.app')}
              disabled={loading}
              className="w-full flex items-center justify-between px-3 py-2.5 rounded-lg bg-amber-500/10 border border-amber-500/30 hover:bg-amber-500/20 transition-colors disabled:opacity-50"
            >
              <div className="flex items-center gap-2">
                <span className="w-7 h-7 rounded-full bg-amber-500/20 flex items-center justify-center text-amber-400 text-[10px] font-bold">★</span>
                <div className="text-left">
                  <div className="text-sm font-bold text-amber-400">Demo Account</div>
                  <div className="text-[10px] text-slate-400">demo@keytune.app</div>
                </div>
              </div>
              <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-amber-500/20 text-amber-400 border border-amber-500/30">PRO</span>
            </button>
          </div>
        </div>

        {/* Divider */}
        {view !== 'forgot' && (
          <>
            <button
              onClick={handleGoogleLogin}
              disabled={loading}
              className="w-full mb-3 py-2.5 rounded-xl bg-white text-slate-900 font-bold text-sm flex items-center justify-center gap-3 hover:bg-slate-100 transition-colors disabled:opacity-50"
            >
              <svg className="w-4 h-4" viewBox="0 0 24 24"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92a5.06 5.06 0 01-2.2 3.32v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.1z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/></svg>
              Continue with Google
            </button>
            <div className="relative mb-3">
              <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-700" /></div>
              <div className="relative flex justify-center text-xs"><span className="bg-slate-900 px-3 text-slate-500">or sign in with email</span></div>
            </div>
          </>
        )}

        {/* Email form */}
        <form onSubmit={handleSubmit} className="space-y-3">
          {view !== 'forgot' && (
            <>
              <div>
                <label className="block text-xs text-slate-400 mb-1">Email</label>
                <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" required className="w-full px-3 py-2.5 bg-slate-800 border border-slate-600 rounded-xl text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-sm" />
              </div>
              <div>
                <label className="block text-xs text-slate-400 mb-1">Password</label>
                <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" required className="w-full px-3 py-2.5 bg-slate-800 border border-slate-600 rounded-xl text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-sm" />
              </div>
            </>
          )}

          {view === 'forgot' && (
            <div>
              <label className="block text-xs text-slate-400 mb-1">Email address</label>
              <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" required className="w-full px-3 py-2.5 bg-slate-800 border border-slate-600 rounded-xl text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-sm" />
            </div>
          )}

          <button type="submit" disabled={loading} className="w-full py-2.5 rounded-xl bg-cyan-500 text-white font-bold text-sm hover:bg-cyan-600 transition-colors disabled:opacity-50 shadow-lg shadow-cyan-500/20">
            {loading ? <span className="flex items-center justify-center gap-2"><svg className="animate-spin h-4 w-4" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg>Processing...</span> : view === 'login' ? 'Sign In' : view === 'signup' ? 'Create Account' : 'Send Reset Link'}
          </button>
        </form>

        {/* Footer */}
        <div className="mt-4 text-center text-xs text-slate-400 space-y-1.5">
          {view === 'login' && (
            <>
              <button onClick={() => { setView('forgot'); setError(null); }} className="text-cyan-400 hover:text-cyan-300">Forgot password?</button>
              <div>Don't have an account? <button onClick={() => { setView('signup'); setError(null); }} className="text-cyan-400 hover:text-cyan-300">Sign up</button></div>
            </>
          )}
          {view === 'signup' && <div>Already have an account? <button onClick={() => { setView('login'); setError(null); }} className="text-cyan-400 hover:text-cyan-300">Sign in</button></div>}
          {view === 'forgot' && <button onClick={() => { setView('login'); setError(null); }} className="text-cyan-400 hover:text-cyan-300">Back to sign in</button>}
        </div>
      </div>
    </div>
  );
}