// src/store/pianoProfileStore.ts — Saved piano profiles for client records + invoices

import { create } from 'zustand';
import { SoundPrint, FlaggedKey } from './calibrationStore';

export interface PianoProfile {
  id: string;
  // Client info
  clientName: string;
  clientEmail: string;
  clientPhone: string;
  // Piano info
  pianoMake: string;
  pianoModel: string;
  pianoSerial: string;
  pianoYear: string;
  pianoType: string;  // upright, grand, baby_grand, spinet, console
  // Calibration data
  soundPrints: Record<number, SoundPrint>;
  flaggedKeys: FlaggedKey[];
  // Session metadata
  calibrationDate: number;
  tuningDate: number | null;
  tunerNotes: string;
  // Invoice fields
  invoiceNumber: string;
  serviceType: string;  // calibration, tuning, pitch_raise, repair
  serviceFee: string;
  currency: string;
  // Meta
  createdAt: number;
  updatedAt: number;
}

export interface PianoProfileState {
  profiles: PianoProfile[];
  addProfile: (profile: Omit<PianoProfile, 'id' | 'createdAt' | 'updatedAt'>) => string;
  updateProfile: (id: string, updates: Partial<PianoProfile>) => void;
  deleteProfile: (id: string) => void;
  getProfileById: (id: string) => PianoProfile | undefined;
}

const PROFILES_KEY = 'keytune-piano-profiles';

function loadProfiles(): PianoProfile[] {
  try {
    const raw = localStorage.getItem(PROFILES_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveProfiles(profiles: PianoProfile[]): void {
  try {
    localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
  } catch {
    // silent
  }
}

function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

export const usePianoProfileStore = create<PianoProfileState>((set, get) => ({
  profiles: loadProfiles(),

  addProfile: (data) => {
    const id = generateId();
    const now = Date.now();
    const profile: PianoProfile = {
      ...data,
      id,
      createdAt: now,
      updatedAt: now,
    };
    set((state) => {
      const profiles = [...state.profiles, profile];
      saveProfiles(profiles);
      return { profiles };
    });
    return id;
  },

  updateProfile: (id, updates) => {
    set((state) => {
      const profiles = state.profiles.map(p =>
        p.id === id ? { ...p, ...updates, updatedAt: Date.now() } : p
      );
      saveProfiles(profiles);
      return { profiles };
    });
  },

  deleteProfile: (id) => {
    set((state) => {
      const profiles = state.profiles.filter(p => p.id !== id);
      saveProfiles(profiles);
      return { profiles };
    });
  },

  getProfileById: (id) => {
    return get().profiles.find(p => p.id === id);
  },
}));