// src/audio/StretchTuning.ts — Railsback curve stretch tuning offsets
// Pure TypeScript — no React, no side effects.

/**
 * Build the Railsback stretch offset table for all 88 piano keys.
 * Index 0 = A0 (MIDI 21), Index 87 = C8 (MIDI 108).
 * Formula: signed parabola centred at key 44 (~E4/F4 boundary)
 *   offset ≈ 0.0012 × n × |n|  where n = keyIndex − 43.5
 * Produces: A0 ≈ −2.3¢, C4 ≈ 0¢, C8 ≈ +8¢
 */
function buildRailsbackTable(): Float32Array {
  const table = new Float32Array(88);
  for (let i = 0; i < 88; i++) {
    const n = i - 43.5;
    table[i] = 0.0012 * n * Math.abs(n);
  }
  return table;
}

export const RAILSBACK: Float32Array = buildRailsbackTable();

/**
 * Get the Railsback stretch offset for a given MIDI note number.
 * @param noteNum - MIDI note number (21=A0, 108=C8)
 * @returns Offset in cents (0 if note is out of range)
 */
export function getRailsbackOffset(noteNum: number): number {
  const keyIndex = noteNum - 21;
  if (keyIndex < 0 || keyIndex >= 88) return 0;
  return RAILSBACK[keyIndex];
}

/**
 * Compute cents deviation with optional stretch tuning and calibration offset.
 * @param freq - Detected (smoothed) frequency in Hz
 * @param noteNum - MIDI note number (21–108)
 * @param referenceA - Reference A4 in Hz
 * @param useStretch - Apply Railsback curve
 * @param calibOffset - Global calibration trim in cents (subtracted)
 * @returns Cents deviation (float, round at display layer only)
 */
export function getCentsWithStretch(
  freq: number,
  noteNum: number,
  referenceA: number,
  useStretch: boolean,
  calibOffset = 0
): number {
  const stretchOffset = useStretch ? getRailsbackOffset(noteNum) : 0;
  const idealFreq = referenceA * Math.pow(2, (noteNum - 69) / 12);
  const stretchedIdeal = idealFreq * Math.pow(2, stretchOffset / 1200);
  return 1200 * Math.log2(freq / stretchedIdeal) - calibOffset;
}