// src/components/tuner/PrecisionTools.tsx — Collapsible carousel with left/right arrows
// Switches between: Inharmonicity, Freq Spectrum, Tuning Curve

import { useState, useRef } from 'react';
import { InharmonicityChart } from './InharmonicityChart';
import { FreqSpectrumDetailed } from './FreqSpectrumDetailed';
import { TuningCurveChart } from './TuningCurveChart';

const TOOLS = [
  { id: 'inharmonicity', label: 'Inharmonicity', icon: '📊' },
  { id: 'spectrum', label: 'Freq Spectrum', icon: '📡' },
  { id: 'curve', label: 'Tuning Curve', icon: '📐' },
] as const;

type ToolId = typeof TOOLS[number]['id'];

export function PrecisionTools() {
  const [activeIdx, setActiveIdx] = useState(0);
  const [isExpanded, setIsExpanded] = useState(true);
  const touchStartX = useRef(0);

  const goLeft = () => setActiveIdx(i => (i - 1 + TOOLS.length) % TOOLS.length);
  const goRight = () => setActiveIdx(i => (i + 1) % TOOLS.length);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e: React.TouchEvent) => {
    const dx = e.changedTouches[0].clientX - touchStartX.current;
    if (Math.abs(dx) > 40) {
      if (dx > 0) goLeft();
      else goRight();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'ArrowLeft') goLeft();
    else if (e.key === 'ArrowRight') goRight();
  };

  return (
    <div className="w-full">
      {/* Collapsible header */}
      <button
        onClick={() => setIsExpanded(!isExpanded)}
        className="w-full flex items-center justify-between px-2 py-0.5 text-[10px] font-bold tracking-wide text-slate-400 hover:text-slate-200 transition-colors"
      >
        <span className="flex items-center gap-1.5">
          <svg
            className={`w-3 h-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`}
            fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}
          >
            <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
          </svg>
          PRECISION TOOLS
        </span>
        <span className="text-[10px] text-slate-500">{TOOLS[activeIdx].label}</span>
      </button>

      {/* Collapsible content */}
      <div
        className={`overflow-hidden transition-all duration-200 ease-in-out ${isExpanded ? 'max-h-[200px] opacity-100' : 'max-h-0 opacity-0'}`}
      >
        <div
          className="relative flex items-center gap-1"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
          onKeyDown={handleKeyDown}
          tabIndex={0}
          role="tablist"
          aria-label="Precision tools carousel"
        >
          {/* Left arrow */}
          <button
            onClick={goLeft}
            className="flex-shrink-0 w-6 h-8 flex items-center justify-center text-slate-500 hover:text-cyan-400 transition-colors"
            aria-label="Previous tool"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
            </svg>
          </button>

          {/* Tool content area */}
          <div className="flex-1 h-16 rounded-lg overflow-hidden">
            {activeIdx === 0 && <InharmonicityChart />}
            {activeIdx === 1 && <FreqSpectrumDetailed />}
            {activeIdx === 2 && <TuningCurveChart />}
          </div>

          {/* Right arrow */}
          <button
            onClick={goRight}
            className="flex-shrink-0 w-6 h-8 flex items-center justify-center text-slate-500 hover:text-cyan-400 transition-colors"
            aria-label="Next tool"
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
            </svg>
          </button>
        </div>

        {/* Page indicator */}
        <div className="flex items-center justify-center gap-1 py-0.5">
          {TOOLS.map((tool, i) => (
            <button
              key={tool.id}
              onClick={() => setActiveIdx(i)}
              className={`flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[9px] font-medium transition-colors ${
                i === activeIdx
                  ? 'bg-cyan-500/20 text-cyan-400'
                  : 'text-slate-600 hover:text-slate-400'
              }`}
            >
              <span>{tool.icon}</span>
              <span className="hidden sm:inline">{tool.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}