// src/components/tuner/WaveformDisplay.tsx — Live waveform visualization (oscilloscope style)
// FIX: Uses refs for Zustand values to prevent rAF restart on every state change.
// Previous version had isListening as useCallback dep, causing animation restarts.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { getSharedAnalyser } from '../../audio/AudioEngine';

export function WaveformDisplay() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const storeRef = useRef(useTunerStore.getState());

  // Keep ref in sync — does NOT restart animation
  storeRef.current = useTunerStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      // Dark background
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      // Grid lines
      ctx.strokeStyle = '#1a2332';
      ctx.lineWidth = 0.5;
      for (let y = 0; y < h; y += h / 6) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }
      for (let x = 0; x < w; x += w / 8) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }

      // Center line
      ctx.strokeStyle = '#1e3a5f';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(0, h / 2);
      ctx.lineTo(w, h / 2);
      ctx.stroke();

      // Read from ref — no closure dependency
      const { isListening } = storeRef.current;
      const analyser = getSharedAnalyser();

      if (!isListening || !analyser) {
        // Flat line when not listening
        ctx.strokeStyle = '#22c55e44';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(0, h / 2);
        ctx.lineTo(w, h / 2);
        ctx.stroke();

        // Label
        ctx.fillStyle = '#475569';
        ctx.font = '12px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Start tuning to see waveform', w / 2, h / 2 - 8);
        animRef.current = requestAnimationFrame(draw);
        return;
      }

      // Get waveform data
      const bufferLength = analyser.fftSize;
      const dataArray = new Float32Array(bufferLength);
      analyser.getFloatTimeDomainData(dataArray);

      // Draw waveform — green oscilloscope style
      const gradient = ctx.createLinearGradient(0, 0, w, 0);
      gradient.addColorStop(0, '#22c55e');
      gradient.addColorStop(0.5, '#06b6d4');
      gradient.addColorStop(1, '#22c55e');

      ctx.strokeStyle = gradient;
      ctx.lineWidth = 2;
      ctx.lineJoin = 'round';
      ctx.lineCap = 'round';
      ctx.beginPath();

      const sliceWidth = w / bufferLength;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const v = dataArray[i];
        const y = (v * 0.5 + 0.5) * h;
        if (i === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
        x += sliceWidth;
      }
      ctx.stroke();

      // Glow effect — draw again thicker and semi-transparent
      ctx.globalAlpha = 0.15;
      ctx.lineWidth = 6;
      ctx.stroke();
      ctx.globalAlpha = 1;

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []); // Empty deps — loop runs forever, reads from refs

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-12 sm:h-16 rounded-lg border border-slate-800"
    />
  );
}