// src/components/tuner/InharmonicityChart.tsx — Bar chart of partials showing inharmonicity
// Shows 1st through 8th harmonic with deviation from ideal integer multiples.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { getSharedAnalyser, getSharedAudioContext } from '../../audio/AudioEngine';

const NUM_PARTIALS = 8;

export function InharmonicityChart() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const smoothPartial = useRef<Float32Array | null>(null);
  const deviationRef = useRef<Float32Array | null>(null);

  const storeRef = useRef(useTunerStore.getState());
  storeRef.current = useTunerStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      // Background
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      const { isListening, frequency } = storeRef.current;
      const analyser = getSharedAnalyser();
      const audioCtx = getSharedAudioContext();

      if (!isListening || !analyser || !audioCtx || frequency <= 0) {
        // Idle state
        ctx.fillStyle = '#475569';
        ctx.font = '11px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Inharmonicity', w / 2, h / 2);
        animRef.current = requestAnimationFrame(draw);
        return;
      }

      // Get frequency data
      const bufferLength = analyser.frequencyBinCount;
      const dataArray = new Float32Array(bufferLength);
      analyser.getFloatFrequencyData(dataArray);
      const sampleRate = audioCtx.sampleRate;
      const binHz = sampleRate / analyser.fftSize;

      // Initialize smooth arrays
      if (!smoothPartial.current || smoothPartial.current.length !== NUM_PARTIALS) {
        smoothPartial.current = new Float32Array(NUM_PARTIALS);
        deviationRef.current = new Float32Array(NUM_PARTIALS);
      }

      // Find fundamental and partials
      const fundBin = Math.round(frequency / binHz);

      for (let p = 0; p < NUM_PARTIALS; p++) {
        const partialNum = p + 1;
        // Ideal partial = n * fundamental
        const idealBin = fundBin * partialNum;

        if (idealBin >= bufferLength || idealBin <= 0) {
          smoothPartial.current[p] = smoothPartial.current![p] * 0.95;
          deviationRef.current![p] = deviationRef.current![p] * 0.95;
          continue;
        }

        // Search for peak near ideal bin (±3 bins window)
        let peakBin = idealBin;
        let peakVal = -Infinity;
        const searchWidth = Math.max(3, Math.round(fundBin * 0.05));
        for (let b = Math.max(0, idealBin - searchWidth); b <= Math.min(bufferLength - 1, idealBin + searchWidth); b++) {
          if (dataArray[b] > peakVal) {
            peakVal = dataArray[b];
            peakBin = b;
          }
        }

        // Normalize amplitude (0-1 range from dB)
        const normAmp = Math.max(0, (peakVal + 80) / 80); // -80dB floor
        smoothPartial.current[p] = smoothPartial.current[p] * 0.7 + normAmp * 0.3;

        // Deviation in cents: how far the actual partial is from ideal n*f0
        const actualFreq = peakBin * binHz;
        const idealFreq = partialNum * frequency;
        const centsDev = 1200 * Math.log2(actualFreq / idealFreq);
        (deviationRef.current!)[p] = (deviationRef.current!)[p] * 0.7 + centsDev * 0.3;
      }

      // Draw bar chart
      const padding = { left: 32, right: 10, top: 14, bottom: 20 };
      const chartW = w - padding.left - padding.right;
      const chartH = h - padding.top - padding.bottom;
      const barGap = 4;
      const barW = (chartW - barGap * (NUM_PARTIALS - 1)) / NUM_PARTIALS;
      const maxDeviation = 30; // cents scale

      // Y-axis labels
      ctx.fillStyle = '#475569';
      ctx.font = '7px "Share Tech Mono", monospace';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let c = -30; c <= 30; c += 10) {
        const y = padding.top + chartH * (1 - (c + maxDeviation) / (2 * maxDeviation));
        ctx.fillText(`${c}¢`, padding.left - 4, y);
        // Grid line
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(padding.left, y);
        ctx.lineTo(w - padding.right, y);
        ctx.stroke();
      }

      // Zero line
      const zeroY = padding.top + chartH * 0.5;
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding.left, zeroY);
      ctx.lineTo(w - padding.right, zeroY);
      ctx.stroke();

      // Bars
      for (let p = 0; p < NUM_PARTIALS; p++) {
        const x = padding.left + p * (barW + barGap);
        const sp = smoothPartial.current;
        const dv = deviationRef.current;
        const amp = sp ? sp[p] : 0;
        const dev = dv ? dv[p] : 0;
        const clampedDev = Math.max(-maxDeviation, Math.min(maxDeviation, dev));

        // Bar height proportional to deviation
        const barH = (clampedDev / maxDeviation) * (chartH / 2);
        const barTop = barH >= 0 ? zeroY - barH : zeroY;
        const absBarH = Math.abs(barH);

        // Color: green near 0, yellow moderate, red high
        const absDev = Math.abs(clampedDev);
        let color: string;
        if (absDev <= 3) color = '#22c55e';
        else if (absDev <= 10) color = '#eab308';
        else color = '#ef4444';

        // Opacity based on amplitude
        const alpha = 0.3 + amp * 0.7;

        ctx.globalAlpha = alpha;
        ctx.fillStyle = color;
        ctx.beginPath();
        const r = Math.min(2, barW / 4);
        if (barH >= 0) {
          ctx.roundRect(x, barTop, barW, absBarH, [r, r, 0, 0]);
        } else {
          ctx.roundRect(x, zeroY, barW, absBarH, [0, 0, r, r]);
        }
        ctx.fill();

        // Glow on strong partials
        if (amp > 0.5) {
          ctx.shadowColor = color;
          ctx.shadowBlur = 6;
          ctx.fill();
          ctx.shadowBlur = 0;
        }

        ctx.globalAlpha = 1;

        // Partial number label
        ctx.fillStyle = '#64748b';
        ctx.font = '8px "Share Tech Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(`${p + 1}`, x + barW / 2, h - padding.bottom + 4);

        // Deviation value label
        if (amp > 0.1) {
          ctx.fillStyle = color;
          ctx.font = '7px "Share Tech Mono", monospace';
          ctx.textBaseline = barH >= 0 ? 'bottom' : 'top';
          const labelY = barH >= 0 ? barTop - 2 : zeroY + absBarH + 2;
          ctx.fillText(`${dev >= 0 ? '+' : ''}${Math.round(dev)}¢`, x + barW / 2, labelY);
        }
      }

      // Title
      ctx.fillStyle = '#94a3b8';
      ctx.font = 'bold 8px "Exo 2", sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText('Partials', padding.left, 2);

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-full rounded-lg border border-slate-800"
    />
  );
}