// src/audio/AudioEngine.ts — Manages microphone, AudioContext, and pitch detection loop
// Pure TypeScript — no React. Communicates via callback.
// Exposes analyser node for waveform/spectrum visualization.
// IMPORTANT: AudioContext MUST be created synchronously inside a user gesture.
// On iOS Safari, creating it after an async gap (like getUserMedia) fails.

import { detectPitch } from './PitchDetector';

export type PitchCallback = (freq: number) => void;

/** Sensitivity EMA alpha values */
export const SENSITIVITY_ALPHA: Record<string, number> = {
  slow: 0.08,
  normal: 0.15,
  fast: 0.3,
};

/** Global reference for spectrum visualizers to access the analyser node */
let _sharedAnalyser: AnalyserNode | null = null;
let _sharedAudioContext: AudioContext | null = null;

export function getSharedAnalyser(): AnalyserNode | null {
  return _sharedAnalyser;
}

export function getSharedAudioContext(): AudioContext | null {
  return _sharedAudioContext;
}

/**
 * Pre-create or resume the AudioContext synchronously inside a user gesture.
 * Call this BEFORE any async work (like getUserMedia).
 * This is the key fix for iOS Safari PWA.
 */
export function prepareAudioContext(): { ctx: AudioContext; alreadyExisted: boolean } {
  // Reuse existing context if still alive
  if (_sharedAudioContext && _sharedAudioContext.state !== 'closed') {
    if (_sharedAudioContext.state === 'suspended') {
      _sharedAudioContext.resume();
    }
    return { ctx: _sharedAudioContext, alreadyExisted: true };
  }

  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
    sampleRate: 44100,
  });

  if (ctx.state === 'suspended') {
    ctx.resume();
  }

  _sharedAudioContext = ctx;
  return { ctx, alreadyExisted: false };
}

/**
 * AudioEngine — manages microphone access, audio context, and real-time pitch detection.
 * Use prepareAudioContext() synchronously in the click handler, then call start() with it.
 */
export class AudioEngine {
  private ctx: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private source: MediaStreamAudioSourceNode | null = null;
  private stream: MediaStream | null = null;
  private rafId: number | null = null;
  private buffer: Float32Array | null = null;
  private onPitch: PitchCallback | null = null;
  private smoothedFreq: number | null = null;
  private lastNoteNum: number | null = null;
  private alpha: number = 0.15;
  /** When true, skip the hysteresis jump filter so any note is accepted.
   *  Set to true during calibration mode. */
  public bypassHysteresis: boolean = false;
  /** Maximum semitone jump allowed by the hysteresis filter.
   *  Normal tuning: 6 (default). Stepwise mode: 2. Calibration: bypassed entirely. */
  public maxJumpSemitones: number = 6;

  /**
   * Start listening. Pass a pre-created AudioContext from prepareAudioContext().
   * MUST be called inside a click/touchend handler.
   */
  async start(ctx: AudioContext, onPitch: PitchCallback): Promise<void> {
    this.ctx = ctx;
    this.onPitch = onPitch;

    // Make sure context is running
    if (this.ctx.state === 'suspended') {
      await this.ctx.resume();
    }

    _sharedAudioContext = this.ctx;

    // getUserMedia must happen AFTER context is created/resumed
    // First try with constraints (raw audio for tuning)
    // If that fails with NotAllowedError, try without constraints as fallback
    let stream: MediaStream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: false,
          channelCount: 1,
        },
      });
    } catch (constraintErr: any) {
      // Some browsers/blockers reject constrained audio but allow basic mic access
      if (constraintErr instanceof DOMException && constraintErr.name === 'NotAllowedError') {
        console.warn('[AudioEngine] Constrained getUserMedia failed, trying basic request...');
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      } else {
        throw constraintErr;
      }
    }
    this.stream = stream;

    this.source = this.ctx.createMediaStreamSource(this.stream);
    this.analyser = this.ctx.createAnalyser();
    this.analyser.fftSize = 4096;
    this.analyser.smoothingTimeConstant = 0.8;
    this.buffer = new Float32Array(this.analyser.fftSize);

    this.source.connect(this.analyser);

    // Share analyser for visualizers
    _sharedAnalyser = this.analyser;

    this.rafId = requestAnimationFrame(this.loop.bind(this));
  }

  /** Stop the engine and release all resources. */
  stop(): void {
    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach((t) => t.stop());
      this.stream = null;
    }
    if (this.source) {
      try { this.source.disconnect(); } catch {}
      this.source = null;
    }
    if (this.ctx) {
      this.ctx.close().catch(() => {});
      this.ctx = null;
    }
    _sharedAnalyser = null;
    _sharedAudioContext = null;
    this.smoothedFreq = null;
    this.lastNoteNum = null;
    this.buffer = null;
    if (this.onPitch) this.onPitch(-1);
  }

  /** Update EMA alpha (called when user changes sensitivity setting). */
  updateSensitivity(alpha: number): void {
    this.alpha = alpha;
  }

  /** Reset hysteresis state — clears smoothedFreq and lastNoteNum so
   *  the jump filter doesn't block detection after a context switch (e.g. starting calibration). */
  resetHysteresis(): void {
    this.smoothedFreq = null;
    this.lastNoteNum = null;
  }

  /** Check if the engine is currently listening. */
  get isListening(): boolean {
    return this.ctx !== null && this.ctx.state === 'running';
  }

  /** Internal rAF loop: read buffer → detect pitch → smooth → hysteresis → callback. */
  private loop(): void {
    this.rafId = requestAnimationFrame(this.loop.bind(this));

    if (this.ctx && this.ctx.state === 'suspended') {
      this.ctx.resume();
      return;
    }

    if (!this.analyser || !this.buffer || !this.ctx) return;

    this.analyser.getFloatTimeDomainData(this.buffer);
    const rawFreq = detectPitch(this.buffer, this.ctx.sampleRate);

    if (rawFreq < 0) {
      this.smoothedFreq = null;
      this.lastNoteNum = null;
      this.onPitch?.(-1);
      return;
    }

    this.smoothedFreq =
      this.smoothedFreq === null
        ? rawFreq
        : this.alpha * rawFreq + (1 - this.alpha) * this.smoothedFreq;

    const noteNum = Math.round(
      12 * Math.log2(this.smoothedFreq / 440) + 69
    );
    // Skip jump filter during calibration (bypassHysteresis) —
    // when calibrating, we need to detect any note immediately.
    // For stepwise mode, maxJumpSemitones is set to 2.
    if (!this.bypassHysteresis && this.lastNoteNum !== null && Math.abs(noteNum - this.lastNoteNum) > this.maxJumpSemitones) {
      return;
    }
    this.lastNoteNum = noteNum;

    this.onPitch?.(this.smoothedFreq);
  }
}

/**
 * Detect error type from getUserMedia failure.
 */
export function micErrorMessage(err: DOMException | Error): string {
  if (err instanceof DOMException) {
    if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
      return 'Microphone access denied.\n\nTo fix on Android:\n1. Tap the 🔒 icon in the address bar\n2. Set Microphone → Allow\n3. Refresh and try again\n\nOr: Chrome Settings → Site Settings → Microphone → Allow';
    }
    if (err.name === 'NotFoundError' || err.name === 'DevicesNotFoundError') {
      return 'No microphone found. Please connect a microphone and try again.';
    }
    if (err.name === 'NotReadableError' || err.name === 'TrackStartError') {
      return 'Microphone is in use by another app. Please close other apps using the microphone and try again.';
    }
  }
  return `Could not access microphone: ${err.message}`;
}