// src/components/calibration/CalibrationKeyboard.tsx — 88-key calibration keyboard
// Matches the PianoKeyboard style but colors keys by calibration status:
// pending=dim, current=red pulse, captured=green, flagged=yellow

import { useRef, useEffect } from 'react';
import { useCalibrationStore, KeyStatus } from '../../store/calibrationStore';
import { useTunerStore } from '../../store/tunerStore';

const NOTE_NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'];
const WHITE_NOTES = [0, 2, 4, 5, 7, 9, 11]; // C D E F G A B
const BLACK_NOTES = [1, 3, 6, 8, 10];       // C# D# F# G# A#
const MIDI_OFFSET = 21;
const TOTAL_KEYS = 88;

const STATUS_COLORS: Record<KeyStatus, { fill: string; glow?: string }> = {
  pending:  { fill: '#1e293b', glow: undefined },
  current:  { fill: '#991b1b', glow: '#ef4444' },  // red-800 fill, red-500 glow
  captured: { fill: '#166534', glow: undefined },     // green-800 fill
  flagged:  { fill: '#854d0e', glow: '#eab308' },      // yellow-800 fill, yellow-500 glow
};

export function CalibrationKeyboard() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const calibRef = useRef(useCalibrationStore.getState());
  const tunerRef = useRef(useTunerStore.getState());

  // Keep refs in sync
  calibRef.current = useCalibrationStore();
  tunerRef.current = useTunerStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const { keyStatuses, currentMidi, isCalibrating } = calibRef.current;
      const { noteNum: activeMidi, isActive } = tunerRef.current;

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);

      const w = rect.width;
      const h = rect.height;

      // Count white keys in A0-C8 range
      let whiteCount = 0;
      for (let n = MIDI_OFFSET; n < MIDI_OFFSET + TOTAL_KEYS; n++) {
        if (WHITE_NOTES.includes(n % 12)) whiteCount++;
      }

      const whiteWidth = w / whiteCount;
      const blackWidth = whiteWidth * 0.6;
      const blackHeight = h * 0.62;

      // Clear
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      // Pulse animation for current key
      const pulseAlpha = 0.65 + 0.35 * Math.sin(Date.now() / 300);

      // Draw white keys first
      let wx = 0;
      for (let n = MIDI_OFFSET; n < MIDI_OFFSET + TOTAL_KEYS; n++) {
        const noteInOctave = n % 12;
        const isBlack = BLACK_NOTES.includes(noteInOctave);
        if (isBlack) continue;

        const status: KeyStatus = isCalibrating ? (keyStatuses[n] || 'pending') : 'pending';
        const isCurrent = n === currentMidi;
        const isActiveNote = isActive && activeMidi === n;
        const colors = STATUS_COLORS[status] || STATUS_COLORS.pending;

        // White key fill
        if (isCurrent) {
          ctx.fillStyle = `rgba(239, 68, 68, ${pulseAlpha})`;
        } else {
          ctx.fillStyle = colors.fill;
        }
        ctx.fillRect(wx, 0, whiteWidth - 1, h - 2);

        // Border
        ctx.strokeStyle = '#334155';
        ctx.lineWidth = 0.5;
        ctx.strokeRect(wx, 0, whiteWidth - 1, h - 2);

        // Glow bar for current key
        if (isCurrent) {
          ctx.save();
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 15;
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(wx + 1, h * 0.7, whiteWidth - 3, 4);
          ctx.restore();
        }

        // Glow bar for active detected note (when it matches current)
        if (isActiveNote && !isCurrent && status === 'pending') {
          ctx.save();
          ctx.shadowColor = '#06b6d4';
          ctx.shadowBlur = 8;
          ctx.fillStyle = '#06b6d4';
          ctx.fillRect(wx + 1, h * 0.75, whiteWidth - 3, 3);
          ctx.restore();
        }

        // C note labels
        if (noteInOctave === 0) {
          const octave = Math.floor(n / 12) - 1;
          ctx.fillStyle = isCurrent ? '#fca5a5' : (status === 'captured' ? '#86efac' : '#64748b');
          ctx.font = `${Math.max(8, Math.min(10, whiteWidth * 0.35))}px "Exo 2", sans-serif`;
          ctx.textAlign = 'center';
          ctx.fillText(`C${octave}`, wx + whiteWidth / 2, h - 6);
        }

        wx += whiteWidth;
      }

      // Draw black keys on top
      wx = 0;
      for (let n = MIDI_OFFSET; n < MIDI_OFFSET + TOTAL_KEYS; n++) {
        const noteInOctave = n % 12;
        const isBlack = BLACK_NOTES.includes(noteInOctave);
        if (!isBlack) {
          wx += whiteWidth;
          continue;
        }

        const status: KeyStatus = isCalibrating ? (keyStatuses[n] || 'pending') : 'pending';
        const isCurrent = n === currentMidi;
        const isActiveNote = isActive && activeMidi === n;
        const colors = STATUS_COLORS[status] || STATUS_COLORS.pending;

        const bx = wx - blackWidth / 2;
        const br = 2;

        // Black key fill
        if (isCurrent) {
          ctx.fillStyle = `rgba(153, 27, 27, ${pulseAlpha})`;
        } else if (status === 'captured') {
          ctx.fillStyle = '#14532d'; // dark green
        } else if (status === 'flagged') {
          ctx.fillStyle = '#713f12'; // dark yellow
        } else {
          ctx.fillStyle = '#0f172a'; // default dark
        }

        ctx.beginPath();
        ctx.moveTo(bx + br, 0);
        ctx.lineTo(bx + blackWidth - br, 0);
        ctx.quadraticCurveTo(bx + blackWidth, 0, bx + blackWidth, br);
        ctx.lineTo(bx + blackWidth, blackHeight - br);
        ctx.quadraticCurveTo(bx + blackWidth, blackHeight, bx + blackWidth - br, blackHeight);
        ctx.lineTo(bx + br, blackHeight);
        ctx.quadraticCurveTo(bx, blackHeight, bx, blackHeight - br);
        ctx.lineTo(bx, br);
        ctx.quadraticCurveTo(bx, 0, bx + br, 0);
        ctx.closePath();
        ctx.fill();

        // Glow for current key
        if (isCurrent) {
          ctx.save();
          ctx.shadowColor = '#ef4444';
          ctx.shadowBlur = 12;
          ctx.fillStyle = '#ef4444';
          ctx.fillRect(bx + 2, blackHeight - 6, blackWidth - 4, 3);
          ctx.restore();
        }

        // Active detected note
        if (isActiveNote && !isCurrent) {
          ctx.save();
          ctx.shadowColor = '#06b6d4';
          ctx.shadowBlur = 8;
          ctx.fillStyle = '#06b6d4';
          ctx.fillRect(bx + 2, blackHeight - 6, blackWidth - 4, 3);
          ctx.restore();
        }

        ctx.strokeStyle = '#0f172a';
        ctx.lineWidth = 1;
        ctx.stroke();
      }

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []); // Empty deps — runs forever, reads from refs

  return (
    <div className="relative w-full">
      <canvas
        ref={canvasRef}
        className="w-full h-20 sm:h-24 rounded-lg border border-slate-800"
      />
    </div>
  );
}