// src/components/tuner/SpectrumView.tsx — Live frequency spectrum bars (like PianoMeter)
// FIX: Uses refs for Zustand values to prevent rAF restart on every state change.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { getSharedAnalyser, getSharedAudioContext } from '../../audio/AudioEngine';

export function SpectrumView() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const storeRef = useRef(useTunerStore.getState());
  const smoothBars = useRef<Float32Array | null>(null);

  // Keep ref in sync — does NOT restart animation
  storeRef.current = useTunerStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      // Dark background
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      // Read from ref — no closure dependency
      const { isListening } = storeRef.current;
      const analyser = getSharedAnalyser();
      const audioCtx = getSharedAudioContext();

      if (!isListening || !analyser || !audioCtx) {
        // Draw idle bars
        ctx.fillStyle = '#475569';
        ctx.font = '11px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Spectrum', w / 2, h / 2 + 4);
        animRef.current = requestAnimationFrame(draw);
        return;
      }

      // Get frequency data
      const bufferLength = analyser.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyser.getByteFrequencyData(dataArray);

      // Piano-relevant frequency range: ~27 Hz to ~4200 Hz
      // At 44100 Hz with fftSize=4096, each bin = 44100/4096 ≈ 10.77 Hz
      // Bin 2 ≈ 21Hz, Bin 390 ≈ 4200Hz
      const minBin = 2;
      const maxBin = Math.min(390, bufferLength - 1);
      const numBars = 64;
      const barGap = 2;
      const barWidth = (w - barGap * (numBars - 1)) / numBars;

      // Initialize smooth bars
      if (!smoothBars.current || smoothBars.current.length !== numBars) {
        smoothBars.current = new Float32Array(numBars);
      }

      // Map bins to bars (logarithmic frequency mapping for piano)
      for (let i = 0; i < numBars; i++) {
        // Logarithmic mapping: low bins get more bars (bass detail)
        const t = i / numBars;
        const logBin = minBin + t * (maxBin - minBin);
        const binStart = Math.floor(logBin);
        const binEnd = Math.min(Math.ceil(logBin + (maxBin - minBin) / numBars), maxBin + 1);

        // Average the bins in this range
        let sum = 0;
        let count = 0;
        for (let b = binStart; b < binEnd && b < bufferLength; b++) {
          sum += dataArray[b];
          count++;
        }
        const raw = count > 0 ? sum / count : 0;
        const normalized = raw / 255; // 0-1

        // Smooth with EMA
        smoothBars.current[i] = smoothBars.current[i] * 0.7 + normalized * 0.3;

        const barHeight = smoothBars.current[i] * h * 0.9;
        const x = i * (barWidth + barGap);
        const y = h - barHeight;

        // Color gradient based on frequency position (bass=warm, treble=cool)
        const hue = 160 - t * 120; // cyan → orange
        const saturation = 70 + normalized * 30;
        const lightness = 40 + normalized * 25;

        // Main bar
        const barGrad = ctx.createLinearGradient(x, y, x, h);
        barGrad.addColorStop(0, `hsla(${hue}, ${saturation}%, ${lightness}%, 0.95)`);
        barGrad.addColorStop(1, `hsla(${hue}, ${saturation}%, ${lightness * 0.5}%, 0.3)`);
        ctx.fillStyle = barGrad;

        // Rounded top
        const r = Math.min(barWidth / 2, 3);
        ctx.beginPath();
        ctx.moveTo(x + r, y);
        ctx.lineTo(x + barWidth - r, y);
        ctx.quadraticCurveTo(x + barWidth, y, x + barWidth, y + r);
        ctx.lineTo(x + barWidth, h);
        ctx.lineTo(x, h);
        ctx.lineTo(x, y + r);
        ctx.quadraticCurveTo(x, y, x + r, y);
        ctx.closePath();
        ctx.fill();

        // Glow on peak bars
        if (normalized > 0.6) {
          ctx.shadowColor = `hsla(${hue}, 100%, 60%, ${normalized * 0.5})`;
          ctx.shadowBlur = 8;
          ctx.fillStyle = `hsla(${hue}, 100%, 70%, 0.5)`;
          ctx.fillRect(x, y, barWidth, Math.min(3, barHeight));
          ctx.shadowBlur = 0;
        }
      }

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []); // Empty deps — loop runs forever, reads values from refs

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-12 sm:h-16 rounded-lg border border-slate-800"
    />
  );
}