// src/components/session/SessionTracker.tsx — Professional session tracker with client/piano info + notes

import { useState } from 'react';
import { useSessionStore } from '../../store/sessionStore';
import { useTunerStore } from '../../store/tunerStore';
import { useAuthStore } from '../../store/authStore';

export function SessionTracker({ className }: { className?: string }) {
  const {
    records, clearSession, autoRecord,
    clientName, pianoMake, pianoModel, pianoSerial,
    sessionNotes, sessionStartedAt,
    setClientName, setPianoMake, setPianoModel, setPianoSerial,
    addSessionNote, removeSessionNote, removeNote,
    startSession,
  } = useSessionStore();
  const { isActive, noteName, octave } = useTunerStore();
  const { subscriptionTier } = useAuthStore();
  const isPlus = subscriptionTier === 'plus' || subscriptionTier === 'pro';
  const [expanded, setExpanded] = useState(false);
  const [editingInfo, setEditingInfo] = useState(false);
  const [quickNote, setQuickNote] = useState('');

  const tunedCount = Object.keys(records).length;
  const totalNotes = 88;
  const progress = Math.round((tunedCount / totalNotes) * 100);

  const startNewSession = () => {
    startSession();
  };

  const handleQuickNote = () => {
    if (!quickNote.trim()) return;
    addSessionNote(quickNote.trim());
    setQuickNote('');
  };

  return (
    <div className={`rounded-xl border border-slate-800/80 bg-slate-900/50 overflow-hidden ${className || ''}`}>
      {/* Header row */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between px-4 py-2.5 hover:bg-slate-800/50 transition-colors"
      >
        <div className="flex items-center gap-3">
          {/* Progress ring */}
          <div className="relative w-8 h-8">
            <svg className="w-8 h-8 -rotate-90" viewBox="0 0 32 32">
              <circle cx="16" cy="16" r="13" fill="none" stroke="#1e293b" strokeWidth="3" />
              <circle
                cx="16" cy="16" r="13" fill="none"
                stroke="#22c55e"
                strokeWidth="3"
                strokeDasharray={`${(progress / 100) * 2 * Math.PI * 13} ${2 * Math.PI * 13}`}
                strokeLinecap="round"
              />
            </svg>
            <span className="absolute inset-0 flex items-center justify-center text-[9px] font-bold text-slate-300">
              {tunedCount}
            </span>
          </div>
          <div className="text-left">
            <div className="text-xs font-medium text-slate-300">
              {clientName ? `${clientName}'s Session` : 'Session Progress'}
            </div>
            <div className="text-[10px] text-slate-500">
              {tunedCount} / {totalNotes} notes
              {sessionStartedAt && ` · ${new Date(sessionStartedAt).toLocaleDateString()}`}
            </div>
          </div>
        </div>
        <svg
          className={`w-4 h-4 text-slate-400 transition-transform ${expanded ? 'rotate-180' : ''}`}
          fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}
        >
          <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {expanded && (
        <div className="px-4 pb-3 space-y-3 border-t border-slate-800/50 pt-3">
          {/* Session info (client/piano) */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <span className="text-[10px] text-slate-500 uppercase tracking-wider">Session Details</span>
              <button
                onClick={() => setEditingInfo(!editingInfo)}
                className="text-[10px] text-cyan-400 hover:text-cyan-300 transition-colors"
              >
                {editingInfo ? 'Done' : 'Edit'}
              </button>
            </div>

            {editingInfo ? (
              <div className="space-y-2">
                <input
                  type="text"
                  placeholder="Client name"
                  value={clientName}
                  onChange={(e) => setClientName(e.target.value)}
                  className="w-full px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-xs"
                />
                <div className="grid grid-cols-2 gap-2">
                  <input
                    type="text"
                    placeholder="Piano make"
                    value={pianoMake}
                    onChange={(e) => setPianoMake(e.target.value)}
                    className="px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-xs"
                  />
                  <input
                    type="text"
                    placeholder="Model"
                    value={pianoModel}
                    onChange={(e) => setPianoModel(e.target.value)}
                    className="px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-xs"
                  />
                </div>
                <input
                  type="text"
                  placeholder="Serial number"
                  value={pianoSerial}
                  onChange={(e) => setPianoSerial(e.target.value)}
                  className="w-full px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-xs"
                />
              </div>
            ) : (
              <div className="bg-slate-800/30 rounded-lg p-2 text-xs space-y-0.5">
                {clientName && <div className="text-slate-300">Client: {clientName}</div>}
                {(pianoMake || pianoModel) && <div className="text-slate-400">Piano: {pianoMake} {pianoModel}</div>}
                {pianoSerial && <div className="text-slate-400">Serial: {pianoSerial}</div>}
                {!clientName && !pianoMake && <div className="text-slate-500">No session details yet</div>}
              </div>
            )}
          </div>

          {/* Quick note input */}
          <div>
            <span className="text-[10px] text-slate-500 uppercase tracking-wider mb-1 block">Quick Note</span>
            <div className="flex gap-2">
              <input
                type="text"
                value={quickNote}
                onChange={(e) => setQuickNote(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleQuickNote()}
                placeholder="Add a note (e.g. 'sticky key on C4')..."
                className="flex-1 px-3 py-1.5 bg-slate-800 border border-slate-600 rounded-lg text-slate-200 placeholder-slate-500 focus:border-cyan-500 focus:outline-none text-xs"
              />
              <button
                onClick={handleQuickNote}
                disabled={!quickNote.trim()}
                className="px-3 py-1.5 rounded-lg bg-cyan-500/15 text-cyan-400 border border-cyan-500/30 text-xs font-bold hover:bg-cyan-500/25 disabled:opacity-30 transition-colors"
              >
                Add
              </button>
            </div>
          </div>

          {/* Session notes list */}
          {sessionNotes.length > 0 && (
            <div>
              <span className="text-[10px] text-slate-500 uppercase tracking-wider mb-1 block">Notes ({sessionNotes.length})</span>
              <div className="space-y-1 max-h-28 overflow-y-auto">
                {sessionNotes.slice().reverse().map((n) => (
                  <div key={n.id} className="flex items-start gap-2 bg-slate-800/30 rounded-lg px-2 py-1.5 text-xs">
                    <span className="text-slate-300 flex-1">{n.text}</span>
                    <button
                      onClick={() => removeSessionNote(n.id)}
                      className="text-slate-600 hover:text-red-400 transition-colors shrink-0"
                    >
                      ✕
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Auto-record toggle */}
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <span className="text-xs text-slate-300">Auto-record (±5¢, 1.5s)</span>
              {!isPlus && (
                <span className="text-[9px] px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-400 border border-amber-500/30 font-bold">PLUS</span>
              )}
            </div>
            <button
              onClick={() => { if (isPlus) autoRecord(!useSessionStore.getState().autoRecordEnabled); }}
              disabled={!isPlus}
              className={`w-10 h-5 rounded-full transition-colors relative ${
                useSessionStore.getState().autoRecordEnabled && isPlus
                  ? 'bg-cyan-500'
                  : 'bg-slate-700'
              } ${!isPlus ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}`}
            >
              <span
                className={`absolute top-0.5 w-4 h-4 rounded-full bg-white transition-transform shadow ${
                  useSessionStore.getState().autoRecordEnabled && isPlus ? 'translate-x-5' : 'translate-x-0.5'
                }`}
              />
            </button>
          </div>

          {/* Tuned notes grid */}
          {tunedCount > 0 && (
            <div>
              <span className="text-[10px] text-slate-500 uppercase tracking-wider mb-1 block">Tuned Notes</span>
              <div className="flex flex-wrap gap-1">
                {Object.entries(records).slice(-30).reverse().map(([midi, rec]) => (
                  <div
                    key={midi}
                    className="group relative px-1.5 py-0.5 rounded text-[10px] bg-green-500/10 text-green-400 border border-green-500/20 hover:border-green-500/40 cursor-default"
                    title={`${rec.noteName}${rec.octave}: ${rec.cents > 0 ? '+' : ''}${rec.cents.toFixed(1)}¢ at ${rec.frequency.toFixed(1)} Hz${rec.manuallyLogged ? ' (manual)' : ''}`}
                  >
                    {rec.noteName}{rec.octave}
                    {/* Remove button on hover */}
                    <button
                      onClick={(e) => { e.stopPropagation(); removeNote(Number(midi)); }}
                      className="absolute -top-1 -right-1 w-3.5 h-3.5 rounded-full bg-red-500 text-white text-[8px] leading-none hidden group-hover:flex items-center justify-center"
                    >
                      ×
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Start new session / Clear */}
          <div className="flex gap-2">
            <button
              onClick={startNewSession}
              className="flex-1 py-1.5 rounded-lg bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 text-xs font-medium hover:bg-cyan-500/20 transition-colors"
            >
              New Session
            </button>
            <button
              onClick={clearSession}
              className="flex-1 py-1.5 rounded-lg bg-slate-800 text-slate-400 text-xs font-medium hover:bg-slate-700 hover:text-slate-300 transition-colors"
            >
              Clear All
            </button>
            <button
              onClick={() => {
                if (!isPlus) return;
                const report = {
                  client: clientName || 'Unnamed',
                  piano: { make: pianoMake, model: pianoModel, serial: pianoSerial },
                  sessionDate: sessionStartedAt ? new Date(sessionStartedAt).toISOString() : null,
                  notes: sessionNotes.map(n => ({ text: n.text, time: new Date(n.timestamp).toISOString() })),
                  tunedKeys: Object.entries(records).map(([midi, rec]) => ({
                    midi: Number(midi),
                    note: `${rec.noteName}${rec.octave}`,
                    frequency: Math.round(rec.frequency * 100) / 100,
                    cents: Math.round(rec.cents * 10) / 10,
                    manual: rec.manuallyLogged || false,
                  })),
                };
                const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = `keytune-${(clientName || 'session').replace(/\s+/g, '-')}-${new Date().toISOString().slice(0, 10)}.json`;
                a.click();
                URL.revokeObjectURL(url);
              }}
              disabled={!isPlus}
              className={`flex-1 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                isPlus
                  ? 'bg-green-500/10 text-green-400 border border-green-500/20 hover:bg-green-500/20'
                  : 'bg-slate-800/30 text-slate-600 cursor-not-allowed'
              }`}
            >
              {isPlus ? 'Export' : '🔒 Export'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}