// src/pages/TunerPage.tsx — Compact single-screen layout, tight spacing

import { useState, useCallback, useEffect, useRef } from 'react';
import { TuningMeter } from '../components/tuner/TuningMeter';
import { PianoKeyboard } from '../components/tuner/PianoKeyboard';
import { WaveformDisplay } from '../components/tuner/WaveformDisplay';
import { SpectrumView } from '../components/tuner/SpectrumView';
import { SessionTracker } from '../components/session/SessionTracker';
import { PrecisionTools } from '../components/tuner/PrecisionTools';
import { SettingsPanel } from '../components/settings/SettingsPanel';
import { ManualNoteEntry } from '../components/session/ManualNoteEntry';
import NoteSwitchSelector from '../components/tuner/NoteSwitchSelector';
import CalibrationOverlay from '../components/calibration/CalibrationOverlay';
import { CalibrationResultsPanel } from '../components/calibration/CalibrationResultsPanel';
import { useTunerStore } from '../store/tunerStore';
import { useCalibrationStore } from '../store/calibrationStore';
import { useSettingsStore } from '../store/settingsStore';
import { useAudioEngine } from '../hooks/useAudioEngine';
import { engineInstance } from '../hooks/useAudioEngine';

export function TunerPage() {
  const [showSettings, setShowSettings] = useState(false);
  const [showManualEntry, setShowManualEntry] = useState(false);
  const [showVisuals, setShowVisuals] = useState(true);
  const { isActive, isListening, noteName, octave, noteNum, micError } = useTunerStore();
  const { toggle, resetHysteresis } = useAudioEngine();
  const wakeLockRef = useRef<WakeLockSentinel | null>(null);

  // Calibration state
  const { isCalibrating, calibrationCompletedAt, soundPrints, startCalibration, cancelCalibration, resetCalibration } = useCalibrationStore();
  const [showCalibrationResults, setShowCalibrationResults] = useState(false);

  // Track calibration completion
  const prevCompletedAt = useRef<number | null>(null);
  useEffect(() => {
    if (calibrationCompletedAt && calibrationCompletedAt !== prevCompletedAt.current) {
      prevCompletedAt.current = calibrationCompletedAt;
      setShowCalibrationResults(true);
    }
  }, [calibrationCompletedAt]);

  // Keep screen on while tuner is listening
  useEffect(() => {
    if (!isListening) {
      if (wakeLockRef.current) {
        wakeLockRef.current.release().catch(() => {});
        wakeLockRef.current = null;
      }
      return;
    }
    if ('wakeLock' in navigator) {
      navigator.wakeLock.request('screen')
        .then(sentinel => {
          wakeLockRef.current = sentinel;
          sentinel.addEventListener('release', () => { wakeLockRef.current = null; });
        })
        .catch(() => {});
    }
    const onVisChange = () => {
      if (document.visibilityState === 'visible' && isListening && 'wakeLock' in navigator && !wakeLockRef.current) {
        navigator.wakeLock.request('screen')
          .then(sentinel => {
            wakeLockRef.current = sentinel;
            sentinel.addEventListener('release', () => { wakeLockRef.current = null; });
          })
          .catch(() => {});
      }
    };
    document.addEventListener('visibilitychange', onVisChange);
    return () => document.removeEventListener('visibilitychange', onVisChange);
  }, [isListening]);

  const handleMicToggle = useCallback(async () => {
    try {
      await toggle();
    } catch (err: any) {
      console.error('Mic error:', err);
    }
  }, [toggle]);

  const handleTouchMic = useCallback((e: React.TouchEvent) => {
    e.preventDefault();
    handleMicToggle();
  }, [handleMicToggle]);

  const handleStartCalibration = useCallback(async () => {
    console.log('[CALIB DEBUG] Starting calibration. isListening:', isListening);
    startCalibration();
    // Reset hysteresis and enable bypass so any note is detected during calibration
    resetHysteresis();
    // Enable bypass on the engine so the jump filter doesn't block notes
    if (engineInstance) engineInstance.bypassHysteresis = true;
    // Ensure mic is listening — calibration needs audio input to detect keys.
    // Check store directly in case the closure is stale
    const currentlyListening = useTunerStore.getState().isListening;
    if (!currentlyListening) {
      try {
        console.log('[CALIB DEBUG] Mic not listening — starting mic...');
        await toggle();
        console.log('[CALIB DEBUG] Mic started successfully');
      } catch (err) {
        console.error('[CALIB DEBUG] Mic error during calibration start:', err);
        // Don't cancel calibration — let the overlay show the mic error.
        // User can still skip keys manually or grant mic permission.
      }
    }
  }, [startCalibration, isListening, toggle, resetHysteresis]);

  const handleStartTuning = useCallback(() => {
    setShowCalibrationResults(false);
  }, []);

  const handleRecalibrate = useCallback(() => {
    setShowCalibrationResults(false);
    resetCalibration();
    // Small delay then start again
    setTimeout(() => startCalibration(), 100);
  }, [resetCalibration, startCalibration]);

  // Calibration overlay renders ON TOP of the tuner (not replacing it)
  // so the audio engine stays alive and keeps feeding notes into calibrationStore
  const calibrationOverlay = isCalibrating ? <CalibrationOverlay /> : null;

  // Sync engine bypassHysteresis with calibration state
  useEffect(() => {
    if (engineInstance) {
      engineInstance.bypassHysteresis = isCalibrating;
    }
  }, [isCalibrating]);

  // Sync engine maxJumpSemitones with note switch mode
  const noteSwitchMode = useSettingsStore((s) => s.noteSwitchMode);
  useEffect(() => {
    if (engineInstance) {
      if (isCalibrating) {
        engineInstance.maxJumpSemitones = 127; // effectively no limit (bypassHysteresis handles it)
      } else if (noteSwitchMode === 'stepwise') {
        engineInstance.maxJumpSemitones = 2;
      } else {
        engineInstance.maxJumpSemitones = 6; // auto mode default
      }
    }
  }, [noteSwitchMode, isCalibrating]);

  // Results panel after calibration completes (replaces tuner view)
  if (showCalibrationResults && calibrationCompletedAt) {
    return (
      <CalibrationResultsPanel
        onStartTuning={handleStartTuning}
        onRecalibrate={handleRecalibrate}
      />
    );
  }

  return (
    <div className="min-h-screen bg-[#020617] flex flex-col">
      <main className="flex-1 flex flex-col items-center px-2 pt-0 pb-1 max-w-lg mx-auto w-full overflow-y-auto" style={{ gap: '2px' }}>
        {/* TuningMeter — note, freq, status all inside the arc */}
        <TuningMeter />

        {/* Note switch mode selector + manual step arrows */}
        <NoteSwitchSelector />

        {/* Error banner */}
        {micError && (
          <div className="w-full px-2 py-1 rounded bg-red-500/10 border border-red-500/30 text-red-400 text-xs whitespace-pre-line">{micError}</div>
        )}

        {/* Waveform + Spectrum — collapsible */}
        <div className="w-full">
          <button
            onClick={() => setShowVisuals(v => !v)}
            className="w-full flex items-center justify-between px-1 py-0.5 text-[10px] font-bold uppercase tracking-wider text-slate-500 hover:text-slate-300 transition-colors"
          >
            <span>Waveform &amp; Spectrum</span>
            <svg className={`w-3 h-3 transition-transform ${showVisuals ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
            </svg>
          </button>
          {showVisuals && (
            <div className="w-full flex" style={{ gap: '4px' }}>
              <div className="flex-1">
                <WaveformDisplay />
              </div>
              <div className="flex-1">
                <SpectrumView />
              </div>
            </div>
          )}
        </div>

        {/* Precision Tools — collapsible carousel */}
        <PrecisionTools />

        {/* Piano keyboard */}
        <PianoKeyboard />

        {/* Mic toggle + Calibrate + Log note */}
        <div className="flex items-center flex-wrap" style={{ gap: '8px' }}>
          <button
            onClick={handleMicToggle}
            onTouchEnd={handleTouchMic}
            className={`relative w-12 h-12 rounded-full flex items-center justify-center transition-all duration-200 shadow-lg ${
              isListening
                ? 'bg-red-500/20 border-2 border-red-500 shadow-red-500/30'
                : 'bg-cyan-500/20 border-2 border-cyan-500 shadow-cyan-500/30'
            }`}
            title={isListening ? 'Stop listening' : 'Start listening'}
          >
            {isListening ? (
              <svg className="w-5 h-5 text-red-400" fill="currentColor" viewBox="0 0 24 24"><rect x="6" y="6" width="12" height="12" rx="2" /></svg>
            ) : (
              <svg className="w-5 h-5 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M12 1a4 4 0 00-4 4v7a4 4 0 008 0V5a4 4 0 00-4-4z" />
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 10v2a7 7 0 01-14 0v-2" />
                <line x1="12" y1="19" x2="12" y2="23" />
                <line x1="8" y1="23" x2="16" y2="23" />
              </svg>
            )}
            {isListening && <span className="absolute inset-0 rounded-full border-2 border-red-500/50 animate-ping" />}
          </button>

          <span className={`text-xs font-medium ${isListening ? 'text-red-400' : 'text-slate-500'}`}>
            {isListening ? 'Listening...' : 'Tap to start'}
          </span>

          {/* Calibrate button */}
          <button
            onClick={handleStartCalibration}
            className="px-3 py-1.5 rounded-lg bg-amber-500/15 border border-amber-500/30 text-amber-400 text-xs font-bold hover:bg-amber-500/25 transition-colors"
            title="Run 88-key calibration test"
          >
            🔧 Calibrate
          </button>

          {isActive && noteName && (
            <button
              onClick={() => setShowManualEntry(true)}
              className="px-3 py-1.5 rounded-lg bg-green-500/15 border border-green-500/30 text-green-400 text-xs font-bold hover:bg-green-500/25 transition-colors"
              title="Log current note"
            >
              + Log {noteName}{octave}
            </button>
          )}
        </div>

        {/* Session tracker */}
        <SessionTracker />
      </main>

      {showSettings && <SettingsPanel onClose={() => setShowSettings(false)} />}
      {showManualEntry && (
        <ManualNoteEntry onClose={() => setShowManualEntry(false)} defaultNote={noteName} defaultOctave={octave} defaultMidi={noteNum} />
      )}
      {calibrationOverlay}
    </div>
  );
}