// src/store/authStore.ts — Auth state management with demo pro user

import { create } from 'zustand';

export interface AuthState {
  isAuthenticated: boolean;
  email: string | null;
  displayName: string | null;
  subscriptionTier: 'free' | 'plus' | 'pro';
  isLoading: boolean;

  login: (email: string, tier?: 'free' | 'plus' | 'pro') => void;
  logout: () => void;
  setTier: (tier: 'free' | 'plus' | 'pro') => void;
}

const AUTH_KEY = 'keytune-auth';

/** Demo accounts — in production these would be verified against Supabase */
export const DEMO_ACCOUNTS: Record<string, { password: string; tier: 'free' | 'plus' | 'pro' }> = {
  'pro@keytune.app': { password: 'KeyTunePro2026!', tier: 'pro' },
  'plus@keytune.app': { password: 'KeyTunePlus2026!', tier: 'plus' },
  'demo@keytune.app': { password: 'demo', tier: 'pro' },
};

export function validateDemoLogin(email: string, password: string): 'free' | 'plus' | 'pro' | null {
  const account = DEMO_ACCOUNTS[email.toLowerCase()];
  if (account && account.password === password) return account.tier;
  return null;
}

function loadAuth(): Partial<AuthState> {
  try {
    const raw = localStorage.getItem(AUTH_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveAuth(state: AuthState): void {
  try {
    localStorage.setItem(AUTH_KEY, JSON.stringify({
      isAuthenticated: state.isAuthenticated,
      email: state.email,
      displayName: state.displayName,
      subscriptionTier: state.subscriptionTier,
    }));
  } catch {
    // silent
  }
}

const saved = loadAuth();

// Auto-upgrade demo accounts to their correct tier (migration fix)
if (saved.email && DEMO_ACCOUNTS[saved.email as string] && saved.subscriptionTier !== DEMO_ACCOUNTS[saved.email as string].tier) {
  saved.subscriptionTier = DEMO_ACCOUNTS[saved.email as string].tier;
  try { localStorage.setItem(AUTH_KEY, JSON.stringify(saved)); } catch {}
}

export const useAuthStore = create<AuthState>((set, get) => ({
  isAuthenticated: saved.isAuthenticated ?? false,
  email: saved.email ?? null,
  displayName: saved.displayName ?? null,
  subscriptionTier: saved.subscriptionTier ?? 'free',
  isLoading: false,

  login: (email, tier = 'free') => {
    set({
      isAuthenticated: true,
      email,
      displayName: email.split('@')[0],
      subscriptionTier: tier,
      isLoading: false,
    });
    saveAuth(get());
  },

  logout: () => {
    set({
      isAuthenticated: false,
      email: null,
      displayName: null,
      subscriptionTier: 'free',
    });
    localStorage.removeItem(AUTH_KEY);
  },

  setTier: (subscriptionTier) => {
    set({ subscriptionTier });
    saveAuth(get());
  },
}));