// src/components/auth/SubscribeModal.tsx — 3-tier pricing with auth integration

import { useAuthStore } from '../../store/authStore';

interface Props {
  open: boolean;
  onClose: () => void;
}

const PLANS = [
  {
    id: 'free' as const,
    name: 'Free',
    price: '£0',
    period: 'forever',
    features: [
      'Real-time pitch detection',
      'Note & cents display',
      'C3–C5 range (2 octaves)',
      'Basic session tracking',
      'Waveform & spectrum view',
    ],
    locked: [] as string[],
    color: 'slate',
    border: 'border-slate-600',
    bg: 'bg-slate-800/50',
    buttonText: 'Current Plan',
  },
  {
    id: 'plus' as const,
    name: 'Plus',
    price: '£4.99',
    period: '/month',
    features: [
      'Everything in Free',
      'Full 88-key range (A0–C8)',
      'Railsback stretch tuning',
      'Auto-record notes (±5¢)',
      'Session export (JSON/CSV)',
      'Custom reference pitch',
    ],
    locked: [] as string[],
    color: 'cyan',
    border: 'border-cyan-500/40',
    bg: 'bg-cyan-500/5',
    buttonText: 'Upgrade to Plus',
    popular: true,
  },
  {
    id: 'pro' as const,
    name: 'Pro',
    price: '£9.99',
    period: '/month',
    features: [
      'Everything in Plus',
      'Multiple tuning temperaments',
      'Tuning history & analytics',
      'Cloud sync & backup',
      'Priority support',
      'Commercial license',
    ],
    locked: [] as string[],
    color: 'amber',
    border: 'border-amber-500/40',
    bg: 'bg-amber-500/5',
    buttonText: 'Upgrade to Pro',
  },
];

export function SubscribeModal({ open, onClose }: Props) {
  const { subscriptionTier, setTier } = useAuthStore();

  if (!open) return null;

  const colorMap: Record<string, { button: string; buttonHover: string }> = {
    slate: { button: 'bg-slate-600', buttonHover: 'bg-slate-500' },
    cyan: { button: 'bg-cyan-500 shadow-lg shadow-cyan-500/25', buttonHover: 'bg-cyan-600' },
    amber: { button: 'bg-amber-500 shadow-lg shadow-amber-500/25', buttonHover: 'bg-amber-600' },
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-50 flex items-start justify-center p-4 overflow-y-auto">
      <div className="my-8 w-full max-w-3xl">
        {/* Close button */}
        <div className="flex justify-end mb-4">
          <button
            onClick={onClose}
            className="p-2 rounded-lg bg-slate-800/80 text-slate-400 hover:text-slate-200 transition-colors"
          >
            ✕
          </button>
        </div>

        <h2 className="text-2xl font-bold text-slate-100 text-center mb-1 font-['Orbitron']">
          Choose Your Plan
        </h2>
        <p className="text-slate-400 text-center mb-8 text-sm">
          Unlock the full potential of KeyTune
        </p>

        {/* Pricing cards */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          {PLANS.map((plan) => {
            const isCurrent = subscriptionTier === plan.id;
            const colors = colorMap[plan.color];

            return (
              <div
                key={plan.id}
                className={`relative rounded-2xl border ${plan.border} ${plan.bg} p-5 flex flex-col ${
                  plan.popular ? 'sm:scale-105 sm:-my-2' : ''
                }`}
              >
                {plan.popular && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 px-3 py-1 rounded-full bg-cyan-500 text-white text-[10px] font-bold uppercase tracking-wider">
                    Most Popular
                  </div>
                )}

                <div className="mb-4">
                  <h3 className="text-lg font-bold text-slate-100 font-['Orbitron']">{plan.name}</h3>
                  <div className="mt-1">
                    <span className="text-3xl font-black text-slate-100">{plan.price}</span>
                    <span className="text-slate-400 text-sm">{plan.period}</span>
                  </div>
                </div>

                <ul className="space-y-2 flex-1 text-sm">
                  {plan.features.map((f, i) => (
                    <li key={i} className="flex items-start gap-2 text-slate-300">
                      <svg className="w-4 h-4 text-green-400 mt-0.5 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                      </svg>
                      {f}
                    </li>
                  ))}
                </ul>

                <button
                  onClick={() => {
                    if (!isCurrent) {
                      setTier(plan.id);
                    }
                  }}
                  disabled={isCurrent}
                  className={`mt-5 w-full py-2.5 rounded-xl font-bold text-sm transition-colors ${
                    isCurrent
                      ? 'bg-slate-700 text-slate-400 cursor-not-allowed'
                      : `${colors.button} text-white hover:${colors.buttonHover}`
                  }`}
                >
                  {isCurrent ? 'Current Plan' : plan.buttonText}
                </button>
              </div>
            );
          })}
        </div>

        <p className="text-center text-xs text-slate-500 mt-6">
          Demo mode — payment integration requires Supabase + Stripe setup
        </p>
      </div>
    </div>
  );
}