// src/components/tuner/NoteSwitchSelector.tsx
// 3-mode note switching: Auto / Stepwise / Lock
// Plus left/right arrows for manual semitone stepping and double-tap for octave

import { useCallback } from 'react';
import { useSettingsStore, NoteSwitchMode } from '../../store/settingsStore';
import { useTunerStore } from '../../store/tunerStore';

const MODES: { key: NoteSwitchMode; label: string; icon: string }[] = [
  { key: 'auto', label: 'AUTO', icon: '⚡' },
  { key: 'stepwise', label: 'STEP', icon: '↕' },
  { key: 'lock', label: 'LOCK', icon: '🔒' },
];

export default function NoteSwitchSelector() {
  const noteSwitchMode = useSettingsStore((s) => s.noteSwitchMode);
  const setNoteSwitchMode = useSettingsStore((s) => s.setNoteSwitchMode);
  const noteNum = useTunerStore((s) => s.noteNum);
  const setPitch = useTunerStore((s) => s.setPitch);
  const isActive = useTunerStore((s) => s.isActive);

  // Step semitone up/down. Uses noteNum from store.
  const stepSemitone = useCallback(
    (direction: 1 | -1) => {
      const current = useTunerStore.getState().noteNum;
      if (current === null) return;
      const next = current + direction;
      if (next < 21 || next > 108) return; // A0–C8 range
      const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
      const name = names[next % 12];
      const octave = Math.floor(next / 12) - 1;
      const refA = useSettingsStore.getState().referenceA;
      const idealFreq = refA * Math.pow(2, (next - 69) / 12);
      setPitch(idealFreq, name, octave, next, 0, idealFreq);
    },
    [setPitch]
  );

  // Step octave up/down
  const stepOctave = useCallback(
    (direction: 1 | -1) => {
      const current = useTunerStore.getState().noteNum;
      if (current === null) return;
      const next = current + direction * 12;
      if (next < 21 || next > 108) return;
      const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
      const name = names[next % 12];
      const octave = Math.floor(next / 12) - 1;
      const refA = useSettingsStore.getState().referenceA;
      const idealFreq = refA * Math.pow(2, (next - 69) / 12);
      setPitch(idealFreq, name, octave, next, 0, idealFreq);
    },
    [setPitch]
  );

  return (
    <div className="flex items-center gap-1 justify-center">
      {/* Left arrow — semitone down, double-tap for octave down */}
      <button
        onClick={() => stepSemitone(-1)}
        onDoubleClick={(e) => { e.preventDefault(); stepOctave(-1); }}
        className="w-8 h-7 flex items-center justify-center rounded bg-slate-800/70 text-slate-300 hover:bg-slate-700 active:bg-slate-600 text-xs transition-colors"
        title="Semitone down (double-tap: octave down)"
        disabled={!isActive && noteNum === null}
      >
        ◀
      </button>

      {/* Mode buttons */}
      <div className="flex rounded-md overflow-hidden border border-slate-700/50">
        {MODES.map(({ key, label, icon }) => (
          <button
            key={key}
            onClick={() => setNoteSwitchMode(key)}
            className={`px-2 py-0.5 text-[9px] font-bold tracking-wider transition-colors ${
              noteSwitchMode === key
                ? 'bg-cyan-600/80 text-white'
                : 'bg-slate-800/60 text-slate-400 hover:text-slate-200 hover:bg-slate-700/60'
            }`}
            title={
              key === 'auto'
                ? 'Auto: app jumps to any detected note'
                : key === 'stepwise'
                ? 'Stepwise: only follow adjacent notes, no big jumps'
                : 'Lock: stay on current note, ignore detected changes'
            }
          >
            {icon} {label}
          </button>
        ))}
      </div>

      {/* Right arrow — semitone up, double-tap for octave up */}
      <button
        onClick={() => stepSemitone(1)}
        onDoubleClick={(e) => { e.preventDefault(); stepOctave(1); }}
        className="w-8 h-7 flex items-center justify-center rounded bg-slate-800/70 text-slate-300 hover:bg-slate-700 active:bg-slate-600 text-xs transition-colors"
        title="Semitone up (double-tap: octave up)"
        disabled={!isActive && noteNum === null}
      >
        ▶
      </button>
    </div>
  );
}