// src/pages/ProfilesPage.tsx — Piano profile list with invoice generation

import { useState } from 'react';
import { usePianoProfileStore, PianoProfile } from '../store/pianoProfileStore';
import { InvoiceExport } from '../components/calibration/InvoiceExport';

const CURRENCY_SYMBOLS: Record<string, string> = { GBP: '£', EUR: '€', USD: '$', BRL: 'R$' };

export function ProfilesPage() {
  const { profiles, deleteProfile, updateProfile } = usePianoProfileStore();
  const [selectedProfile, setSelectedProfile] = useState<PianoProfile | null>(null);

  if (selectedProfile) {
    return (
      <div className="min-h-screen bg-[#020617] p-4">
        <div className="max-w-lg mx-auto">
          <button
            onClick={() => setSelectedProfile(null)}
            className="text-xs text-slate-500 hover:text-slate-300 mb-4 transition-colors"
          >
            ← Back to profiles
          </button>
          <InvoiceExport profile={selectedProfile} onBack={() => setSelectedProfile(null)} />
        </div>
      </div>
    );
  }

  if (profiles.length === 0) {
    return (
      <div className="min-h-screen bg-[#020617] p-4">
        <div className="max-w-lg mx-auto text-center py-16">
          <div className="text-6xl mb-4">🎹</div>
          <h1 className="text-lg font-bold font-['Orbitron'] text-slate-200 mb-2">Piano Profiles</h1>
          <p className="text-xs text-slate-400 mb-6">No profiles saved yet.</p>
          <p className="text-[10px] text-slate-500">Run a calibration test to create your first piano profile with sound print data.</p>
        </div>
      </div>
    );
  }

  // Sort newest first
  const sorted = [...profiles].sort((a, b) => b.createdAt - a.createdAt);

  return (
    <div className="min-h-screen bg-[#020617] p-4">
      <div className="max-w-lg mx-auto">
        <h1 className="text-lg font-bold font-['Orbitron'] text-slate-200 mb-4">Piano Profiles</h1>
        <p className="text-xs text-slate-400 mb-4">{profiles.length} profile{profiles.length !== 1 ? 's' : ''} saved</p>

        <div className="space-y-3">
          {sorted.map(profile => {
            const capturedCount = Object.keys(profile.soundPrints).length;
            const sym = CURRENCY_SYMBOLS[profile.currency] || profile.currency;
            const invoiceNum = profile.invoiceNumber || `KT-${profile.id.slice(0, 8).toUpperCase()}`;

            return (
              <div
                key={profile.id}
                className="bg-slate-800/30 rounded-xl p-4 border border-slate-700/30 hover:border-cyan-500/30 transition-all cursor-pointer"
                onClick={() => setSelectedProfile(profile)}
              >
                {/* Top row */}
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <div className="text-sm font-bold text-slate-200">{profile.clientName || 'Unnamed Client'}</div>
                    <div className="text-[10px] text-slate-500 mt-0.5">
                      {profile.pianoMake} {profile.pianoModel}
                      {profile.pianoSerial && ` · S/N ${profile.pianoSerial}`}
                    </div>
                  </div>
                  {profile.serviceFee && (
                    <span className="text-sm font-bold text-cyan-400 font-['Orbitron']">{sym}{profile.serviceFee}</span>
                  )}
                </div>

                {/* Stats row */}
                <div className="flex items-center gap-4 text-[10px] text-slate-400">
                  <span>{capturedCount} keys</span>
                  {profile.flaggedKeys.length > 0 && (
                    <span className="text-amber-400">{profile.flaggedKeys.length} flagged</span>
                  )}
                  <span>{new Date(profile.calibrationDate).toLocaleDateString()}</span>
                  <span className="ml-auto text-slate-600">{invoiceNum}</span>
                </div>

                {/* Service badge */}
                <div className="mt-2 flex items-center gap-2">
                  <span className="text-[9px] px-2 py-0.5 rounded-full bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 capitalize">
                    {profile.serviceType.replace(/_/g, ' ')}
                  </span>
                  {profile.flaggedKeys.filter(f => f.level === 'high').length > 0 && (
                    <span className="text-[9px] px-2 py-0.5 rounded-full bg-red-500/10 text-red-400 border border-red-500/20">
                      {profile.flaggedKeys.filter(f => f.level === 'high').length} high priority
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}