// src/audio/NoteUtils.ts — Note/frequency math. Pure functions, no side effects.

export const NOTE_NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'] as const;

import { getCentsWithStretch } from './StretchTuning';

export interface NoteInfo {
  noteNum: number;    // MIDI note number (21=A0, 108=C8)
  name: string;       // e.g. "A", "C♯"
  octave: number;     // e.g. 4 for A4
  idealFreq: number;  // Equal temperament frequency
  cents: number;      // Cents deviation (float, round at display)
  display: string;    // e.g. "A4", "C♯5"
}

/**
 * Convert a detected frequency to a note descriptor.
 * @param freq - Detected frequency in Hz
 * @param referenceA - Reference pitch for A4 (default 440)
 * @param useStretch - Apply Railsback curve (default false)
 * @param calibOffset - Calibration offset in cents (default 0)
 */
export function noteFromFrequency(freq: number, referenceA = 440, useStretch = false, calibOffset = 0): NoteInfo {
  const noteNum = Math.round(12 * Math.log2(freq / referenceA) + 69);
  const name = NOTE_NAMES[((noteNum % 12) + 12) % 12];
  const octave = Math.floor(noteNum / 12) - 1;
  const idealFreq = referenceA * Math.pow(2, (noteNum - 69) / 12);
  const cents = getCentsWithStretch(freq, noteNum, referenceA, useStretch, calibOffset);
  return { noteNum, name, octave, idealFreq, cents, display: `${name}${octave}` };
}

/**
 * Check if a MIDI note number is within the free-tier range (C3=48 to C5=72).
 */
export function isFreeTierNote(noteNum: number): boolean {
  return noteNum >= 48 && noteNum <= 72;
}

/**
 * Format cents value for display with sign.
 */
export function formatCents(cents: number): string {
  const c = Math.round(cents);
  const sign = c > 0 ? '+' : '';
  return `${sign}${c}¢`;
}

/**
 * Format frequency for display.
 */
export function formatHz(freq: number): string {
  return freq.toFixed(1) + ' Hz';
}

/**
 * Get just the note name from a frequency.
 */
export function frequencyToNoteName(freq: number, referenceA = 440): string {
  const noteNum = Math.round(12 * Math.log2(freq / referenceA) + 69);
  return NOTE_NAMES[((noteNum % 12) + 12) % 12];
}

/**
 * Get the MIDI note number from a frequency.
 */
export function frequencyToNoteNumber(freq: number): number {
  return Math.round(12 * Math.log2(freq / 440) + 69);
}

/**
 * Calculate cents deviation from an ideal frequency.
 * @param freq - Actual measured frequency
 * @param ideal - Ideal (equal temperament) frequency
 */
export function centsDeviation(freq: number, ideal: number): number {
  return 1200 * Math.log2(freq / ideal);
}

// Alias for backward compatibility
export const cents = centsDeviation;