// src/components/calibration/CalibrationOverlay.tsx — Full-screen calibration test overlay

import { useCalibrationStore } from '../../store/calibrationStore';
import { useTunerStore } from '../../store/tunerStore';
import { CalibrationKeyboard } from './CalibrationKeyboard';

const MIDI_OFFSET = 21; // A0 = MIDI 21
const TOTAL_KEYS = 88;

function midiToNoteName(midi: number): string {
  const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
  const name = names[midi % 12];
  const octave = Math.floor(midi / 12) - 1;
  return `${name}${octave}`;
}

export default function CalibrationOverlay() {
  const {
    isCalibrating,
    currentMidi,
    soundPrints,
    keyStatuses,
    flaggedKeys,
    skipKey,
    cancelCalibration,
  } = useCalibrationStore();

  // Show currently detected note from tuner store (for user feedback)
  const { noteName: detectedName, octave: detectedOctave, noteNum: detectedMidi, isActive } = useTunerStore();

  if (!isCalibrating) return null;

  const capturedCount = Object.keys(soundPrints).length;
  const progress = capturedCount / TOTAL_KEYS;
  const currentNoteName = currentMidi >= MIDI_OFFSET && currentMidi < MIDI_OFFSET + TOTAL_KEYS
    ? midiToNoteName(currentMidi)
    : '—';

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        zIndex: 50,
        background: '#020617',
        display: 'flex',
        flexDirection: 'column',
        fontFamily: '"Exo 2", sans-serif',
        color: '#e2e8f0',
        overflow: 'auto',
      }}
    >
      {/* Top Bar */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '16px 24px',
          borderBottom: '1px solid #1e293b',
        }}
      >
        <h1
          style={{
            fontFamily: '"Orbitron", monospace',
            fontWeight: 700,
            fontSize: '1.25rem',
            letterSpacing: '0.15em',
            color: '#06b6d4',
          }}
        >
          CALIBRATION MODE
        </h1>
        <span
          style={{
            fontFamily: '"Share Tech Mono", monospace',
            fontSize: '1rem',
            color: '#94a3b8',
          }}
        >
          {capturedCount}/{TOTAL_KEYS}
        </span>
        <button
          onClick={cancelCalibration}
          style={{
            background: 'transparent',
            border: '1px solid #334155',
            borderRadius: '6px',
            color: '#94a3b8',
            padding: '6px 16px',
            cursor: 'pointer',
            fontSize: '0.875rem',
            fontFamily: '"Exo 2", sans-serif',
          }}
        >
          Cancel
        </button>
      </div>

      {/* Progress Bar */}
      <div
        style={{
          height: '3px',
          background: '#1e293b',
        }}
      >
        <div
          style={{
            height: '100%',
            width: `${progress * 100}%`,
            background: '#06b6d4',
            transition: 'width 0.3s ease',
          }}
        />
      </div>

      {/* Main Content Area */}
      <div
        style={{
          flex: 1,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '24px',
          gap: '24px',
        }}
      >
        {/* Current Key Display */}
        <div
          style={{
            textAlign: 'center',
          }}
        >
          <div
            className="calibration-key-pulse"
            style={{
              fontFamily: '"Orbitron", monospace',
              fontWeight: 700,
              fontSize: '5rem',
              color: '#ef4444',
              textShadow: '0 0 30px rgba(239, 68, 68, 0.6), 0 0 60px rgba(239, 68, 68, 0.3)',
              animation: 'pulseRedGlow 1.5s ease-in-out infinite',
              lineHeight: 1,
            }}
          >
            {currentNoteName}
          </div>
          <div
            style={{
              fontFamily: '"Exo 2", sans-serif',
              fontSize: '0.8rem',
              fontWeight: 600,
              letterSpacing: '0.2em',
              color: '#06b6d4',
              marginTop: '12px',
              textTransform: 'uppercase',
            }}
          >
            PLAY NEXT →
          </div>
          {/* Detected note feedback */}
          {isActive && detectedName && (
            <div
              style={{
                marginTop: '8px',
                fontFamily: '"Share Tech Mono", monospace',
                fontSize: '0.85rem',
                color: detectedMidi === currentMidi ? '#22c55e' : '#94a3b8',
              }}
            >
              Detected: {detectedName}{detectedOctave}
              {detectedMidi === currentMidi ? ' ✓' : ` (expected: ${currentNoteName})`}
            </div>
          )}
        </div>

        {/* Piano Keyboard */}
        <div
          style={{
            width: '100%',
            maxWidth: '800px',
            padding: '0 16px',
          }}
        >
          <CalibrationKeyboard />
        </div>

        {/* Flagged Keys Section */}
        {flaggedKeys.length > 0 && (
          <div
            style={{
              width: '100%',
              maxWidth: '600px',
              background: '#0f172a',
              borderRadius: '8px',
              border: '1px solid #1e293b',
              padding: '16px',
            }}
          >
            <h3
              style={{
                fontFamily: '"Orbitron", monospace',
                fontSize: '0.75rem',
                letterSpacing: '0.12em',
                color: '#eab308',
                marginBottom: '12px',
                textTransform: 'uppercase',
              }}
            >
              Flagged Keys ({flaggedKeys.length})
            </h3>
            <div
              style={{
                display: 'flex',
                flexWrap: 'wrap',
                gap: '8px',
              }}
            >
              {flaggedKeys.map((fk) => (
                <div
                  key={fk.midiNote}
                  style={{
                    background: '#1e293b',
                    borderRadius: '6px',
                    padding: '8px 12px',
                    border: `1px solid ${fk.level === 'high' ? '#ef4444' : '#eab308'}`,
                    fontSize: '0.8rem',
                  }}
                >
                  <span
                    style={{
                      fontFamily: '"Orbitron", monospace',
                      color: fk.level === 'high' ? '#ef4444' : '#eab308',
                      fontWeight: 600,
                    }}
                  >
                    {fk.noteName}{fk.octave}
                  </span>
                  <span style={{ color: '#94a3b8', marginLeft: '8px' }}>
                    {fk.issues.join(', ').replace(/_/g, ' ')}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Bottom Buttons */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '16px',
          padding: '16px 24px',
          borderTop: '1px solid #1e293b',
        }}
      >
        {currentMidi >= MIDI_OFFSET && currentMidi < MIDI_OFFSET + TOTAL_KEYS && (
          <button
            onClick={() => skipKey(currentMidi)}
            style={{
              background: 'transparent',
              border: '1px solid #334155',
              borderRadius: '6px',
              color: '#64748b',
              padding: '10px 20px',
              cursor: 'pointer',
              fontSize: '0.85rem',
              fontFamily: '"Exo 2", sans-serif',
            }}
          >
            Skip Key
          </button>
        )}
        <button
          onClick={cancelCalibration}
          style={{
            background: '#1e293b',
            border: '1px solid #334155',
            borderRadius: '6px',
            color: '#ef4444',
            padding: '8px 20px',
            cursor: 'pointer',
            fontSize: '0.85rem',
            fontFamily: '"Exo 2", sans-serif',
          }}
        >
          Cancel Calibration
        </button>
      </div>

      {/* Inline keyframes for pulse animation */}
      <style>{`
        @keyframes pulseRedGlow {
          0%, 100% { text-shadow: 0 0 30px rgba(239, 68, 68, 0.6), 0 0 60px rgba(239, 68, 68, 0.3); }
          50% { text-shadow: 0 0 50px rgba(239, 68, 68, 0.9), 0 0 100px rgba(239, 68, 68, 0.5), 0 0 150px rgba(239, 68, 68, 0.2); }
        }
      `}</style>
    </div>
  );
}