// src/App.tsx — Root layout: landing page (logged out), tuner app (logged in), footer nav only

import { useState } from 'react';
import { LandingPage } from './pages/LandingPage';
import { TunerPage } from './pages/TunerPage';
import { SessionPage } from './pages/SessionPage';
import { SettingsPage } from './pages/SettingsPage';
import { ProfilesPage } from './pages/ProfilesPage';
import { SubscribeModal } from './components/auth/SubscribeModal';
import { useAuthStore } from './store/authStore';
import { useInstallPrompt } from './hooks/useInstallPrompt';

type Page = 'tuner' | 'session' | 'profiles' | 'settings';

export default function App() {
  const [page, setPage] = useState<Page>('tuner');
  const [showSubscribe, setShowSubscribe] = useState(false);
  const { isAuthenticated, email, subscriptionTier, logout } = useAuthStore();
  const { promptInstall, shouldShowBanner } = useInstallPrompt();

  // Logged out — show landing page
  if (!isAuthenticated) {
    return <LandingPage />;
  }

  // Logged in — show tuner app with footer nav only (no header)
  const renderPage = () => {
    switch (page) {
      case 'tuner':
        return <TunerPage />;
      case 'session':
        return <SessionPage />;
      case 'profiles':
        return <ProfilesPage />;
      case 'settings':
        return <SettingsPage />;
    }
  };

  return (
    <div className="h-screen flex flex-col bg-[#020617] text-slate-100 overflow-hidden">
      {/* Page content — NO header */}
      <div className="flex-1 overflow-y-auto">
        {renderPage()}
      </div>

      {/* Bottom navigation — the only nav, footer only */}
      <nav className="flex-shrink-0 border-t border-slate-800 bg-slate-900/95 backdrop-blur-lg safe-area-pb">
        <div className="max-w-lg mx-auto flex">
          {[
            { id: 'tuner' as Page, label: 'Tuner', icon: '♩' },
            { id: 'session' as Page, label: 'Session', icon: '☰' },
            { id: 'profiles' as Page, label: 'Profiles', icon: '🎹' },
            { id: 'settings' as Page, label: 'Settings', icon: '⚙' },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => setPage(item.id)}
              className={`flex-1 py-2.5 flex flex-col items-center gap-0.5 transition-colors ${
                page === item.id
                  ? 'text-cyan-400'
                  : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              <span className="text-lg">{item.icon}</span>
              <span className="text-[10px] font-medium">{item.label}</span>
            </button>
          ))}

          {/* Upgrade / tier badge */}
          {subscriptionTier !== 'pro' && (
            <button
              onClick={() => setShowSubscribe(true)}
              className="flex-1 py-2.5 flex flex-col items-center gap-0.5 text-amber-400 hover:text-amber-300 transition-colors"
            >
              <span className="text-lg">★</span>
              <span className="text-[10px] font-medium">Pro</span>
            </button>
          )}

          {/* Logout */}
          <button
            onClick={logout}
            className="flex-1 py-2.5 flex flex-col items-center gap-0.5 text-slate-500 hover:text-red-400 transition-colors"
            title={`Logged in as ${email?.split('@')[0] || 'user'}`}
          >
            <span className="text-lg">⏻</span>
            <span className="text-[10px] font-medium">Logout</span>
          </button>
        </div>

        {/* Install PWA row */}
        {shouldShowBanner && (
          <button
            onClick={promptInstall}
            className="w-full py-2 text-xs text-cyan-400 bg-cyan-500/10 hover:bg-cyan-500/20 transition-colors border-t border-slate-800 flex items-center justify-center gap-1.5"
          >
            📲 Install KeyTune
          </button>
        )}
      </nav>

      {/* Subscribe modal */}
      <SubscribeModal
        open={showSubscribe}
        onClose={() => setShowSubscribe(false)}
      />
    </div>
  );
}