// src/store/settingsStore.ts — User settings: reference pitch, tuning mode, sensitivity

import { create } from 'zustand';

export type TuningMode = 'equal' | 'stretch';
export type SensitivityLevel = 'slow' | 'normal' | 'fast';
export type NoteSwitchMode = 'auto' | 'stepwise' | 'lock';

export interface SettingsState {
  referenceA: number;
  tuningMode: TuningMode;
  sensitivity: SensitivityLevel;
  calibrationOffset: number; // cents
  subscriptionTier: 'free' | 'plus' | 'pro';
  noteSwitchMode: NoteSwitchMode;

  // Actions
  setReferenceA: (hz: number) => void;
  setTuningMode: (mode: TuningMode) => void;
  setSensitivity: (level: SensitivityLevel) => void;
  setCalibrationOffset: (cents: number) => void;
  setSubscriptionTier: (tier: 'free' | 'plus' | 'pro') => void;
  setNoteSwitchMode: (mode: NoteSwitchMode) => void;
}

const STORAGE_KEY = 'keytune-settings';

function loadSettings(): Partial<SettingsState> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveSettings(state: SettingsState): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({
      referenceA: state.referenceA,
      tuningMode: state.tuningMode,
      sensitivity: state.sensitivity,
      calibrationOffset: state.calibrationOffset,
      noteSwitchMode: state.noteSwitchMode,
    }));
  } catch {
    // localStorage may be unavailable — silent fail
  }
}

const defaults = loadSettings();

export const useSettingsStore = create<SettingsState>((set, get) => ({
  referenceA: defaults.referenceA ?? 440,
  tuningMode: defaults.tuningMode ?? 'equal',
  sensitivity: defaults.sensitivity ?? 'normal',
  calibrationOffset: defaults.calibrationOffset ?? 0,
  subscriptionTier: 'free',
  noteSwitchMode: defaults.noteSwitchMode ?? 'auto',

  setReferenceA: (referenceA) => { set({ referenceA }); saveSettings(get()); },
  setTuningMode: (tuningMode) => { set({ tuningMode }); saveSettings(get()); },
  setSensitivity: (sensitivity) => { set({ sensitivity }); saveSettings(get()); },
  setCalibrationOffset: (calibrationOffset) => { set({ calibrationOffset }); saveSettings(get()); },
  setSubscriptionTier: (subscriptionTier) => set({ subscriptionTier }),
  setNoteSwitchMode: (noteSwitchMode) => { set({ noteSwitchMode }); saveSettings(get()); },
}));