// src/audio/PitchDetector.ts — YIN autocorrelation pitch detection algorithm
// Pure TypeScript — NO React imports. Communicates via Zustand store only.

/**
 * Detect the fundamental frequency from an audio buffer using YIN-style autocorrelation.
 * @param buffer - Float32Array of audio samples from AnalyserNode
 * @param sampleRate - Sample rate in Hz (typically 44100)
 * @returns Detected frequency in Hz, or -1 if silent or out of piano range
 */
export function detectPitch(buffer: Float32Array, sampleRate: number): number {
  const SIZE = buffer.length;

  // 1. RMS silence gate
  let rms = 0;
  for (let i = 0; i < SIZE; i++) rms += buffer[i] ** 2;
  rms = Math.sqrt(rms / SIZE);
  if (rms < 0.01) return -1;

  // 2. Apply Hanning window to reduce spectral leakage
  const win = new Float32Array(SIZE);
  for (let i = 0; i < SIZE; i++) {
    win[i] = buffer[i] * 0.5 * (1 - Math.cos((2 * Math.PI * i) / (SIZE - 1)));
  }

  // 3. Trim zero-crossing edges to reduce noise artifacts
  let r1 = 0;
  let r2 = SIZE - 1;
  for (let i = 0; i < SIZE / 2; i++) {
    if (Math.abs(win[i]) > 0.2) {
      r1 = i;
      break;
    }
  }
  for (let i = 1; i < SIZE / 2; i++) {
    if (Math.abs(win[SIZE - i]) > 0.2) {
      r2 = SIZE - i;
      break;
    }
  }

  const buf = win.subarray(r1, r2 + 1);
  const len = buf.length;
  if (len < 4) return -1;

  // 4. Autocorrelation
  const c = new Float32Array(len);
  for (let i = 0; i < len; i++) {
    for (let j = 0; j < len - i; j++) {
      c[i] += buf[j] * buf[j + i];
    }
  }

  // 5. Find first dip (where autocorrelation starts rising — the fundamental)
  let d = 0;
  while (d < len - 1 && c[d] > c[d + 1]) d++;

  // 6. Find global maximum after the dip
  let maxVal = -1;
  let maxPos = -1;
  for (let i = d; i < len; i++) {
    if (c[i] > maxVal) {
      maxVal = c[i];
      maxPos = i;
    }
  }
  if (maxPos <= 0) return -1;

  // 7. Parabolic interpolation for sub-sample accuracy
  let T0 = maxPos;
  if (T0 > 0 && T0 < len - 1) {
    const a = (c[T0 - 1] + c[T0 + 1] - 2 * c[T0]) / 2;
    const b = (c[T0 + 1] - c[T0 - 1]) / 2;
    if (a !== 0) T0 -= b / (2 * a);
  }
  if (T0 <= 0) return -1;

  const freq = sampleRate / T0;

  // 8. Clamp to piano range: A0 (27.5 Hz) to C8 (4186 Hz)
  if (freq < 27.5 || freq > 4186) return -1;
  return freq;
}