// src/store/calibrationStore.ts — Calibration test state: 88-key sound prints

import { create } from 'zustand';
import { useTunerStore } from './tunerStore';

export interface SoundPrint {
  midiNote: number;
  noteName: string;
  octave: number;
  frequency: number;
  cents: number;
  idealFreq: number;
  inharmonicity: number;     // B value (inharmonicity coefficient)
  decayMs: number;           // sustain decay time in ms
  amplitude: number;         // peak amplitude (normalized 0–1)
  beating: number;           // beating rate Hz between unisons
  capturedAt: number;        // timestamp
}

export type KeyStatus = 'pending' | 'current' | 'captured' | 'flagged';

export type FlagLevel = 'none' | 'moderate' | 'high';

export interface FlaggedKey {
  midiNote: number;
  noteName: string;
  octave: number;
  issues: string[];    // e.g. ['high_inharmonicity', 'fast_decay', 'severe_beating']
  level: FlagLevel;
}

export interface CalibrationState {
  // Calibration session
  isCalibrating: boolean;
  currentMidi: number;           // next key to play (0=A0, 87=C8 mapped to MIDI 21-108)
  soundPrints: Record<number, SoundPrint>;
  keyStatuses: Record<number, KeyStatus>;
  flaggedKeys: FlaggedKey[];
  calibrationStartedAt: number | null;
  calibrationCompletedAt: number | null;
  lastCaptureAt: number;          // timestamp of last capture — prevents rapid double-captures

  // Actions
  startCalibration: () => void;
  captureKey: (data: Omit<SoundPrint, 'capturedAt'>) => void;
  forceCaptureKey: (midiNote: number) => void; // Force-capture using current tuner reading
  skipKey: (midiNote: number) => void;
  completeCalibration: () => void;
  cancelCalibration: () => void;
  resetCalibration: () => void;
}

const TOTAL_KEYS = 88;
const MIDI_OFFSET = 21; // A0 = MIDI 21

// Thresholds for flagging
const INHARMONICITY_MODERATE = 0.003;
const INHARMONICITY_HIGH = 0.008;
const DECAY_MODERATE = 800;    // ms — short sustain
const DECAY_HIGH = 400;
const BEATING_MODERATE = 1.5;  // Hz
const BEATING_HIGH = 4.0;
const CENTS_MODERATE = 15;
const CENTS_HIGH = 40;

function evaluateFlags(data: Omit<SoundPrint, 'capturedAt'>): { issues: string[]; level: FlagLevel } {
  const issues: string[] = [];
  let maxLevel: FlagLevel = 'none';

  if (data.inharmonicity >= INHARMONICITY_HIGH) {
    issues.push('high_inharmonicity');
    maxLevel = 'high';
  } else if (data.inharmonicity >= INHARMONICITY_MODERATE) {
    issues.push('moderate_inharmonicity');
    maxLevel = maxLevel === 'none' ? 'moderate' : maxLevel;
  }

  if (data.decayMs <= DECAY_HIGH) {
    issues.push('fast_decay');
    maxLevel = 'high';
  } else if (data.decayMs <= DECAY_MODERATE) {
    issues.push('short_decay');
    maxLevel = maxLevel === 'none' ? 'moderate' : maxLevel;
  }

  if (data.beating >= BEATING_HIGH) {
    issues.push('severe_beating');
    maxLevel = 'high';
  } else if (data.beating >= BEATING_MODERATE) {
    issues.push('moderate_beating');
    maxLevel = maxLevel === 'none' ? 'moderate' : maxLevel;
  }

  const absCents = Math.abs(data.cents);
  if (absCents >= CENTS_HIGH) {
    issues.push('severely_out_of_tune');
    maxLevel = 'high';
  } else if (absCents >= CENTS_MODERATE) {
    issues.push('out_of_tune');
    maxLevel = maxLevel === 'none' ? 'moderate' : maxLevel;
  }

  return { issues, level: maxLevel };
}

function noteNameFromMidi(midi: number): string {
  const names = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
  return names[midi % 12];
}

function octaveFromMidi(midi: number): number {
  return Math.floor(midi / 12) - 1;
}

function initKeyStatuses(): Record<number, KeyStatus> {
  const statuses: Record<number, KeyStatus> = {};
  for (let i = 0; i < TOTAL_KEYS; i++) {
    const midi = MIDI_OFFSET + i;
    statuses[midi] = (i === 0 ? 'current' : 'pending') as KeyStatus;
  }
  return statuses;
}

export const useCalibrationStore = create<CalibrationState>((set, get) => ({
  isCalibrating: false,
  currentMidi: MIDI_OFFSET,
  soundPrints: {},
  keyStatuses: {},
  flaggedKeys: [],
  calibrationStartedAt: null,
  calibrationCompletedAt: null,
  lastCaptureAt: 0,

  startCalibration: () => {
    set({
      isCalibrating: true,
      currentMidi: MIDI_OFFSET,
      soundPrints: {},
      keyStatuses: initKeyStatuses(),
      flaggedKeys: [],
      calibrationStartedAt: Date.now(),
      calibrationCompletedAt: null,
      lastCaptureAt: 0,
    });
  },

  captureKey: (data) => {
    const state = get();
    // Cooldown: minimum 500ms between captures to prevent rapid double-captures
    const now = Date.now();
    if (now - state.lastCaptureAt < 500) return;

    const print: SoundPrint = { ...data, capturedAt: now };
    const midi = data.midiNote;
    const { issues, level } = evaluateFlags(data);

    const newPrints = { ...state.soundPrints, [midi]: print } as Record<number, SoundPrint>;
    const newStatuses = { ...state.keyStatuses, [midi]: (level !== 'none' ? 'flagged' : 'captured') as KeyStatus };

    let newFlagged = state.flaggedKeys;
    if (level !== 'none') {
      // Remove old entry if exists, add new
      newFlagged = newFlagged.filter(f => f.midiNote !== midi);
      newFlagged = [...newFlagged, {
        midiNote: midi,
        noteName: data.noteName,
        octave: data.octave,
        issues,
        level,
      }];
    }

    // Advance to next key
    const nextIndex = midi - MIDI_OFFSET + 1;
    const nextMidi = nextIndex < TOTAL_KEYS ? MIDI_OFFSET + nextIndex : -1;

    if (nextMidi >= MIDI_OFFSET && nextMidi < MIDI_OFFSET + TOTAL_KEYS) {
      (newStatuses as Record<number, KeyStatus>)[nextMidi] = 'current';
    }

    set({
      soundPrints: newPrints,
      keyStatuses: newStatuses,
      flaggedKeys: newFlagged,
      currentMidi: nextMidi,
      lastCaptureAt: now,
    });

    // Auto-complete if all 88 captured
    if (Object.keys(newPrints).length >= TOTAL_KEYS) {
      get().completeCalibration();
    }
  },

  skipKey: (midiNote) => {
    const state = get();
    const newStatuses = { ...state.keyStatuses, [midiNote]: 'captured' as KeyStatus };
    const nextIndex = midiNote - MIDI_OFFSET + 1;
    const nextMidi = nextIndex < TOTAL_KEYS ? MIDI_OFFSET + nextIndex : -1;

    if (nextMidi >= MIDI_OFFSET && nextMidi < MIDI_OFFSET + TOTAL_KEYS) {
      (newStatuses as Record<number, KeyStatus>)[nextMidi] = 'current';
    }

    set({
      keyStatuses: newStatuses,
      currentMidi: nextMidi,
    });
  },

  forceCaptureKey: (midiNote) => {
    // Use current tuner reading to fill the sound print
    const tunerState = useTunerStore.getState();
    const { frequency, noteName, octave, noteNum, cents, idealFreq, isActive } = tunerState;

    if (!isActive || frequency <= 0) {
      // No active reading — skip this key instead
      get().skipKey(midiNote);
      return;
    }

    get().captureKey({
      midiNote,
      noteName: noteName || noteNameFromMidi(midiNote),
      octave: octave ?? octaveFromMidi(midiNote),
      frequency,
      cents: cents ?? 0,
      idealFreq: idealFreq || frequency,
      inharmonicity: 0,
      decayMs: 2000,
      amplitude: 0.5,
      beating: 0,
    });
  },

  completeCalibration: () => {
    const state = get();
    set({
      isCalibrating: false,
      calibrationCompletedAt: Date.now(),
      currentMidi: -1,
    });
  },

  cancelCalibration: () => {
    set({
      isCalibrating: false,
      currentMidi: MIDI_OFFSET,
      soundPrints: {},
      keyStatuses: {},
      flaggedKeys: [],
      calibrationStartedAt: null,
      calibrationCompletedAt: null,
      lastCaptureAt: 0,
    });
  },

  resetCalibration: () => {
    get().cancelCalibration();
  },
}));