// src/components/calibration/InvoiceExport.tsx — Generate PDF and DOCX invoices from piano profiles

import { useState } from 'react';
import { usePianoProfileStore, PianoProfile } from '../../store/pianoProfileStore';

const CURRENCY_SYMBOLS: Record<string, string> = {
  GBP: '£',
  EUR: '€',
  USD: '$',
  BRL: 'R$',
};

const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];

function midiToNoteLabel(midi: number): string {
  const name = NOTE_NAMES[midi % 12];
  const octave = Math.floor(midi / 12) - 1;
  return `${name}${octave}`;
}

function formatDate(ts: number): string {
  return new Date(ts).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
}

function formatDateTime(ts: number): string {
  return new Date(ts).toLocaleString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' });
}

// ─── PDF Generation (jsPDF) ────────────────────────────────────

async function generatePDF(profile: PianoProfile): Promise<void> {
  const { jsPDF } = await import('jspdf');
  const doc = new jsPDF({ unit: 'mm', format: 'a4' });
  const pageW = doc.internal.pageSize.getWidth();
  const margin = 15;
  let y = 20;

  // Colors
  const cyan = [6, 182, 212] as const;
  const dark = [2, 6, 23] as const;
  const slate = [148, 163, 184] as const;
  const white = [226, 232, 240] as const;

  // Header bar
  doc.setFillColor(...dark);
  doc.rect(0, 0, pageW, 40, 'F');
  doc.setTextColor(...cyan);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text('KeyTune', margin, 18);
  doc.setFontSize(10);
  doc.text('Professional Piano Calibration Report', margin, 28);
  doc.setTextColor(...slate);
  doc.setFontSize(7);
  doc.text('www.keytune.app', margin, 35);

  // Invoice number
  const invoiceNum = profile.invoiceNumber || `KT-${profile.id.slice(0, 8).toUpperCase()}`;
  doc.setTextColor(...white);
  doc.setFontSize(11);
  doc.text(`Invoice: ${invoiceNum}`, pageW - margin, 18, { align: 'right' });
  doc.setFontSize(8);
  doc.setTextColor(...slate);
  doc.text(formatDate(profile.calibrationDate), pageW - margin, 24, { align: 'right' });

  y = 50;
  doc.setTextColor(...white);
  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');

  // Client & Piano info — two columns
  doc.setTextColor(...cyan);
  doc.setFontSize(8);
  doc.text('CLIENT', margin, y);
  doc.text('PIANO', pageW / 2 + 5, y);
  y += 5;

  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...white);
  doc.setFontSize(9);
  const clientLines = [
    profile.clientName || 'N/A',
    profile.clientEmail,
    profile.clientPhone,
  ].filter(Boolean);
  clientLines.forEach(line => { doc.text(line, margin, y); y += 4; });

  let yRight = y - clientLines.length * 4;
  const pianoLines = [
    [profile.pianoMake, profile.pianoModel].filter(Boolean).join(' '),
    profile.pianoSerial ? `S/N: ${profile.pianoSerial}` : null,
    profile.pianoYear ? `Year: ${profile.pianoYear}` : null,
    profile.pianoType ? profile.pianoType.replace('_', ' ').toUpperCase() : null,
  ].filter(Boolean) as string[];
  pianoLines.forEach(line => { doc.text(line, pageW / 2 + 5, yRight); yRight += 4; });
  y = Math.max(y, yRight) + 8;

  // Service section
  doc.setFillColor(15, 23, 42);
  doc.roundedRect(margin, y, pageW - margin * 2, 10, 2, 2, 'F');
  doc.setTextColor(...cyan);
  doc.setFontSize(8);
  doc.setFont('helvetica', 'bold');
  doc.text('SERVICE', margin + 3, y + 6.5);
  y += 14;

  doc.setTextColor(...white);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  const serviceLabel = (profile.serviceType || 'calibration').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  doc.text(`${serviceLabel} — Full 88-key calibration assessment`, margin, y);
  y += 5;
  const capturedCount = Object.keys(profile.soundPrints).length;
  doc.text(`${capturedCount} of 88 keys recorded · ${profile.flaggedKeys.length} flagged for attention`, margin, y);
  y += 10;

  // Flagged keys table
  if (profile.flaggedKeys.length > 0) {
    doc.setFillColor(15, 23, 42);
    doc.roundedRect(margin, y, pageW - margin * 2, 8, 2, 2, 'F');
    doc.setTextColor(...cyan);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text('KEYS NEEDING ATTENTION', margin + 3, y + 5.5);
    y += 12;

    // Table header
    doc.setFontSize(7);
    doc.setTextColor(...slate);
    doc.text('KEY', margin, y);
    doc.text('ISSUE', margin + 25, y);
    doc.text('SEVERITY', pageW - margin - 20, y);
    y += 4;

    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...white);
    doc.setFontSize(8);

    profile.flaggedKeys.forEach(fk => {
      if (y > 270) { doc.addPage(); y = 20; }
      doc.text(`${fk.noteName}${fk.octave}`, margin, y);
      doc.text(fk.issues.join(', ').replace(/_/g, ' '), margin + 25, y);
      const sevColor = fk.level === 'high' ? [239, 68, 68] : [234, 179, 8];
      doc.setTextColor(sevColor[0], sevColor[1], sevColor[2]);
      doc.text(fk.level.toUpperCase(), pageW - margin - 20, y);
      doc.setTextColor(white[0], white[1], white[2]);
      y += 5;
    });
    y += 5;
  }

  // Sound print summary
  const prints = Object.values(profile.soundPrints);
  if (prints.length > 0) {
    if (y > 250) { doc.addPage(); y = 20; }
    doc.setFillColor(15, 23, 42);
    doc.roundedRect(margin, y, pageW - margin * 2, 8, 2, 2, 'F');
    doc.setTextColor(...cyan);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text('CALIBRATION SUMMARY', margin + 3, y + 5.5);
    y += 12;

    const avgCents = prints.reduce((s, p) => s + Math.abs(p.cents), 0) / prints.length;
    const worst = prints.reduce((w, p) => Math.abs(p.cents) > Math.abs(w.cents) ? p : w, prints[0]);
    const avgDecay = prints.reduce((s, p) => s + p.decayMs, 0) / prints.length;
    const avgInharm = prints.reduce((s, p) => s + p.inharmonicity, 0) / prints.length;

    doc.setTextColor(...white);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    const summaryItems = [
      ['Average deviation:', `${avgCents.toFixed(1)} cents`],
      ['Worst key:', `${worst.noteName}${worst.octave} (${worst.cents > 0 ? '+' : ''}${worst.cents.toFixed(1)}¢)`],
      ['Average decay:', `${(avgDecay / 1000).toFixed(1)}s`],
      ['Average inharmonicity:', avgInharm.toFixed(4)],
    ];
    summaryItems.forEach(([label, value]) => {
      doc.setTextColor(...slate);
      doc.text(label, margin, y);
      doc.setTextColor(...white);
      doc.text(value, margin + 40, y);
      y += 5;
    });
    y += 5;
  }

  // Tuner notes
  if (profile.tunerNotes) {
    if (y > 250) { doc.addPage(); y = 20; }
    doc.setFillColor(15, 23, 42);
    doc.roundedRect(margin, y, pageW - margin * 2, 8, 2, 2, 'F');
    doc.setTextColor(...cyan);
    doc.setFontSize(8);
    doc.setFont('helvetica', 'bold');
    doc.text('TUNER NOTES', margin + 3, y + 5.5);
    y += 12;
    doc.setTextColor(...white);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    const lines = doc.splitTextToSize(profile.tunerNotes, pageW - margin * 2);
    lines.forEach((line: string) => {
      if (y > 280) { doc.addPage(); y = 20; }
      doc.text(line, margin, y);
      y += 4;
    });
    y += 5;
  }

  // Fee section
  if (y > 250) { doc.addPage(); y = 20; }
  y += 5;
  doc.setDrawColor(30, 41, 59);
  doc.line(margin, y, pageW - margin, y);
  y += 8;

  doc.setTextColor(...white);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  const sym = CURRENCY_SYMBOLS[profile.currency] || profile.currency;
  const feeLine = profile.serviceFee ? `${sym}${profile.serviceFee}` : 'N/A';
  doc.text(`Total: ${feeLine}`, pageW - margin, y, { align: 'right' });
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(...slate);
  y += 5;
  doc.text('Payment due within 30 days. Thank you for choosing KeyTune.', pageW - margin, y, { align: 'right' });

  // Footer
  y = doc.internal.pageSize.getHeight() - 10;
  doc.setFontSize(6);
  doc.setTextColor(...slate);
  doc.text('Generated by KeyTune Pro — Professional Piano Tuner', margin, y);
  doc.text(formatDateTime(Date.now()), pageW - margin, y, { align: 'right' });

  // Save
  const filename = `KeyTune-${invoiceNum}-${profile.clientName.replace(/\s+/g, '-') || 'piano'}-${new Date().toISOString().slice(0, 10)}.pdf`;
  doc.save(filename);
}

// ─── DOCX Generation ──────────────────────────────────────────

async function generateDOCX(profile: PianoProfile): Promise<void> {
  const docx = await import('docx');
  const { Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType, AlignmentType, BorderStyle, HeadingLevel } = docx;

  const capturedCount = Object.keys(profile.soundPrints).length;
  const invoiceNum = profile.invoiceNumber || `KT-${profile.id.slice(0, 8).toUpperCase()}`;
  const sym = CURRENCY_SYMBOLS[profile.currency] || profile.currency;

  const children: any[] = [];

  // Header
  children.push(new Paragraph({
    children: [
      new TextRun({ text: 'KeyTune', bold: true, size: 48, color: '06B6D4' }),
      new TextRun({ text: '  Professional Piano Calibration Report', size: 20, color: '94A3B8' }),
    ],
    spacing: { after: 100 },
  }));

  children.push(new Paragraph({
    children: [
      new TextRun({ text: `Invoice: ${invoiceNum}`, size: 22, bold: true }),
      new TextRun({ text: `    Date: ${formatDate(profile.calibrationDate)}`, size: 18, color: '94A3B8' }),
    ],
    spacing: { after: 200 },
  }));

  // Client info
  children.push(new Paragraph({
    children: [new TextRun({ text: 'CLIENT INFORMATION', bold: true, size: 18, color: '06B6D4' })],
    spacing: { before: 200, after: 100 },
  }));
  const clientInfo = [
    `Name: ${profile.clientName || 'N/A'}`,
    profile.clientEmail ? `Email: ${profile.clientEmail}` : null,
    profile.clientPhone ? `Phone: ${profile.clientPhone}` : null,
  ].filter(Boolean) as string[];
  clientInfo.forEach(line => {
    children.push(new Paragraph({ children: [new TextRun({ text: line, size: 20 })], spacing: { after: 40 } }));
  });

  // Piano info
  children.push(new Paragraph({
    children: [new TextRun({ text: 'PIANO INFORMATION', bold: true, size: 18, color: '06B6D4' })],
    spacing: { before: 200, after: 100 },
  }));
  const pianoInfo = [
    [profile.pianoMake, profile.pianoModel].filter(Boolean).join(' ') || 'Unknown',
    profile.pianoSerial ? `Serial: ${profile.pianoSerial}` : null,
    profile.pianoYear ? `Year: ${profile.pianoYear}` : null,
    profile.pianoType ? `Type: ${profile.pianoType.replace('_', ' ')}` : null,
  ].filter(Boolean) as string[];
  pianoInfo.forEach(line => {
    children.push(new Paragraph({ children: [new TextRun({ text: line, size: 20 })], spacing: { after: 40 } }));
  });

  // Service
  children.push(new Paragraph({
    children: [new TextRun({ text: 'SERVICE', bold: true, size: 18, color: '06B6D4' })],
    spacing: { before: 200, after: 100 },
  }));
  const serviceLabel = (profile.serviceType || 'calibration').replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  children.push(new Paragraph({
    children: [new TextRun({ text: `${serviceLabel} — ${capturedCount}/88 keys assessed · ${profile.flaggedKeys.length} flagged`, size: 20 })],
    spacing: { after: 200 },
  }));

  // Flagged keys table
  if (profile.flaggedKeys.length > 0) {
    children.push(new Paragraph({
      children: [new TextRun({ text: 'KEYS NEEDING ATTENTION', bold: true, size: 18, color: '06B6D4' })],
      spacing: { before: 200, after: 100 },
    }));

    const headerRow = new TableRow({
      children: ['Key', 'Issues', 'Severity'].map(text =>
        new TableCell({
          children: [new Paragraph({ children: [new TextRun({ text, bold: true, size: 18, color: '94A3B8' })] })],
          width: { size: text === 'Issues' ? 60 : 20, type: WidthType.PERCENTAGE },
        })
      ),
    });

    const dataRows = profile.flaggedKeys.map(fk =>
      new TableRow({
        children: [
          new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: `${fk.noteName}${fk.octave}`, size: 20, bold: true })] })] }),
          new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: fk.issues.join(', ').replace(/_/g, ' '), size: 18 })] })] }),
          new TableCell({ children: [new Paragraph({ children: [new TextRun({ text: fk.level.toUpperCase(), size: 18, color: fk.level === 'high' ? 'EF4444' : 'EAB308', bold: true })] })] }),
        ],
      })
    );

    children.push(new Table({
      rows: [headerRow, ...dataRows],
      width: { size: 100, type: WidthType.PERCENTAGE },
    }));
  }

  // Tuner notes
  if (profile.tunerNotes) {
    children.push(new Paragraph({
      children: [new TextRun({ text: 'TUNER NOTES', bold: true, size: 18, color: '06B6D4' })],
      spacing: { before: 200, after: 100 },
    }));
    profile.tunerNotes.split('\n').forEach(line => {
      children.push(new Paragraph({ children: [new TextRun({ text: line, size: 20 })], spacing: { after: 40 } }));
    });
  }

  // Fee
  if (profile.serviceFee) {
    children.push(new Paragraph({
      children: [new TextRun({ text: `Total: ${sym}${profile.serviceFee}`, bold: true, size: 28 })],
      alignment: AlignmentType.RIGHT,
      spacing: { before: 400 },
    }));
  }

  // Footer
  children.push(new Paragraph({
    children: [new TextRun({ text: 'Generated by KeyTune Pro — Professional Piano Tuner', size: 14, color: '94A3B8' })],
    alignment: AlignmentType.CENTER,
    spacing: { before: 400 },
  }));

  const doc = new Document({
    sections: [{ children }],
  });

  const blob = await Packer.toBlob(doc);
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `KeyTune-${invoiceNum}-${profile.clientName.replace(/\s+/g, '-') || 'piano'}-${new Date().toISOString().slice(0, 10)}.docx`;
  a.click();
  URL.revokeObjectURL(url);
}

// ─── Component ────────────────────────────────────────────────

interface Props {
  profile: PianoProfile;
  onBack?: () => void;
}

export function InvoiceExport({ profile, onBack }: Props) {
  const [exporting, setExporting] = useState<'pdf' | 'docx' | null>(null);

  const invoiceNum = profile.invoiceNumber || `KT-${profile.id.slice(0, 8).toUpperCase()}`;
  const sym = CURRENCY_SYMBOLS[profile.currency] || profile.currency;
  const capturedCount = Object.keys(profile.soundPrints).length;

  const handlePDF = async () => {
    setExporting('pdf');
    try {
      await generatePDF(profile);
    } catch (err) {
      console.error('PDF generation failed:', err);
    }
    setExporting(null);
  };

  const handleDOCX = async () => {
    setExporting('docx');
    try {
      await generateDOCX(profile);
    } catch (err) {
      console.error('DOCX generation failed:', err);
    }
    setExporting(null);
  };

  return (
    <div className="bg-slate-800/30 rounded-xl border border-slate-700/30 p-4 space-y-4">
      {/* Preview header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-sm font-bold font-['Orbitron'] text-slate-200">Invoice {invoiceNum}</h3>
          <p className="text-[10px] text-slate-400 mt-1">
            {profile.clientName} · {profile.pianoMake} {profile.pianoModel} · {capturedCount} keys · {profile.flaggedKeys.length} flagged
          </p>
        </div>
        {profile.serviceFee && (
          <div className="text-right">
            <span className="text-lg font-bold text-cyan-400 font-['Orbitron']">{sym}{profile.serviceFee}</span>
            <div className="text-[10px] text-slate-500">{profile.currency}</div>
          </div>
        )}
      </div>

      {/* Export buttons */}
      <div className="flex gap-3">
        <button
          onClick={handlePDF}
          disabled={!!exporting}
          className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 ${
            exporting === 'pdf'
              ? 'bg-red-500/10 text-red-400 border border-red-500/20'
              : 'bg-red-500/15 text-red-400 border border-red-500/30 hover:bg-red-500/25'
          }`}
        >
          {exporting === 'pdf' ? '⏳ Generating...' : '📄 Export PDF'}
        </button>
        <button
          onClick={handleDOCX}
          disabled={!!exporting}
          className={`flex-1 py-2.5 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 ${
            exporting === 'docx'
              ? 'bg-blue-500/10 text-blue-400 border border-blue-500/20'
              : 'bg-blue-500/15 text-blue-400 border border-blue-500/30 hover:bg-blue-500/25'
          }`}
        >
          {exporting === 'docx' ? '⏳ Generating...' : '📝 Export DOCX'}
        </button>
      </div>

      {onBack && (
        <button
          onClick={onBack}
          className="w-full py-2 text-xs text-slate-500 hover:text-slate-300 transition-colors"
        >
          ← Back to profiles
        </button>
      )}
    </div>
  );
}