// src/store/sessionStore.ts — Professional tuning session state with notes, client, piano info

import { create } from 'zustand';

export interface TunedNote {
  noteName: string;
  octave: number;
  frequency: number;
  cents: number;
  idealFreq: number;
  timestamp: number;
  manuallyLogged?: boolean;
}

export interface SessionNote {
  id: string;
  text: string;
  timestamp: number;
  noteNumber?: number; // optional: attach to a specific key
}

export interface SessionState {
  // Session metadata (professional workflow)
  clientName: string;
  pianoMake: string;
  pianoModel: string;
  pianoSerial: string;
  sessionNotes: SessionNote[];
  sessionStartedAt: number | null;

  // Tuning records
  records: Record<number, TunedNote>;
  autoRecordEnabled: boolean;

  // Actions
  setClientName: (name: string) => void;
  setPianoMake: (make: string) => void;
  setPianoModel: (model: string) => void;
  setPianoSerial: (serial: string) => void;
  addSessionNote: (text: string, noteNumber?: number) => void;
  removeSessionNote: (id: string) => void;
  startSession: () => void;
  recordNote: (midiNote: number, data: TunedNote) => void;
  removeNote: (midiNote: number) => void;
  clearSession: () => void;
  autoRecord: (enabled: boolean) => void;
}

const SESSION_KEY = 'keytune-session';

function loadSession(): Partial<SessionState> {
  try {
    const raw = localStorage.getItem(SESSION_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveSession(state: SessionState): void {
  try {
    localStorage.setItem(SESSION_KEY, JSON.stringify({
      clientName: state.clientName,
      pianoMake: state.pianoMake,
      pianoModel: state.pianoModel,
      pianoSerial: state.pianoSerial,
      sessionNotes: state.sessionNotes,
      sessionStartedAt: state.sessionStartedAt,
      records: state.records,
    }));
  } catch {
    // silent
  }
}

const saved = loadSession();

export const useSessionStore = create<SessionState>((set, get) => ({
  clientName: saved.clientName ?? '',
  pianoMake: saved.pianoMake ?? '',
  pianoModel: saved.pianoModel ?? '',
  pianoSerial: saved.pianoSerial ?? '',
  sessionNotes: saved.sessionNotes ?? [],
  sessionStartedAt: saved.sessionStartedAt ?? null,
  records: saved.records ?? {},
  autoRecordEnabled: false,

  setClientName: (clientName) => { set({ clientName }); saveSession(get()); },
  setPianoMake: (pianoMake) => { set({ pianoMake }); saveSession(get()); },
  setPianoModel: (pianoModel) => { set({ pianoModel }); saveSession(get()); },
  setPianoSerial: (pianoSerial) => { set({ pianoSerial }); saveSession(get()); },

  addSessionNote: (text, noteNumber) => {
    set((state) => {
      const sessionNotes = [...state.sessionNotes, {
        id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
        text,
        timestamp: Date.now(),
        noteNumber,
      }];
      saveSession({ ...state, sessionNotes } as SessionState);
      return { sessionNotes };
    });
  },

  removeSessionNote: (id) => {
    set((state) => {
      const sessionNotes = state.sessionNotes.filter(n => n.id !== id);
      saveSession({ ...state, sessionNotes } as SessionState);
      return { sessionNotes };
    });
  },

  startSession: () => {
    set({ sessionStartedAt: Date.now() });
    saveSession(get());
  },

  recordNote: (midiNote, data) => {
    set((state) => {
      const records = { ...state.records, [midiNote]: data };
      saveSession({ ...state, records } as SessionState);
      return { records };
    });
  },

  removeNote: (midiNote) => {
    set((state) => {
      const { [midiNote]: _, ...records } = state.records;
      saveSession({ ...state, records } as SessionState);
      return { records };
    });
  },

  clearSession: () => {
    set({
      records: {},
      sessionNotes: [],
      sessionStartedAt: null,
      clientName: '',
      pianoMake: '',
      pianoModel: '',
      pianoSerial: '',
    });
    localStorage.removeItem(SESSION_KEY);
  },

  autoRecord: (autoRecordEnabled) => {
    set({ autoRecordEnabled });
  },
}));