// src/components/tuner/TuningMeter.tsx — Compact arc meter, persistent needle
// FIX: Uses refs for Zustand values. Needle stays visible and decays slowly
// when pitch is lost instead of vanishing instantly.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { useSettingsStore } from '../../store/settingsStore';
import { formatHz, formatCents } from '../../audio/NoteUtils';

const ARC_START = Math.PI * 0.75;
const ARC_END = Math.PI * 2.25;
const ARC_RANGE = ARC_END - ARC_START;

export function TuningMeter() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const needleRef = useRef(0);
  const glowRef = useRef(0);
  const lastPitchRef = useRef({ noteName: '', octave: 0, cents: 0, frequency: 0, idealFreq: 0, active: false, fadeAlpha: 0 });

  const storeRef = useRef(useTunerStore.getState());
  const settingsRef = useRef(useSettingsStore.getState());

  storeRef.current = useTunerStore();
  settingsRef.current = useSettingsStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const { cents, isActive, noteName, octave, frequency, idealFreq } = storeRef.current;
      const { sensitivity, tuningMode } = settingsRef.current;
      const isStretch = tuningMode === 'stretch';
      const last = lastPitchRef.current;

      if (isActive) {
        last.noteName = noteName;
        last.octave = octave;
        last.cents = cents;
        last.frequency = frequency;
        last.idealFreq = idealFreq;
        last.active = true;
        last.fadeAlpha = 1;
      } else if (last.active) {
        last.fadeAlpha -= 0.005;
        if (last.fadeAlpha <= 0) { last.active = false; last.fadeAlpha = 0; }
      }

      const showActive = isActive || last.active;
      const showCents = isActive ? cents : last.cents;
      const showNoteName = isActive ? noteName : last.noteName;
      const showOctave = isActive ? octave : last.octave;
      const showFrequency = isActive ? frequency : last.frequency;
      const showIdealFreq = isActive ? idealFreq : last.idealFreq;
      const showAlpha = isActive ? 1 : last.fadeAlpha;

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);

      const w = rect.width;
      const h = rect.height;
      const cx = w / 2;
      const cy = h * 0.48;
      const radius = Math.min(w * 0.33, h * 0.40);

      // Clear
      ctx.fillStyle = '#020617';
      ctx.fillRect(0, 0, w, h);

      // Radial glow
      if (showActive) {
        const absC = Math.abs(showCents);
        const glowColor = absC <= 2 ? 'rgba(34, 197, 94,' : absC <= 8 ? 'rgba(234, 179, 8,' : 'rgba(239, 68, 68,';
        const glowIntensity = Math.min(1, absC / 20) * 0.15 * showAlpha;
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, radius * 1.3);
        grad.addColorStop(0, glowColor + glowIntensity + ')');
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.fillRect(0, 0, w, h);
      }

      // Outer ring
      ctx.beginPath();
      ctx.arc(cx, cy, radius + 5, ARC_START, ARC_END);
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 2;
      ctx.stroke();

      // Zone arcs
      drawArcSegment(ctx, cx, cy, radius, -2, 2, '#22c55e', 0.7);
      drawArcSegment(ctx, cx, cy, radius, -8, -2, '#eab308', 0.45);
      drawArcSegment(ctx, cx, cy, radius, +2, +8, '#eab308', 0.45);
      drawArcSegment(ctx, cx, cy, radius, -20, -8, '#f97316', 0.25);
      drawArcSegment(ctx, cx, cy, radius, +8, +20, '#f97316', 0.25);
      drawArcSegment(ctx, cx, cy, radius, -50, -20, '#ef4444', 0.15);
      drawArcSegment(ctx, cx, cy, radius, +20, +50, '#ef4444', 0.15);

      // Tick marks
      for (let c = -50; c <= 50; c += 2) {
        const angle = centsToAngle(c);
        const isMajor = c % 10 === 0;
        const isMid = c % 5 === 0 && !isMajor;
        const outerR = radius + 3;
        const innerR = radius - (isMajor ? 12 : isMid ? 7 : 3);
        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(angle) * innerR, cy + Math.sin(angle) * innerR);
        ctx.lineTo(cx + Math.cos(angle) * outerR, cy + Math.sin(angle) * outerR);
        if (isMajor) { ctx.lineWidth = 1.5; ctx.strokeStyle = '#94a3b8'; }
        else if (isMid) { ctx.lineWidth = 1; ctx.strokeStyle = '#64748b'; }
        else { ctx.lineWidth = 0.5; ctx.strokeStyle = '#475569'; }
        ctx.stroke();
      }

      // Cents labels
      for (let c = -50; c <= 50; c += 10) {
        const angle = centsToAngle(c);
        const labelR = radius - 20;
        ctx.fillStyle = c === 0 ? '#e2e8f0' : '#64748b';
        ctx.font = c === 0 ? 'bold 10px "Share Tech Mono", monospace' : '8px "Share Tech Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const label = c === 0 ? '0' : (c > 0 ? `+${c}` : `${c}`);
        ctx.fillText(label, cx + Math.cos(angle) * labelR, cy + Math.sin(angle) * labelR);
      }

      // Needle animation
      const speed = sensitivity === 'slow' ? 0.08 : sensitivity === 'fast' ? 0.3 : 0.15;
      const targetCents = Math.max(-50, Math.min(50, showActive ? showCents : 0));
      if (isActive) {
        needleRef.current = needleRef.current * (1 - speed) + targetCents * speed;
      } else if (last.active) {
        needleRef.current = needleRef.current * (1 - 0.02);
      }
      const targetGlow = showActive ? 1 : 0;
      glowRef.current += (targetGlow - glowRef.current) * (showActive ? 0.1 : 0.02);

      if (glowRef.current > 0.005) {
        const needleAngle = centsToAngle(needleRef.current);
        const absCents = Math.abs(needleRef.current);
        let needleColor: string;
        if (absCents <= 2) needleColor = '#22c55e';
        else if (absCents <= 8) needleColor = '#eab308';
        else if (absCents <= 20) needleColor = '#f97316';
        else needleColor = '#ef4444';

        ctx.save();
        ctx.globalAlpha = Math.min(1, glowRef.current * 1.5);
        ctx.shadowColor = needleColor;
        ctx.shadowBlur = 10 * glowRef.current;
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        const nx = cx + Math.cos(needleAngle) * (radius - 8);
        const ny = cy + Math.sin(needleAngle) * (radius - 8);
        ctx.lineTo(nx, ny);
        ctx.strokeStyle = needleColor;
        ctx.lineWidth = 2;
        ctx.stroke();
        ctx.restore();
        ctx.globalAlpha = Math.min(1, glowRef.current * 1.5);
        ctx.beginPath();
        ctx.arc(nx, ny, 2.5, 0, Math.PI * 2);
        ctx.fillStyle = needleColor;
        ctx.fill();
        ctx.globalAlpha = 1;
      }

      // Center hub
      ctx.beginPath();
      ctx.arc(cx, cy, 5, 0, Math.PI * 2);
      const hubGrad = ctx.createRadialGradient(cx, cy, 0, cx, cy, 5);
      hubGrad.addColorStop(0, '#e2e8f0');
      hubGrad.addColorStop(1, '#475569');
      ctx.fillStyle = hubGrad;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(cx, cy, 2, 0, Math.PI * 2);
      ctx.fillStyle = '#020617';
      ctx.fill();

      // === STROBOSCOPIC SPINNERS — concentric ring display ===
      // Each ring = 1 harmonic. Bars spin CW if sharp, CCW if flat.
      // Speed proportional to cents deviation. Frozen when in tune.
      if (showActive && showAlpha > 0.1) {
        const now = Date.now() / 1000; // time in seconds for animation
        const spinnerInnerR = 18; // start radius (just outside hub)
        const spinnerOuterR = Math.min(radius * 0.55, 45); // max radius
        const harmonics = [1, 2, 3, 4, 5]; // harmonic numbers
        const barCountPerRing = 16;

        ctx.save();
        ctx.globalAlpha = showAlpha * 0.8;

        harmonics.forEach((h, hIdx) => {
          const ringR = spinnerInnerR + (spinnerOuterR - spinnerInnerR) * (hIdx / (harmonics.length - 1));
          const barLen = 4 + (spinnerOuterR - spinnerInnerR) / harmonics.length * 0.6;
          // Cents deviation scaled by harmonic number — higher harmonics show more deviation
          const hCents = showCents * h;
          // Angular speed: radians/sec proportional to cents (1¢ = ~0.05 rad/s for visual effect)
          const spinSpeed = hCents * 0.05;
          // Base angle offset per ring so bars don't align
          const offset = (hIdx * Math.PI / harmonics.length);

          for (let b = 0; b < barCountPerRing; b++) {
            const baseAngle = (b / barCountPerRing) * Math.PI * 2;
            const angle = baseAngle + offset + now * spinSpeed;

            const x1 = cx + Math.cos(angle) * (ringR - barLen / 2);
            const y1 = cy + Math.sin(angle) * (ringR - barLen / 2);
            const x2 = cx + Math.cos(angle) * (ringR + barLen / 2);
            const y2 = cy + Math.sin(angle) * (ringR + barLen / 2);

            // Color by proximity to in-tune (frozen = green, spinning = cyan/amber)
            const absHCents = Math.abs(hCents);
            let barColor: string;
            if (absHCents <= 2) barColor = 'rgba(34, 197, 94, 0.7)';       // green — in tune
            else if (absHCents <= 8) barColor = 'rgba(234, 179, 8, 0.5)';   // amber — slightly off
            else barColor = 'rgba(6, 182, 212, 0.4)';                        // cyan — noticeably off

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.strokeStyle = barColor;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            ctx.stroke();
          }
        });

        // Harmonic number label (small, bottom-right of spinners)
        ctx.fillStyle = 'rgba(100, 116, 139, 0.5)';
        ctx.font = '7px "Share Tech Mono", monospace';
        ctx.textAlign = 'right';
        ctx.textBaseline = 'bottom';
        ctx.fillText('H:1-5', cx + spinnerOuterR + 2, cy + spinnerOuterR);
        ctx.restore();
      }

      // === INFO INSIDE THE ARC — tight packing ===
      const iY = cy + 4;

      if (!showActive) {
        // Stretch tuning indicator
        if (isStretch) {
          ctx.fillStyle = 'rgba(6, 182, 212, 0.6)';
          ctx.font = 'bold 7px "Exo 2", sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'top';
          ctx.fillText('⟡ STRETCH', cx, iY - 10);
        }

        ctx.fillStyle = '#475569';
        ctx.font = '10px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText('Tap mic to start', cx, iY + 2);

        ctx.fillStyle = '#334155';
        ctx.font = 'bold 28px "Orbitron", sans-serif';
        ctx.fillText('—', cx, iY + 14);

        ctx.font = '10px "Share Tech Mono", monospace';
        ctx.fillText('— Hz   —¢', cx, iY + 44);
      } else {
        const c = Math.round(showCents);

        // Stretch tuning indicator
        if (isStretch) {
          ctx.fillStyle = 'rgba(6, 182, 212, 0.6)';
          ctx.font = 'bold 7px "Exo 2", sans-serif';
          ctx.textAlign = 'center';
          ctx.textBaseline = 'top';
          ctx.fillText('⟡ STRETCH', cx, iY - 10);
        }

        const abs = Math.abs(c);
        let badgeText: string, badgeColor: string, badgeBg: string;

        if (abs <= 2) { badgeText = '♪ IN TUNE'; badgeColor = '#22c55e'; badgeBg = 'rgba(34, 197, 94, 0.15)'; }
        else {
          const dir = c < 0 ? '♭ FLAT' : '♯ SHARP';
          if (abs <= 8) { badgeText = dir; badgeColor = '#eab308'; badgeBg = 'rgba(234, 179, 8, 0.15)'; }
          else if (abs <= 20) { badgeText = dir; badgeColor = '#f97316'; badgeBg = 'rgba(249, 115, 22, 0.15)'; }
          else { badgeText = dir; badgeColor = '#ef4444'; badgeBg = 'rgba(239, 68, 68, 0.15)'; }
        }

        ctx.globalAlpha = showAlpha;

        // Badge
        ctx.font = 'bold 8px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        const badgeW = ctx.measureText(badgeText).width + 14;
        const badgeH = 14;
        ctx.fillStyle = badgeBg;
        ctx.beginPath();
        ctx.roundRect(cx - badgeW / 2, iY, badgeW, badgeH, 7);
        ctx.fill();
        ctx.strokeStyle = badgeColor + '4D';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.roundRect(cx - badgeW / 2, iY, badgeW, badgeH, 7);
        ctx.stroke();
        ctx.fillStyle = badgeColor;
        ctx.fillText(badgeText, cx, iY + badgeH / 2);

        if (abs <= 2) {
          ctx.fillStyle = `rgba(34,197,94,${0.15 + 0.1 * Math.sin(Date.now() / 400)})`;
          ctx.beginPath();
          ctx.roundRect(cx - badgeW / 2, iY, badgeW, badgeH, 7);
          ctx.fill();
        }

        // Note name
        const noteGlow = abs <= 2 ? '#22c55e' : abs <= 8 ? '#eab308' : '#e2e8f0';
        ctx.save();
        ctx.shadowColor = noteGlow;
        ctx.shadowBlur = abs <= 2 ? 14 : abs <= 8 ? 8 : 3;
        ctx.fillStyle = abs <= 2 ? '#4ade80' : abs <= 8 ? '#facc15' : '#e2e8f0';
        ctx.font = 'bold 32px "Orbitron", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(showNoteName || '—', cx - 5, iY + 16);
        ctx.restore();

        // Octave
        ctx.fillStyle = '#94a3b8';
        ctx.font = 'bold 14px "Orbitron", sans-serif';
        ctx.textAlign = 'left';
        ctx.textBaseline = 'top';
        ctx.fillText(String(showOctave || ''), cx + 14, iY + 26);

        // Cents
        const absC = Math.abs(Math.round(showCents));
        let centsColor: string;
        if (absC <= 2) centsColor = '#4ade80';
        else if (absC <= 8) centsColor = '#facc15';
        else if (absC <= 20) centsColor = '#fb923c';
        else centsColor = '#f87171';

        ctx.fillStyle = centsColor;
        ctx.font = 'bold 20px "Share Tech Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(formatCents(showCents), cx, iY + 48);

        // "cents" label
        ctx.fillStyle = '#64748b';
        ctx.font = '7px "Exo 2", sans-serif';
        ctx.fillText('cents', cx, iY + 68);

        // Frequency + target on same row to save space
        ctx.fillStyle = '#94a3b8';
        ctx.font = '10px "Share Tech Mono", monospace';
        ctx.fillText(formatHz(showFrequency) + ' Hz', cx, iY + 76);

        if (showIdealFreq > 0) {
          ctx.fillStyle = '#475569';
          ctx.font = '8px "Share Tech Mono", monospace';
          ctx.fillText('target: ' + formatHz(showIdealFreq) + ' Hz', cx, iY + 86);
        }

        ctx.globalAlpha = 1;
      }

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="w-full max-w-md"
      style={{ aspectRatio: '7/4.4', imageRendering: 'auto' }}
    />
  );
}

function centsToAngle(cents: number): number {
  return ARC_START + ((cents + 50) / 100) * ARC_RANGE;
}

function drawArcSegment(
  ctx: CanvasRenderingContext2D,
  cx: number, cy: number, radius: number,
  fromCents: number, toCents: number,
  color: string, alpha: number
) {
  ctx.beginPath();
  ctx.arc(cx, cy, radius + 1, centsToAngle(fromCents), centsToAngle(toCents));
  ctx.strokeStyle = color;
  ctx.lineWidth = 5;
  ctx.globalAlpha = alpha;
  ctx.lineCap = 'butt';
  ctx.stroke();
  ctx.globalAlpha = 1;
}