// src/components/tuner/FreqSpectrumDetailed.tsx — Detailed FFT spectrum with labeled frequency axis and peak markers.

import { useRef, useEffect } from 'react';
import { useTunerStore } from '../../store/tunerStore';
import { getSharedAnalyser, getSharedAudioContext } from '../../audio/AudioEngine';

export function FreqSpectrumDetailed() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const animRef = useRef<number>(0);
  const smoothData = useRef<Float32Array | null>(null);

  const storeRef = useRef(useTunerStore.getState());
  storeRef.current = useTunerStore();

  useEffect(() => {
    const draw = () => {
      const canvas = canvasRef.current;
      if (!canvas) { animRef.current = requestAnimationFrame(draw); return; }
      const ctx = canvas.getContext('2d');
      if (!ctx) { animRef.current = requestAnimationFrame(draw); return; }

      const dpr = window.devicePixelRatio || 1;
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * dpr;
      canvas.height = rect.height * dpr;
      ctx.scale(dpr, dpr);
      const w = rect.width;
      const h = rect.height;

      // Background
      ctx.fillStyle = '#0a0f1e';
      ctx.fillRect(0, 0, w, h);

      const { isListening, frequency } = storeRef.current;
      const analyser = getSharedAnalyser();
      const audioCtx = getSharedAudioContext();

      if (!isListening || !analyser || !audioCtx) {
        ctx.fillStyle = '#475569';
        ctx.font = '11px "Exo 2", sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('Freq Spectrum', w / 2, h / 2);
        animRef.current = requestAnimationFrame(draw);
        return;
      }

      const sampleRate = audioCtx.sampleRate;
      const fftSize = analyser.fftSize;
      const binHz = sampleRate / fftSize;
      const bufferLength = analyser.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyser.getByteFrequencyData(dataArray);

      // Initialize smooth data
      if (!smoothData.current || smoothData.current.length !== bufferLength) {
        smoothData.current = new Float32Array(bufferLength);
      }

      // Smooth with EMA
      for (let i = 0; i < bufferLength; i++) {
        smoothData.current[i] = smoothData.current[i] * 0.75 + (dataArray[i] / 255) * 0.25;
      }

      // Piano-relevant range: ~27 Hz to ~4200 Hz
      const minFreq = 27;
      const maxFreq = 4200;
      const minBin = Math.floor(minFreq / binHz);
      const maxBin = Math.min(Math.ceil(maxFreq / binHz), bufferLength - 1);

      const padding = { left: 30, right: 8, top: 14, bottom: 18 };
      const chartW = w - padding.left - padding.right;
      const chartH = h - padding.top - padding.bottom;

      // Grid lines - frequency markers
      const freqMarkers = [50, 100, 200, 440, 1000, 2000, 4000];
      ctx.fillStyle = '#475569';
      ctx.font = '7px "Share Tech Mono", monospace';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';

      freqMarkers.forEach(fm => {
        const x = padding.left + (Math.log2(fm / minFreq) / Math.log2(maxFreq / minFreq)) * chartW;
        if (x < padding.left || x > w - padding.right) return;

        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(x, padding.top);
        ctx.lineTo(x, h - padding.bottom);
        ctx.stroke();

        const label = fm >= 1000 ? `${fm / 1000}k` : `${fm}`;
        ctx.fillText(label, x, h - padding.bottom + 4);
      });

      // dB grid lines
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let db = 0; db >= -60; db -= 20) {
        const y = padding.top + chartH * (-db / 80);
        ctx.strokeStyle = '#1e293b';
        ctx.lineWidth = 0.5;
        ctx.beginPath();
        ctx.moveTo(padding.left, y);
        ctx.lineTo(w - padding.right, y);
        ctx.stroke();
        ctx.fillText(`${db}`, padding.left - 3, y);
      }

      // Draw spectrum line
      ctx.beginPath();
      let firstPoint = true;
      for (let bin = minBin; bin <= maxBin; bin++) {
        const freq = bin * binHz;
        const norm = Math.log2(freq / minFreq) / Math.log2(maxFreq / minFreq);
        const x = padding.left + norm * chartW;
        let amplitude = smoothData.current[bin];
        // Normalize: 1.0 = 0dB, 0.0 = -80dB floor
        const dbApprox = (amplitude - 1) * 60; // rough dB estimate
        const y = padding.top + chartH * Math.min(1, Math.max(0, -dbApprox / 80));

        if (firstPoint) { ctx.moveTo(x, y); firstPoint = false; }
        else ctx.lineTo(x, y);
      }

      // Gradient fill
      const grad = ctx.createLinearGradient(0, padding.top, 0, h - padding.bottom);
      grad.addColorStop(0, 'rgba(6, 182, 212, 0.6)');
      grad.addColorStop(0.5, 'rgba(6, 182, 212, 0.2)');
      grad.addColorStop(1, 'rgba(6, 182, 212, 0.02)');

      // Fill area under curve
      const lastX = padding.left + chartW;
      ctx.lineTo(lastX, h - padding.bottom);
      ctx.lineTo(padding.left, h - padding.bottom);
      ctx.closePath();
      ctx.fillStyle = grad;
      ctx.fill();

      // Stroke line on top
      ctx.beginPath();
      firstPoint = true;
      for (let bin = minBin; bin <= maxBin; bin++) {
        const freq = bin * binHz;
        const norm = Math.log2(freq / minFreq) / Math.log2(maxFreq / minFreq);
        const x = padding.left + norm * chartW;
        let amplitude = smoothData.current[bin];
        const dbApprox = (amplitude - 1) * 60;
        const y = padding.top + chartH * Math.min(1, Math.max(0, -dbApprox / 80));
        if (firstPoint) { ctx.moveTo(x, y); firstPoint = false; }
        else ctx.lineTo(x, y);
      }
      ctx.strokeStyle = '#06b6d4';
      ctx.lineWidth = 1.5;
      ctx.stroke();

      // Peak marker for detected fundamental
      if (frequency > 0) {
        const fundNorm = Math.log2(frequency / minFreq) / Math.log2(maxFreq / minFreq);
        const fundX = padding.left + fundNorm * chartW;

        // Vertical line
        ctx.strokeStyle = 'rgba(239, 68, 68, 0.6)';
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(fundX, padding.top);
        ctx.lineTo(fundX, h - padding.bottom);
        ctx.stroke();
        ctx.setLineDash([]);

        // Label
        ctx.fillStyle = '#ef4444';
        ctx.font = 'bold 7px "Share Tech Mono", monospace';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'bottom';
        ctx.fillText(`${Math.round(frequency)} Hz`, fundX, padding.top - 1);
      }

      // Axis label
      ctx.fillStyle = '#475569';
      ctx.font = '7px "Exo 2", sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText('dB', 2, padding.top);

      animRef.current = requestAnimationFrame(draw);
    };

    animRef.current = requestAnimationFrame(draw);
    return () => cancelAnimationFrame(animRef.current);
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="w-full h-full rounded-lg border border-slate-800"
    />
  );
}